    /**
     * @method
     * @name binance#tokenizedConvertHistory
     * @ignore
     * @description check the history of redeeming or minting between a tokenized stock asset and the underlying asset
     * @see https://developers.binance.com/en/docs/catalog/advanced-trading-stocks-trading/api/rest-api/tokenized#tokenized-convert-history
     * @param {int} [since] timestamp in ms of the earliest conversion to fetch
     * @param {int} [limit] the maximum amount of conversions to fetch
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {int} [params.recvWindow] cannot be greater than 60000
     * @param {int} [params.endTime] timestamp in ms of the latest conversion to fetch
     * @param {int} [params.lastTradeTokenId] last record id from the previous page
     * @returns {object} the response from the exchange
     */
    virtual std::any tokenizedConvertHistory(std::any since = std::any{}, std::any limit = std::any{}, std::any params = ccxt::dict {})
    {
        std::any request = ccxt::dict {
            { std::string("timestamp"), this->milliseconds() },
        };
        if (isTrue(!isEqual(since, std::any{})))
        {
            ::setValue(request, std::string("startTime"), since);
        }
        if (isTrue(!isEqual(limit, std::any{})))
        {
            ::setValue(request, std::string("size"), limit);
        }
        std::any requestparamsVariable = this->handleUntilOption(std::string("endTime"), request, params);
        request = ::getValue(requestparamsVariable, 0);
        params = ::getValue(requestparamsVariable, 1);
        std::any response = this->sapiGetEquityTokenizedHistory(this->extend(request, params));
        //
        //     {
        //         "rows": [
        //             {
        //                 "underlyingAsset": "AAPL",
        //                 "underlyingAssetAmount": "0.0576724",
        //                 "tokenizedAsset": "AAPLB",
        //                 "tokenizedAssetAmount": "0.0576724",
        //                 "issuerRequestId": "d9a01aa5-c8b0-46bb-bc58-43b7e122ec20",
        //                 "convertType": "REDEEM",
        //                 "status": "S",
        //                 "createdAt": "1785986980000",
        //                 "updatedAt": "1785986980000"
        //             }
        //         ],
        //         "hasMore": true,
        //         "nextLastId": "5167862022496942848"
        //     }
        //
        return response;
    }

    /**
     * @method
     * @name binance#enableDemoTrading
     * @description enables or disables demo trading mode
     * @see https://www.binance.com/en/support/faq/detail/9be58f73e5e14338809e3b705b9687dd
     * @see https://demo.binance.com/en/my/settings/api-management
     * @param {boolean} [enable] true if demo trading should be enabled, false otherwise
     */
    void enableDemoTrading(std::any enable) override
    {
        if (isTrue(this->isSandboxModeEnabled))
        {
            throw NotSupported(toString(add(this->id, std::string(" demo trading is not supported in the sandbox environment. Please check https://www.binance.com/en/support/faq/detail/9be58f73e5e14338809e3b705b9687dd to see the differences"))));
        }
        if (isTrue(enable))
        {
            ::setValue(this->urls, std::string("apiBackupDemoTrading"), ::getValue(this->urls, std::string("api")));
            ::setValue(this->urls, std::string("api"), ::getValue(this->urls, std::string("demo")));
        } else if (isTrue(inOp(this->urls, std::string("apiBackupDemoTrading"))))
        {
            ::setValue(this->urls, std::string("api"), ::getValue(this->urls, std::string("apiBackupDemoTrading")));
            std::any newUrls = this->omit(this->urls, std::string("apiBackupDemoTrading"));
            this->urls = newUrls;
        }
        ::setValue(this->options, std::string("enableDemoTrading"), enable);
    }

    /**
     * @method
     * @name binance#fetchTime
     * @description fetches the current integer timestamp in milliseconds from the exchange server
     * @see https://developers.binance.com/docs/binance-spot-api-docs/rest-api/general-endpoints#check-server-time          // spot
     * @see https://developers.binance.com/docs/derivatives/usds-margined-futures/market-data/rest-api/Check-Server-Time    // swap
     * @see https://developers.binance.com/docs/derivatives/coin-margined-futures/market-data/rest-api/Check-Server-time    // future
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {string} [params.subType] "linear" or "inverse"
     * @returns {int} the current integer timestamp in milliseconds from the exchange server
     */
    std::shared_future<std::any> fetchTime(std::any params = ccxt::dict {}) override
    {
        return std::async(std::launch::deferred, [=]() mutable -> std::any {
            std::any defaultType = this->safeString2(this->options, std::string("fetchTime"), std::string("defaultType"), std::string("spot"));
            std::any type = this->safeString(params, std::string("type"), defaultType);
            std::any query = this->omit(params, std::string("type"));
            std::any subType = std::any{};
            std::any subTypeparamsVariable = this->handleSubTypeAndParams(std::string("fetchTime"), std::any{}, params);
            subType = ::getValue(subTypeparamsVariable, 0);
            params = ::getValue(subTypeparamsVariable, 1);
            std::any response = std::any{};
            if (isTrue(this->isLinear(type, subType)))
            {
                response = awaitValue(this->fapiPublicGetTime(query));
            } else if (isTrue(this->isInverse(type, subType)))
            {
                response = awaitValue(this->dapiPublicGetTime(query));
            } else
            {
                response = awaitValue(this->publicGetTime(query));
            }
            return this->safeInteger(response, std::string("serverTime"));
        }).share();
    }

    /**
     * @method
     * @name binance#fetchCurrencies
     * @description fetches all available currencies on an exchange
     * @see https://developers.binance.com/docs/wallet/capital/all-coins-info
     * @see https://developers.binance.com/docs/margin_trading/market-data/Get-All-Margin-Assets
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} an associative dictionary of currencies
     */
    std::shared_future<std::any> fetchCurrencies(std::any params = ccxt::dict {}) override
    {
        return std::async(std::launch::deferred, [=]() mutable -> std::any {
            std::any fetchCurrenciesEnabled = this->safeBool(this->options, std::string("fetchCurrencies"));
            if (isTrue(!isEqual(fetchCurrenciesEnabled, true)))
            {
                return ccxt::dict {};
            }
            // this endpoint requires authentication
            // while fetchCurrencies is a public API method by design
            // therefore we check the keys here
            // and fallback to generating the currencies from the markets
            if (!isTrue(this->checkRequiredCredentials(false)))
            {
                return ccxt::dict {};
            }
            // sandbox/testnet does not support sapi endpoints
            std::any apiBackup = this->safeValue(this->urls, std::string("apiBackup"));
            if (isTrue(!isEqual(apiBackup, std::any{})))
            {
                return ccxt::dict {};
            }
            // demotrading does not support sapi endpoints
            if (isTrue(this->safeBool(this->options, std::string("enableDemoTrading"), false)))
            {
                return ccxt::dict {};
            }
            std::any promises = ccxt::list{this->sapiGetCapitalConfigGetall(params)};
            std::any fetchMargins = this->safeBool(this->options, std::string("fetchMargins"), false);
            if (isTrue(isEqual(fetchMargins, true)))
            {
                arrayPush(promises, this->sapiGetMarginAllPairs(params));
            }
            std::any results = awaitValue(promiseAll(promises));
            std::any responseCurrencies = ::getValue(results, 0);
            std::any marginablesById = std::any{};
            if (isTrue(isEqual(fetchMargins, true)))
            {
                std::any responseMarginables = ::getValue(results, 1);
                marginablesById = this->indexBy(responseMarginables, std::string("assetName"));
            }
            return this->parseCurrenciesCustom(responseCurrencies, marginablesById);
        }).share();
    }

    virtual std::any parseCurrenciesCustom(std::any responseCurrencies, std::any marginablesById)
    {
        std::any result = ccxt::dict {};
        for (std::any i = 0; isLessThan(i, getArrayLength(responseCurrencies)); postFixIncrement(i))
        {
            std::any parsed = this->parseCurrency(::getValue(responseCurrencies, i));
            if (isTrue(isEqual(parsed, std::any{})))
            {
                throw ExchangeError(toString(add(this->id, std::string(" parseCurrenciesCustom() could not resolve parsed"))));
            }
            std::any code = ::getValue(parsed, std::string("code"));
            if (isTrue(isEqual(parsed, std::any{})))
            {
                throw ExchangeError(toString(add(this->id, std::string(" parseCurrenciesCustom() could not resolve parsed"))));
            }
            std::any marginEntry = this->safeDict(marginablesById, ::getValue(parsed, std::string("id")));
            if (isTrue(isEqual(parsed, std::any{})))
            {
                throw ExchangeError(toString(add(this->id, std::string(" parseCurrenciesCustom() could not resolve parsed"))));
            }
            ::setValue(parsed, std::string("margin"), this->safeBool(marginEntry, std::string("isBorrowable")));
            ::setValue(result, code, parsed);
        }
        return result;
    }

