    virtual std::any parseOrderStatus(std::any status)
    {
        std::any statuses = ccxt::dict {
            { std::string("NEW"), std::string("open") },
            { std::string("PARTIALLY_FILLED"), std::string("open") },
            { std::string("ACCEPTED"), std::string("open") },
            { std::string("TRIGGERING"), std::string("open") },
            { std::string("FILLED"), std::string("closed") },
            { std::string("TRIGGERED"), std::string("closed") },
            { std::string("FINISHED"), std::string("closed") },
            { std::string("CANCELED"), std::string("canceled") },
            { std::string("CANCELLED"), std::string("canceled") },
            { std::string("PENDING_CANCEL"), std::string("canceling") },
            { std::string("REJECTED"), std::string("rejected") },
            { std::string("EXPIRED"), std::string("expired") },
            { std::string("EXPIRED_IN_MATCH"), std::string("expired") },
            { std::string("S"), std::string("ok") },
            { std::string("F"), std::string("rejected") },
        };
        return this->safeString(statuses, status, status);
    }

    virtual std::any parseOrderTypeByMarket(std::any type, std::any marketType)
    {
        std::any types = ccxt::dict {};
        if (isTrue(isTrue((!isEqual(marketType, std::any{}))) && isTrue(isEqual(marketType, std::string("spot")))))
        {
            types = ccxt::dict {
                { std::string("limit_maker"), std::string("limit") },
                { std::string("stop_loss_limit"), std::string("limit") },
                { std::string("stop_loss"), std::string("market") },
                { std::string("take_profit_limit"), std::string("limit") },
                { std::string("take_profit"), std::string("market") },
            };
        } else
        {
            types = ccxt::dict {
                { std::string("limit_maker"), std::string("limit") },
                { std::string("stop"), std::string("limit") },
                { std::string("stop_market"), std::string("market") },
                { std::string("take_profit"), std::string("limit") },
                { std::string("take_profit_market"), std::string("market") },
                { std::string("trailing_stop_market"), std::string("market") },
            };
        }
        return this->safeString(types, type, type);
    }

