    /**
     * @method
     * @name binance#fetchOpenOrders
     * @description fetch all unfilled currently open orders
     * @see https://developers.binance.com/docs/binance-spot-api-docs/rest-api/trading-endpoints#current-open-orders-user_data
     * @see https://developers.binance.com/docs/derivatives/usds-margined-futures/trade/rest-api/Current-All-Open-Orders
     * @see https://developers.binance.com/docs/derivatives/coin-margined-futures/trade/rest-api/Current-All-Open-Orders
     * @see https://developers.binance.com/docs/derivatives/option/trade/Query-Current-Open-Option-Orders
     * @see https://developers.binance.com/docs/margin_trading/trade/Query-Margin-Account-Open-Orders
     * @see https://developers.binance.com/docs/derivatives/portfolio-margin/trade/Query-All-Current-UM-Open-Orders
     * @see https://developers.binance.com/docs/derivatives/portfolio-margin/trade/Query-All-Current-UM-Open-Conditional-Orders
     * @see https://developers.binance.com/docs/derivatives/portfolio-margin/trade/Query-All-Current-CM-Open-Orders
     * @see https://developers.binance.com/docs/derivatives/portfolio-margin/trade/Query-All-Current-CM-Open-Conditional-Orders
     * @see https://developers.binance.com/docs/derivatives/usds-margined-futures/trade/rest-api/Current-All-Algo-Open-Orders
     * @see https://developers.binance.com/en/docs/catalog/advanced-trading-stocks-trading/api/rest-api/trade#current-open-orders
     * @param {string} [symbol] unified market symbol
     * @param {int} [since] the earliest time in ms to fetch open orders for
     * @param {int} [limit] the maximum number of open orders structures to retrieve
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {string} [params.marginMode] 'cross' or 'isolated', for spot margin trading
     * @param {boolean} [params.portfolioMargin] set to true if you would like to fetch open orders in the portfolio margin account
     * @param {boolean} [params.trigger] set to true if you would like to fetch portfolio margin account conditional orders
     * @param {boolean} [params.stock] set to true if you would like to fetch tokenized stock orders
     * @param {string} [params.subType] "linear" or "inverse"
     * @returns {Order[]} a list of [order structures]{@link https://docs.ccxt.com/?id=order-structure}
     */
    std::shared_future<std::any> fetchOpenOrders(std::any symbol = std::any{}, std::any since = std::any{}, std::any limit = std::any{}, std::any params = ccxt::dict {}) override
    {
        return std::async(std::launch::deferred, [=]() mutable -> std::any {
            if (isTrue(isEqual(this->markets, std::any{})))
            {
                awaitValue(this->loadMarkets());
            }
            std::any market = std::any{};
            std::any type = std::any{};
            std::any request = ccxt::dict {};
            std::any marginMode = std::any{};
            std::any marginModeparamsVariable = this->handleMarginModeAndParams(std::string("fetchOpenOrders"), params);
            marginMode = ::getValue(marginModeparamsVariable, 0);
            params = ::getValue(marginModeparamsVariable, 1);
            std::any isPortfolioMargin = std::any{};
            std::any isPortfolioMarginparamsVariable = this->handleOptionAndParams2(params, std::string("fetchOpenOrders"), std::string("papi"), std::string("portfolioMargin"), false);
            isPortfolioMargin = ::getValue(isPortfolioMarginparamsVariable, 0);
            params = ::getValue(isPortfolioMarginparamsVariable, 1);
            std::any isConditional = this->safeBoolN(params, ccxt::list{std::string("stop"), std::string("trigger"), std::string("conditional")});
            std::any stock = std::any{};
            std::any stockparamsVariable = this->handleOptionAndParams(params, std::string("fetchOpenOrders"), std::string("stock"), false);
            stock = ::getValue(stockparamsVariable, 0);
            params = ::getValue(stockparamsVariable, 1);
            if (isTrue(!isEqual(symbol, std::any{})))
            {
                market = this->market(symbol);
                stock = this->safeBool(market, std::string("stock"), false);
                if (isTrue(!isEqual(stock, true)))
                {
                    ::setValue(request, std::string("symbol"), ::getValue(market, std::string("id")));
                }
            } else if (!isTrue(stock))
            {
                std::any warnWithoutSymbol = this->safeBool(::getValue(this->options, std::string("fetchOpenOrders")), std::string("warnWithoutSymbol"));
                std::any optValue = this->safeBool(this->options, std::string("warnOnFetchOpenOrdersWithoutSymbol")); // for backward compatibility
                if (isTrue(isTrue((isEqual(optValue, true))) || isTrue((isTrue(isEqual(optValue, std::any{})) && isTrue((isEqual(warnWithoutSymbol, true)))))))
                {
                    throw ExchangeError(toString(add(add(add(this->id, std::string(" fetchOpenOrders() WARNING: fetching open orders without specifying a symbol has stricter rate limits (10 times more for spot, 40 times more for other markets) compared to requesting with symbol argument. To acknowledge this warning, set ")), this->id), std::string(".options[\"fetchOpenOrders\"][\"warnWithoutSymbol\"] = false to suppress this warning message."))));
                }
            }
            std::any typeparamsVariable = this->handleMarketTypeAndParams(std::string("fetchOpenOrders"), market, params, std::string("spot"));
            type = ::getValue(typeparamsVariable, 0);
            params = ::getValue(typeparamsVariable, 1);
            std::any subType = std::any{};
            std::any subTypeparamsVariable = this->handleSubTypeAndParams(std::string("fetchOpenOrders"), market, params);
            subType = ::getValue(subTypeparamsVariable, 0);
            params = ::getValue(subTypeparamsVariable, 1);
            params = this->omit(params, ccxt::list{std::string("stop"), std::string("trigger"), std::string("conditional")});
            std::any response = std::any{};
            if (isTrue(isEqual(type, std::string("option"))))
            {
                if (isTrue(!isEqual(since, std::any{})))
                {
                    ::setValue(request, std::string("startTime"), since);
                }
                if (isTrue(!isEqual(limit, std::any{})))
                {
                    ::setValue(request, std::string("limit"), limit);
                }
                response = awaitValue(this->eapiPrivateGetOpenOrders(this->extend(request, params)));
            } else if (isTrue(this->isLinear(type, subType)))
            {
                if (isTrue(isPortfolioMargin))
                {
                    if (isTrue(isEqual(isConditional, true)))
                    {
                        response = awaitValue(this->papiGetUmConditionalOpenOrders(this->extend(request, params)));
                    } else
                    {
                        response = awaitValue(this->papiGetUmOpenOrders(this->extend(request, params)));
                    }
                } else
                {
                    if (isTrue(isEqual(isConditional, true)))
                    {
                        response = awaitValue(this->fapiPrivateGetOpenAlgoOrders(this->extend(request, params)));
                    } else
                    {
                        response = awaitValue(this->fapiPrivateGetOpenOrders(this->extend(request, params)));
                    }
                }
            } else if (isTrue(this->isInverse(type, subType)))
            {
                if (isTrue(isPortfolioMargin))
                {
                    if (isTrue(isEqual(isConditional, true)))
                    {
                        response = awaitValue(this->papiGetCmConditionalOpenOrders(this->extend(request, params)));
                    } else
                    {
                        response = awaitValue(this->papiGetCmOpenOrders(this->extend(request, params)));
                    }
                } else
                {
                    if (isTrue(isEqual(isConditional, true)))
                    {
                        response = awaitValue(this->dapiPrivateGetOpenAlgoOrders(this->extend(request, params)));
                    } else
                    {
                        response = awaitValue(this->dapiPrivateGetOpenOrders(this->extend(request, params)));
                    }
                }
            } else if (isTrue(isTrue(isTrue(isEqual(type, std::string("margin"))) || isTrue(!isEqual(marginMode, std::any{}))) || isTrue(isPortfolioMargin)))
            {
                if (isTrue(isPortfolioMargin))
                {
                    response = awaitValue(this->papiGetMarginOpenOrders(this->extend(request, params)));
                } else
                {
                    if (isTrue(isEqual(marginMode, std::string("isolated"))))
                    {
                        ::setValue(request, std::string("isIsolated"), true);
                        if (isTrue(isEqual(symbol, std::any{})))
                        {
                            throw ArgumentsRequired(toString(add(this->id, std::string(" fetchOpenOrders() requires a symbol argument for isolated markets"))));
                        }
                    }
                    response = awaitValue(this->sapiGetMarginOpenOrders(this->extend(request, params)));
                }
            } else if (isTrue(isEqual(stock, true)))
            {
                response = awaitValue(this->sapiGetEquityOrderOpenOrders(this->extend(request, params)));
            } else
            {
                response = awaitValue(this->privateGetOpenOrders(this->extend(request, params)));
            }
            return this->parseOrders(response, market, since, limit);
        }).share();
    }

    /**
     * @method
     * @name binance#fetchOpenOrder
     * @description fetch an open order by the id
     * @see https://developers.binance.com/docs/derivatives/usds-margined-futures/trade/rest-api/Query-Current-Open-Order
     * @see https://developers.binance.com/docs/derivatives/coin-margined-futures/trade/rest-api/Query-Current-Open-Order
     * @see https://developers.binance.com/docs/derivatives/portfolio-margin/trade/Query-Current-UM-Open-Order
     * @see https://developers.binance.com/docs/derivatives/portfolio-margin/trade/Query-Current-UM-Open-Conditional-Order
     * @see https://developers.binance.com/docs/derivatives/portfolio-margin/trade/Query-Current-CM-Open-Order
     * @see https://developers.binance.com/docs/derivatives/portfolio-margin/trade/Query-Current-CM-Open-Conditional-Order
     * @param {string} id order id
     * @param {string} symbol unified market symbol
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {string} [params.trigger] set to true if you would like to fetch portfolio margin account stop or conditional orders
     * @param {boolean} [params.portfolioMargin] set to true if you would like to fetch for a portfolio margin account
     * @returns {object} an [order structure]{@link https://docs.ccxt.com/?id=order-structure}
     */
    virtual std::shared_future<std::any> fetchOpenOrder(std::any id, std::any symbol = std::any{}, std::any params = ccxt::dict {})
    {
        return std::async(std::launch::deferred, [=]() mutable -> std::any {
            if (isTrue(isEqual(symbol, std::any{})))
            {
                throw ArgumentsRequired(toString(add(this->id, std::string(" fetchOpenOrder() requires a symbol argument"))));
            }
            if (isTrue(isEqual(this->markets, std::any{})))
            {
                awaitValue(this->loadMarkets());
            }
            std::any market = this->market(symbol);
            std::any request = ccxt::dict {
                { std::string("symbol"), ::getValue(market, std::string("id")) },
            };
            std::any isPortfolioMargin = std::any{};
            std::any isPortfolioMarginparamsVariable = this->handleOptionAndParams2(params, std::string("fetchOpenOrder"), std::string("papi"), std::string("portfolioMargin"), false);
            isPortfolioMargin = ::getValue(isPortfolioMarginparamsVariable, 0);
            params = ::getValue(isPortfolioMarginparamsVariable, 1);
            std::any isConditional = this->safeBoolN(params, ccxt::list{std::string("stop"), std::string("trigger"), std::string("conditional")});
            params = this->omit(params, ccxt::list{std::string("stop"), std::string("trigger"), std::string("conditional")});
            std::any isPortfolioMarginConditional = (isTrue(isPortfolioMargin) && isTrue(isConditional));
            std::any orderIdRequest = (isTrue((isEqual(isPortfolioMarginConditional, true))) ? std::any(std::string("strategyId")) : std::any(std::string("orderId")));
            ::setValue(request, orderIdRequest, id);
            std::any response = std::any{};
            if (isTrue(isEqual(::getValue(market, std::string("linear")), true)))
            {
                if (isTrue(isPortfolioMargin))
                {
                    if (isTrue(isEqual(isConditional, true)))
                    {
                        response = awaitValue(this->papiGetUmConditionalOpenOrder(this->extend(request, params)));
                    } else
                    {
                        response = awaitValue(this->papiGetUmOpenOrder(this->extend(request, params)));
                    }
                } else
                {
                    response = awaitValue(this->fapiPrivateGetOpenOrder(this->extend(request, params)));
                }
            } else if (isTrue(isEqual(::getValue(market, std::string("inverse")), true)))
            {
                if (isTrue(isPortfolioMargin))
                {
                    if (isTrue(isEqual(isConditional, true)))
                    {
                        response = awaitValue(this->papiGetCmConditionalOpenOrder(this->extend(request, params)));
                    } else
                    {
                        response = awaitValue(this->papiGetCmOpenOrder(this->extend(request, params)));
                    }
                } else
                {
                    response = awaitValue(this->dapiPrivateGetOpenOrder(this->extend(request, params)));
                }
            } else
            {
                if (isTrue(isEqual(::getValue(market, std::string("option")), true)))
                {
                    throw NotSupported(toString(add(this->id, std::string(" fetchOpenOrder() does not support option markets"))));
                } else if (isTrue(isEqual(::getValue(market, std::string("spot")), true)))
                {
                    throw NotSupported(toString(add(this->id, std::string(" fetchOpenOrder() does not support spot markets"))));
                }
            }
            //
            // linear swap
            //
            //     {
            //         "orderId": 3697213934,
            //         "symbol": "BTCUSDT",
            //         "status": "NEW",
            //         "clientOrderId": "x-xcKtGhcufb20c5a7761a4aa09aa156",
            //         "price": "33000.00",
            //         "avgPrice": "0.00000",
            //         "origQty": "0.010",
            //         "executedQty": "0.000",
            //         "cumQuote": "0.00000",
            //         "timeInForce": "GTC",
            //         "type": "LIMIT",
            //         "reduceOnly": false,
            //         "closePosition": false,
            //         "side": "BUY",
            //         "positionSide": "BOTH",
            //         "stopPrice": "0.00",
            //         "workingType": "CONTRACT_PRICE",
            //         "priceProtect": false,
            //         "origType": "LIMIT",
            //         "priceMatch": "NONE",
            //         "selfTradePreventionMode": "NONE",
            //         "goodTillDate": 0,
            //         "time": 1707892893502,
            //         "updateTime": 1707892893515
            //     }
            //
            // inverse swap
            //
            //     {
            //         "orderId": 597368542,
            //         "symbol": "BTCUSD_PERP",
            //         "pair": "BTCUSD",
            //         "status": "NEW",
            //         "clientOrderId": "x-xcKtGhcubbde7ba93b1a4ab881eff3",
            //         "price": "35000",
            //         "avgPrice": "0",
            //         "origQty": "1",
            //         "executedQty": "0",
            //         "cumBase": "0",
            //         "timeInForce": "GTC",
            //         "type": "LIMIT",
            //         "reduceOnly": false,
            //         "closePosition": false,
            //         "side": "BUY",
            //         "positionSide": "BOTH",
            //         "stopPrice": "0",
            //         "workingType": "CONTRACT_PRICE",
            //         "priceProtect": false,
            //         "origType": "LIMIT",
            //         "time": 1707893453199,
            //         "updateTime": 1707893453199
            //     }
            //
            // linear portfolio margin
            //
            //     {
            //         "orderId": 264895013409,
            //         "symbol": "BTCUSDT",
            //         "status": "NEW",
            //         "clientOrderId": "x-xcKtGhcu6278f1adbdf14f74ab432e",
            //         "price": "35000",
            //         "avgPrice": "0",
            //         "origQty": "0.010",
            //         "executedQty": "0",
            //         "cumQuote": "0",
            //         "timeInForce": "GTC",
            //         "type": "LIMIT",
            //         "reduceOnly": false,
            //         "side": "BUY",
            //         "positionSide": "LONG",
            //         "origType": "LIMIT",
            //         "time": 1707893839364,
            //         "updateTime": 1707893839364,
            //         "goodTillDate": 0,
            //         "selfTradePreventionMode": "NONE"
            //     }
            //
            // inverse portfolio margin
            //
            //     {
            //         "orderId": 71790316950,
            //         "symbol": "ETHUSD_PERP",
            //         "pair": "ETHUSD",
            //         "status": "NEW",
            //         "clientOrderId": "x-xcKtGhcuec11030474204ab08ba2c2",
            //         "price": "2500",
            //         "avgPrice": "0",
            //         "origQty": "1",
            //         "executedQty": "0",
            //         "cumBase": "0",
            //         "timeInForce": "GTC",
            //         "type": "LIMIT",
            //         "reduceOnly": false,
            //         "side": "BUY",
            //         "positionSide": "LONG",
            //         "origType": "LIMIT",
            //         "time": 1707894181694,
            //         "updateTime": 1707894181694
            //     }
            //
            // linear portfolio margin conditional
            //
            //     {
            //         "newClientStrategyId": "x-xcKtGhcu2205fde44418483ca21874",
            //         "strategyId": 4084339,
            //         "strategyStatus": "NEW",
            //         "strategyType": "STOP",
            //         "origQty": "0.010",
            //         "price": "35000",
            //         "reduceOnly": false,
            //         "side": "BUY",
            //         "positionSide": "LONG",
            //         "stopPrice": "60000",
            //         "symbol": "BTCUSDT",
            //         "bookTime": 1707894490094,
            //         "updateTime": 1707894490094,
            //         "timeInForce": "GTC",
            //         "workingType": "CONTRACT_PRICE",
            //         "priceProtect": false,
            //         "goodTillDate": 0,
            //         "selfTradePreventionMode": "NONE"
            //     }
            //
            // inverse portfolio margin conditional
            //
            //     {
            //         "newClientStrategyId": "x-xcKtGhcu2da9c765294b433994ffce",
            //         "strategyId": 1423501,
            //         "strategyStatus": "NEW",
            //         "strategyType": "STOP",
            //         "origQty": "1",
            //         "price": "2500",
            //         "reduceOnly": false,
            //         "side": "BUY",
            //         "positionSide": "LONG",
            //         "stopPrice": "4000",
            //         "symbol": "ETHUSD_PERP",
            //         "bookTime": 1707894782679,
            //         "updateTime": 1707894782679,
            //         "timeInForce": "GTC",
            //         "workingType": "CONTRACT_PRICE",
            //         "priceProtect": false
            //     }
            //
            if (isTrue(isEqual(response, std::any{})))
            {
                throw NullResponse(toString(add(this->id, std::string(" parseOrder() returned empty response"))));
            }
            return this->parseOrder(response, market);
        }).share();
    }

    /**
     * @method
     * @name binance#fetchClosedOrders
     * @description fetches information on multiple closed orders made by the user
     * @see https://developers.binance.com/docs/binance-spot-api-docs/rest-api/trading-endpoints#all-orders-user_data
     * @see https://developers.binance.com/docs/derivatives/usds-margined-futures/trade/rest-api/All-Orders
     * @see https://developers.binance.com/docs/derivatives/coin-margined-futures/trade/rest-api/All-Orders
     * @see https://developers.binance.com/docs/derivatives/option/trade/Query-Option-Order-History
     * @see https://developers.binance.com/docs/margin_trading/trade/Query-Margin-Account-All-Orders
     * @see https://developers.binance.com/docs/derivatives/portfolio-margin/trade/Query-All-UM-Orders
     * @see https://developers.binance.com/docs/derivatives/portfolio-margin/trade/Query-All-CM-Orders
     * @see https://developers.binance.com/docs/derivatives/portfolio-margin/trade/Query-All-UM-Conditional-Orders
     * @see https://developers.binance.com/docs/derivatives/portfolio-margin/trade/Query-All-CM-Conditional-Orders
     * @see https://developers.binance.com/en/docs/catalog/advanced-trading-stocks-trading/api/rest-api/trade#equity-order-history
     * @param {string} [symbol] unified market symbol of the market orders were made in
     * @param {int} [since] the earliest time in ms to fetch orders for
     * @param {int} [limit] the maximum number of order structures to retrieve
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {boolean} [params.paginate] default false, when true will automatically paginate by calling this endpoint multiple times. See in the docs all the [available parameters](https://github.com/ccxt/ccxt/wiki/Manual#pagination-params)
     * @param {boolean} [params.portfolioMargin] set to true if you would like to fetch orders in a portfolio margin account
     * @param {boolean} [params.trigger] set to true if you would like to fetch portfolio margin account trigger or conditional orders
     * @param {boolean} [params.stock] set to true if you would like to fetch tokenized stock orders
     * @returns {Order[]} a list of [order structures]{@link https://docs.ccxt.com/?id=order-structure}
     */
    std::shared_future<std::any> fetchClosedOrders(std::any symbol = std::any{}, std::any since = std::any{}, std::any limit = std::any{}, std::any params = ccxt::dict {}) override
    {
        return std::async(std::launch::deferred, [=]() mutable -> std::any {
            std::any market = std::any{};
            std::any stock = std::any{};
            std::any stockparamsVariable = this->handleOptionAndParams(params, std::string("fetchClosedOrders"), std::string("stock"), false);
            stock = ::getValue(stockparamsVariable, 0);
            params = ::getValue(stockparamsVariable, 1);
            if (isTrue(!isEqual(symbol, std::any{})))
            {
                market = this->market(symbol);
                stock = this->safeBool(market, std::string("stock"), false);
            } else if (!isTrue(stock))
            {
                throw ArgumentsRequired(toString(add(this->id, std::string(" fetchClosedOrders() requires a symbol argument"))));
            }
            if (isTrue(isEqual(stock, true)))
            {
                ::setValue(params, std::string("stock"), true);
                ::setValue(params, std::string("orderStatus"), std::string("FILLED"));
            }
            std::any orders = awaitValue(this->fetchOrders(symbol, since, std::any{}, params));
            std::any filteredOrders = this->filterBy(orders, std::string("status"), std::string("closed"));
            return this->filterBySinceLimit(filteredOrders, since, limit);
        }).share();
    }

    /**
     * @method
     * @name binance#fetchCanceledOrders
     * @description fetches information on multiple canceled orders made by the user
     * @see https://developers.binance.com/docs/binance-spot-api-docs/rest-api/trading-endpoints#all-orders-user_data
     * @see https://developers.binance.com/docs/derivatives/usds-margined-futures/trade/rest-api/All-Orders
     * @see https://developers.binance.com/docs/derivatives/coin-margined-futures/trade/rest-api/All-Orders
     * @see https://developers.binance.com/docs/derivatives/option/trade/Query-Option-Order-History
     * @see https://developers.binance.com/docs/margin_trading/trade/Query-Margin-Account-All-Orders
     * @see https://developers.binance.com/docs/derivatives/portfolio-margin/trade/Query-All-UM-Orders
     * @see https://developers.binance.com/docs/derivatives/portfolio-margin/trade/Query-All-CM-Orders
     * @see https://developers.binance.com/docs/derivatives/portfolio-margin/trade/Query-All-UM-Conditional-Orders
     * @see https://developers.binance.com/docs/derivatives/portfolio-margin/trade/Query-All-CM-Conditional-Orders
     * @see https://developers.binance.com/en/docs/catalog/advanced-trading-stocks-trading/api/rest-api/trade#equity-order-history
     * @param {string} [symbol] unified market symbol of the market the orders were made in
     * @param {int} [since] the earliest time in ms to fetch orders for
     * @param {int} [limit] the maximum number of order structures to retrieve
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {boolean} [params.paginate] default false, when true will automatically paginate by calling this endpoint multiple times. See in the docs all the [available parameters](https://github.com/ccxt/ccxt/wiki/Manual#pagination-params)
     * @param {boolean} [params.portfolioMargin] set to true if you would like to fetch orders in a portfolio margin account
     * @param {boolean} [params.trigger] set to true if you would like to fetch portfolio margin account trigger or conditional orders
     * @param {boolean} [params.stock] set to true if you would like to fetch tokenized stock orders
     * @returns {object[]} a list of [order structures]{@link https://docs.ccxt.com/?id=order-structure}
     */
    std::shared_future<std::any> fetchCanceledOrders(std::any symbol = std::any{}, std::any since = std::any{}, std::any limit = std::any{}, std::any params = ccxt::dict {}) override
    {
        return std::async(std::launch::deferred, [=]() mutable -> std::any {
            std::any market = std::any{};
            std::any stock = std::any{};
            std::any stockparamsVariable = this->handleOptionAndParams(params, std::string("fetchCanceledOrders"), std::string("stock"), false);
            stock = ::getValue(stockparamsVariable, 0);
            params = ::getValue(stockparamsVariable, 1);
            if (isTrue(!isEqual(symbol, std::any{})))
            {
                market = this->market(symbol);
                stock = this->safeBool(market, std::string("stock"), false);
            } else if (!isTrue(stock))
            {
                throw ArgumentsRequired(toString(add(this->id, std::string(" fetchCanceledOrders() requires a symbol argument"))));
            }
            if (isTrue(isEqual(stock, true)))
            {
                ::setValue(params, std::string("stock"), true);
                ::setValue(params, std::string("orderStatus"), std::string("CANCELED"));
            }
            std::any orders = awaitValue(this->fetchOrders(symbol, since, std::any{}, params));
            std::any filteredOrders = this->filterBy(orders, std::string("status"), std::string("canceled"));
            return this->filterBySinceLimit(filteredOrders, since, limit);
        }).share();
    }

    /**
     * @method
     * @name binance#fetchCanceledAndClosedOrders
     * @description fetches information on multiple canceled orders made by the user
     * @see https://developers.binance.com/docs/binance-spot-api-docs/rest-api/trading-endpoints#all-orders-user_data
     * @see https://developers.binance.com/docs/derivatives/usds-margined-futures/trade/rest-api/All-Orders
     * @see https://developers.binance.com/docs/derivatives/coin-margined-futures/trade/rest-api/All-Orders
     * @see https://developers.binance.com/docs/derivatives/option/trade/Query-Option-Order-History
     * @see https://developers.binance.com/docs/margin_trading/trade/Query-Margin-Account-All-Orders
     * @see https://developers.binance.com/docs/derivatives/portfolio-margin/trade/Query-All-UM-Orders
     * @see https://developers.binance.com/docs/derivatives/portfolio-margin/trade/Query-All-CM-Orders
     * @see https://developers.binance.com/docs/derivatives/portfolio-margin/trade/Query-All-UM-Conditional-Orders
     * @see https://developers.binance.com/docs/derivatives/portfolio-margin/trade/Query-All-CM-Conditional-Orders
     * @see https://developers.binance.com/en/docs/catalog/advanced-trading-stocks-trading/api/rest-api/trade#equity-order-history
     * @param {string} [symbol] unified market symbol of the market the orders were made in
     * @param {int} [since] the earliest time in ms to fetch orders for
     * @param {int} [limit] the maximum number of order structures to retrieve
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {boolean} [params.paginate] default false, when true will automatically paginate by calling this endpoint multiple times. See in the docs all the [available parameters](https://github.com/ccxt/ccxt/wiki/Manual#pagination-params)
     * @param {boolean} [params.portfolioMargin] set to true if you would like to fetch orders in a portfolio margin account
     * @param {boolean} [params.trigger] set to true if you would like to fetch portfolio margin account trigger or conditional orders
     * @param {boolean} [params.stock] set to true if you would like to fetch tokenized stock orders
     * @returns {object[]} a list of [order structures]{@link https://docs.ccxt.com/?id=order-structure}
     */
    std::shared_future<std::any> fetchCanceledAndClosedOrders(std::any symbol = std::any{}, std::any since = std::any{}, std::any limit = std::any{}, std::any params = ccxt::dict {}) override
    {
        return std::async(std::launch::deferred, [=]() mutable -> std::any {
            std::any market = std::any{};
            std::any stock = std::any{};
            std::any stockparamsVariable = this->handleOptionAndParams(params, std::string("fetchCanceledAndClosedOrders"), std::string("stock"), false);
            stock = ::getValue(stockparamsVariable, 0);
            params = ::getValue(stockparamsVariable, 1);
            if (isTrue(!isEqual(symbol, std::any{})))
            {
                market = this->market(symbol);
                stock = this->safeBool(market, std::string("stock"), false);
            } else if (!isTrue(stock))
            {
                throw ArgumentsRequired(toString(add(this->id, std::string(" fetchCanceledAndClosedOrders() requires a symbol argument"))));
            }
            if (isTrue(isEqual(stock, true)))
            {
                ::setValue(params, std::string("stock"), true);
                ::setValue(params, std::string("orderStatus"), std::string("FILLED,CANCELED"));
            }
            std::any orders = awaitValue(this->fetchOrders(symbol, since, std::any{}, params));
            std::any canceledOrders = this->filterBy(orders, std::string("status"), std::string("canceled"));
            std::any closedOrders = this->filterBy(orders, std::string("status"), std::string("closed"));
            std::any filteredOrders = this->arrayConcat(canceledOrders, closedOrders);
            std::any sortedOrders = this->sortBy(filteredOrders, std::string("timestamp"));
            return this->filterBySinceLimit(sortedOrders, since, limit);
        }).share();
    }

    /**
     * @method
     * @name binance#cancelOrder
     * @description cancels an open order
     * @see https://developers.binance.com/docs/binance-spot-api-docs/rest-api/trading-endpoints#cancel-order-trade
     * @see https://developers.binance.com/docs/derivatives/usds-margined-futures/trade/rest-api/Cancel-Order
     * @see https://developers.binance.com/docs/derivatives/coin-margined-futures/trade/rest-api/Cancel-Order
     * @see https://developers.binance.com/docs/derivatives/option/trade/Cancel-Option-Order
     * @see https://developers.binance.com/docs/margin_trading/trade/Margin-Account-Cancel-Order
     * @see https://developers.binance.com/docs/derivatives/portfolio-margin/trade/Cancel-UM-Order
     * @see https://developers.binance.com/docs/derivatives/portfolio-margin/trade/Cancel-CM-Order
     * @see https://developers.binance.com/docs/derivatives/portfolio-margin/trade/Cancel-UM-Conditional-Order
     * @see https://developers.binance.com/docs/derivatives/portfolio-margin/trade/Cancel-CM-Conditional-Order
     * @see https://developers.binance.com/docs/derivatives/portfolio-margin/trade/Cancel-Margin-Account-Order
     * @see https://developers.binance.com/docs/derivatives/usds-margined-futures/trade/rest-api/Cancel-Algo-Order
     * @see https://developers.binance.com/en/docs/catalog/advanced-trading-stocks-trading/api/rest-api/trade#cancel-equity-order
     * @param {string} id order id
     * @param {string} symbol unified symbol of the market the order was made in
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {boolean} [params.portfolioMargin] set to true if you would like to cancel an order in a portfolio margin account
     * @param {boolean} [params.trigger] set to true if you would like to cancel a portfolio margin account conditional order
     * @param {boolean} [params.stock] set to true if you would like to cancel a tokenized stock order
     * @returns {object} An [order structure]{@link https://docs.ccxt.com/?id=order-structure}
     */
    std::shared_future<std::any> cancelOrder(std::any id, std::any symbol = std::any{}, std::any params = ccxt::dict {}) override
    {
        return std::async(std::launch::deferred, [=]() mutable -> std::any {
            if (isTrue(isEqual(this->markets, std::any{})))
            {
                awaitValue(this->loadMarkets());
            }
            std::any request = ccxt::dict {};
            std::any market = std::any{};
            std::any stock = std::any{};
            std::any stockparamsVariable = this->handleOptionAndParams(params, std::string("cancelOrder"), std::string("stock"), false);
            stock = ::getValue(stockparamsVariable, 0);
            params = ::getValue(stockparamsVariable, 1);
            if (isTrue(!isEqual(symbol, std::any{})))
            {
                market = this->market(symbol);
                stock = this->safeBool(market, std::string("stock"), false);
                if (isTrue(!isEqual(stock, true)))
                {
                    ::setValue(request, std::string("symbol"), ::getValue(market, std::string("id")));
                }
            } else
            {
                throw ArgumentsRequired(toString(add(this->id, std::string(" cancelOrder() requires a symbol argument"))));
            }
            std::any type = std::any{};
            std::any typeparamsVariable = this->handleMarketTypeAndParams(std::string("cancelOrder"), market, params, std::string("spot"));
            type = ::getValue(typeparamsVariable, 0);
            params = ::getValue(typeparamsVariable, 1);
            std::any subType = std::any{};
            std::any subTypeparamsVariable = this->handleSubTypeAndParams(std::string("cancelOrder"), market, params);
            subType = ::getValue(subTypeparamsVariable, 0);
            params = ::getValue(subTypeparamsVariable, 1);
            std::any marginMode = std::any{};
            std::any marginModeparamsVariable = this->handleMarginModeAndParams(std::string("cancelOrder"), params);
            marginMode = ::getValue(marginModeparamsVariable, 0);
            params = ::getValue(marginModeparamsVariable, 1);
            std::any isPortfolioMargin = std::any{};
            std::any isPortfolioMarginparamsVariable = this->handleOptionAndParams2(params, std::string("cancelOrder"), std::string("papi"), std::string("portfolioMargin"), false);
            isPortfolioMargin = ::getValue(isPortfolioMarginparamsVariable, 0);
            params = ::getValue(isPortfolioMarginparamsVariable, 1);
            std::any isConditional = this->safeBoolN(params, ccxt::list{std::string("stop"), std::string("trigger"), std::string("conditional")});
            std::any isOptionType = isEqual(type, std::string("option"));
            std::any isLinearType = this->isLinear(type, subType);
            std::any isInverseType = this->isInverse(type, subType);
            std::any isSwapConditional = isTrue(isTrue(isTrue((!isEqual(market, std::any{}))) && isTrue((isEqual(::getValue(market, std::string("swap")), true)))) && isTrue((isEqual(isConditional, true)))) && isTrue((!isEqual(isPortfolioMargin, true)));
            std::any clientOrderId = this->safeStringN(params, ccxt::list{std::string("origClientOrderId"), std::string("clientOrderId"), std::string("newClientStrategyId"), std::string("clientAlgoId")});
            if (isTrue(!isEqual(clientOrderId, std::any{})))
            {
                if (isTrue(isOptionType))
                {
                    ::setValue(request, std::string("clientOrderId"), clientOrderId);
                } else if (isTrue(isEqual(isSwapConditional, true)))
                {
                    ::setValue(request, std::string("clientAlgoId"), clientOrderId);
                } else
                {
                    if (isTrue(isTrue(isPortfolioMargin) && isTrue((isEqual(isConditional, true)))))
                    {
                        ::setValue(request, std::string("newClientStrategyId"), clientOrderId);
                    } else
                    {
                        ::setValue(request, std::string("origClientOrderId"), clientOrderId);
                    }
                }
            } else
            {
                if (isTrue(isTrue(isPortfolioMargin) && isTrue((isEqual(isConditional, true)))))
                {
                    ::setValue(request, std::string("strategyId"), id);
                } else if (isTrue(isEqual(isSwapConditional, true)))
                {
                    ::setValue(request, std::string("algoId"), id);
                } else
                {
                    ::setValue(request, std::string("orderId"), id);
                }
            }
            params = this->omit(params, ccxt::list{std::string("origClientOrderId"), std::string("clientOrderId"), std::string("newClientStrategyId"), std::string("stop"), std::string("trigger"), std::string("conditional"), std::string("clientAlgoId")});
            std::any response = std::any{};
            if (isTrue(isOptionType))
            {
                response = awaitValue(this->eapiPrivateDeleteOrder(this->extend(request, params)));
            } else if (isTrue(isLinearType))
            {
                if (isTrue(isPortfolioMargin))
                {
                    if (isTrue(isEqual(isConditional, true)))
                    {
                        response = awaitValue(this->papiDeleteUmConditionalOrder(this->extend(request, params)));
                    } else
                    {
                        response = awaitValue(this->papiDeleteUmOrder(this->extend(request, params)));
                    }
                } else
                {
                    if (isTrue(isEqual(isConditional, true)))
                    {
                        response = awaitValue(this->fapiPrivateDeleteAlgoOrder(this->extend(request, params)));
                    } else
                    {
                        response = awaitValue(this->fapiPrivateDeleteOrder(this->extend(request, params)));
                    }
                }
            } else if (isTrue(isInverseType))
            {
                if (isTrue(isPortfolioMargin))
                {
                    if (isTrue(isEqual(isConditional, true)))
                    {
                        response = awaitValue(this->papiDeleteCmConditionalOrder(this->extend(request, params)));
                    } else
                    {
                        response = awaitValue(this->papiDeleteCmOrder(this->extend(request, params)));
                    }
                } else
                {
                    if (isTrue(isEqual(isConditional, true)))
                    {
                        response = awaitValue(this->dapiPrivateDeleteAlgoOrder(this->extend(request, params)));
                    } else
                    {
                        response = awaitValue(this->dapiPrivateDeleteOrder(this->extend(request, params)));
                    }
                }
            } else if (isTrue(isTrue(isTrue((isEqual(type, std::string("margin")))) || isTrue((!isEqual(marginMode, std::any{})))) || isTrue(isPortfolioMargin)))
            {
                if (isTrue(isPortfolioMargin))
                {
                    response = awaitValue(this->papiDeleteMarginOrder(this->extend(request, params)));
                } else
                {
                    if (isTrue(isEqual(marginMode, std::string("isolated"))))
                    {
                        ::setValue(request, std::string("isIsolated"), true);
                    }
                    response = awaitValue(this->sapiDeleteMarginOrder(this->extend(request, params)));
                }
            } else if (isTrue(isEqual(stock, true)))
            {
                response = awaitValue(this->sapiPostEquityOrderCancel(this->extend(request, params)));
            } else
            {
                response = awaitValue(this->privateDeleteOrder(this->extend(request, params)));
            }
            if (isTrue(isEqual(response, std::any{})))
            {
                throw NullResponse(toString(add(this->id, std::string(" parseOrder() returned empty response"))));
            }
            return this->parseOrder(response, market);
        }).share();
    }

    /**
     * @method
     * @name binance#cancelAllOrders
     * @description cancel all open orders in a market
     * @see https://developers.binance.com/docs/binance-spot-api-docs/rest-api/trading-endpoints#cancel-all-open-orders-on-a-symbol-trade
     * @see https://developers.binance.com/docs/derivatives/usds-margined-futures/trade/rest-api/Cancel-All-Open-Orders
     * @see https://developers.binance.com/docs/derivatives/coin-margined-futures/trade/rest-api/Cancel-All-Open-Orders
     * @see https://developers.binance.com/docs/derivatives/option/trade/Cancel-all-Option-orders-on-specific-symbol
     * @see https://developers.binance.com/docs/margin_trading/trade/Margin-Account-Cancel-All-Open-Orders
     * @see https://developers.binance.com/docs/derivatives/portfolio-margin/trade/Cancel-All-UM-Open-Orders
     * @see https://developers.binance.com/docs/derivatives/portfolio-margin/trade/Cancel-All-UM-Open-Conditional-Orders
     * @see https://developers.binance.com/docs/derivatives/portfolio-margin/trade/Cancel-All-CM-Open-Orders
     * @see https://developers.binance.com/docs/derivatives/portfolio-margin/trade/Cancel-All-CM-Open-Conditional-Orders
     * @see https://developers.binance.com/docs/derivatives/portfolio-margin/trade/Cancel-Margin-Account-All-Open-Orders-on-a-Symbol
     * @see https://developers.binance.com/docs/derivatives/usds-margined-futures/trade/rest-api/Cancel-All-Algo-Open-Orders
     * @see https://developers.binance.com/en/docs/catalog/advanced-trading-stocks-trading/api/rest-api/trade#cancel-all-equity-orders
     * @param {string} symbol unified market symbol of the market to cancel orders in
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {string} [params.marginMode] 'cross' or 'isolated', for spot margin trading
     * @param {boolean} [params.portfolioMargin] set to true if you would like to cancel orders in a portfolio margin account
     * @param {boolean} [params.trigger] set to true if you would like to cancel portfolio margin account conditional orders
     * @param {boolean} [params.stock] set to true if you would like to cancel tokenized stock orders
     * @returns {object[]} a list of [order structures]{@link https://docs.ccxt.com/?id=order-structure}
     */
    std::shared_future<std::any> cancelAllOrders(std::any symbol = std::any{}, std::any params = ccxt::dict {}) override
    {
        return std::async(std::launch::deferred, [=]() mutable -> std::any {
            if (isTrue(isEqual(this->markets, std::any{})))
            {
                awaitValue(this->loadMarkets());
            }
            std::any request = ccxt::dict {};
            std::any market = std::any{};
            std::any stock = std::any{};
            std::any stockparamsVariable = this->handleOptionAndParams(params, std::string("cancelAllOrders"), std::string("stock"), false);
            stock = ::getValue(stockparamsVariable, 0);
            params = ::getValue(stockparamsVariable, 1);
            if (isTrue(!isEqual(symbol, std::any{})))
            {
                market = this->market(symbol);
                stock = this->safeBool(market, std::string("stock"), false);
                if (isTrue(!isEqual(stock, true)))
                {
                    ::setValue(request, std::string("symbol"), ::getValue(market, std::string("id")));
                }
            } else
            {
                throw ArgumentsRequired(toString(add(this->id, std::string(" cancelAllOrders() requires a symbol argument"))));
            }
            std::any isPortfolioMargin = std::any{};
            std::any isPortfolioMarginparamsVariable = this->handleOptionAndParams2(params, std::string("cancelAllOrders"), std::string("papi"), std::string("portfolioMargin"), false);
            isPortfolioMargin = ::getValue(isPortfolioMarginparamsVariable, 0);
            params = ::getValue(isPortfolioMarginparamsVariable, 1);
            std::any isConditional = this->safeBoolN(params, ccxt::list{std::string("stop"), std::string("trigger"), std::string("conditional")});
            std::any type = std::any{};
            std::any typeparamsVariable = this->handleMarketTypeAndParams(std::string("cancelAllOrders"), market, params, std::string("spot"));
            type = ::getValue(typeparamsVariable, 0);
            params = ::getValue(typeparamsVariable, 1);
            std::any subType = std::any{};
            std::any subTypeparamsVariable = this->handleSubTypeAndParams(std::string("cancelAllOrders"), market, params);
            subType = ::getValue(subTypeparamsVariable, 0);
            params = ::getValue(subTypeparamsVariable, 1);
            std::any isOptionType = isEqual(type, std::string("option"));
            std::any isLinearType = this->isLinear(type, subType);
            std::any isInverseType = this->isInverse(type, subType);
            params = this->omit(params, ccxt::list{std::string("stop"), std::string("trigger"), std::string("conditional")});
            std::any marginMode = std::any{};
            std::any marginModeparamsVariable = this->handleMarginModeAndParams(std::string("cancelAllOrders"), params);
            marginMode = ::getValue(marginModeparamsVariable, 0);
            params = ::getValue(marginModeparamsVariable, 1);
            std::any response = std::any{};
            if (isTrue(isOptionType))
            {
                response = awaitValue(this->eapiPrivateDeleteAllOpenOrders(this->extend(request, params)));
            } else if (isTrue(isLinearType))
            {
                if (isTrue(isPortfolioMargin))
                {
                    if (isTrue(isEqual(isConditional, true)))
                    {
                        response = awaitValue(this->papiDeleteUmConditionalAllOpenOrders(this->extend(request, params)));
                    } else
                    {
                        response = awaitValue(this->papiDeleteUmAllOpenOrders(this->extend(request, params)));
                    }
                } else
                {
                    if (isTrue(isEqual(isConditional, true)))
                    {
                        response = awaitValue(this->fapiPrivateDeleteAlgoOpenOrders(this->extend(request, params)));
                    } else
                    {
                        response = awaitValue(this->fapiPrivateDeleteAllOpenOrders(this->extend(request, params)));
                    }
                }
            } else if (isTrue(isInverseType))
            {
                if (isTrue(isPortfolioMargin))
                {
                    if (isTrue(isEqual(isConditional, true)))
                    {
                        response = awaitValue(this->papiDeleteCmConditionalAllOpenOrders(this->extend(request, params)));
                    } else
                    {
                        response = awaitValue(this->papiDeleteCmAllOpenOrders(this->extend(request, params)));
                    }
                } else
                {
                    response = awaitValue(this->dapiPrivateDeleteAllOpenOrders(this->extend(request, params)));
                }
            } else if (isTrue(isTrue(isTrue((isEqual(type, std::string("margin")))) || isTrue((!isEqual(marginMode, std::any{})))) || isTrue(isPortfolioMargin)))
            {
                if (isTrue(isPortfolioMargin))
                {
                    response = awaitValue(this->papiDeleteMarginAllOpenOrders(this->extend(request, params)));
                } else
                {
                    if (isTrue(isEqual(marginMode, std::string("isolated"))))
                    {
                        ::setValue(request, std::string("isIsolated"), true);
                    }
                    response = awaitValue(this->sapiDeleteMarginOpenOrders(this->extend(request, params)));
                }
            } else if (isTrue(isEqual(stock, true)))
            {
                response = awaitValue(this->sapiPostEquityOrderCancelAll(this->extend(request, params)));
            } else
            {
                response = awaitValue(this->privateDeleteOpenOrders(this->extend(request, params)));
            }
            if (isTrue(isArray(response)))
            {
                return this->parseOrders(response, market);
            } else
            {
                std::any order = this->safeOrder(ccxt::dict {
                    { std::string("info"), response },
                });
                return ccxt::list{order};
            }
            return std::any{};
        }).share();
    }

    /**
     * @method
     * @name binance#cancelOrders
     * @description cancel multiple orders
     * @see https://developers.binance.com/docs/derivatives/usds-margined-futures/trade/rest-api/Cancel-Multiple-Orders
     * @see https://developers.binance.com/docs/derivatives/coin-margined-futures/trade/rest-api/Cancel-Multiple-Orders
     * @param {string[]} ids order ids
     * @param {string} [symbol] unified market symbol
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {string[]} [params.clientOrderIds] alternative to ids, array of client order ids
     *
     * EXCHANGE SPECIFIC PARAMETERS
     * @param {string[]} [params.origClientOrderIdList] max length 10 e.g. ["my_id_1","my_id_2"], encode the double quotes. No space after comma
     * @param {int[]} [params.recvWindow]
     * @returns {object} an list of [order structures]{@link https://docs.ccxt.com/?id=order-structure}
     */
    std::shared_future<std::any> cancelOrders(std::any ids, std::any symbol = std::any{}, std::any params = ccxt::dict {}) override
    {
        return std::async(std::launch::deferred, [=]() mutable -> std::any {
            if (isTrue(isEqual(symbol, std::any{})))
            {
                throw ArgumentsRequired(toString(add(this->id, std::string(" cancelOrders() requires a symbol argument"))));
            }
            if (isTrue(isEqual(this->markets, std::any{})))
            {
                awaitValue(this->loadMarkets());
            }
            std::any market = this->market(symbol);
            if (isTrue(!isEqual(::getValue(market, std::string("contract")), true)))
            {
                throw BadRequest(toString(add(this->id, std::string(" cancelOrders is only supported for swap markets."))));
            }
            std::any request = ccxt::dict {
                { std::string("symbol"), ::getValue(market, std::string("id")) },
            };
            std::any origClientOrderIdList = this->safeList2(params, std::string("origClientOrderIdList"), std::string("clientOrderIds"));
            if (isTrue(!isEqual(origClientOrderIdList, std::any{})))
            {
                params = this->omit(params, ccxt::list{std::string("clientOrderIds")});
                ::setValue(request, std::string("origClientOrderIdList"), origClientOrderIdList);
            } else
            {
                ::setValue(request, std::string("orderidlist"), ids);
            }
            std::any response = std::any{};
            if (isTrue(isEqual(::getValue(market, std::string("linear")), true)))
            {
                response = awaitValue(this->fapiPrivateDeleteBatchOrders(this->extend(request, params)));
            } else if (isTrue(isEqual(::getValue(market, std::string("inverse")), true)))
            {
                response = awaitValue(this->dapiPrivateDeleteBatchOrders(this->extend(request, params)));
            }
            //
            //    [
            //        {
            //            "clientOrderId": "myOrder1",
            //            "cumQty": "0",
            //            "cumQuote": "0",
            //            "executedQty": "0",
            //            "orderId": 283194212,
            //            "origQty": "11",
            //            "origType": "TRAILING_STOP_MARKET",
            //            "price": "0",
            //            "reduceOnly": false,
            //            "side": "BUY",
            //            "positionSide": "SHORT",
            //            "status": "CANCELED",
            //            "stopPrice": "9300",                  // please ignore when order type is TRAILING_STOP_MARKET
            //            "closePosition": false,               // if Close-All
            //            "symbol": "BTCUSDT",
            //            "timeInForce": "GTC",
            //            "type": "TRAILING_STOP_MARKET",
            //            "activatePrice": "9020",              // activation price, only return with TRAILING_STOP_MARKET order
            //            "priceRate": "0.3",                   // callback rate, only return with TRAILING_STOP_MARKET order
            //            "updateTime": 1571110484038,
            //            "workingType": "CONTRACT_PRICE",
            //            "priceProtect": false,                // if conditional order trigger is protected
            //            "priceMatch": "NONE",                 // price match mode
            //            "selfTradePreventionMode": "NONE",    // self trading preventation mode
            //            "goodTillDate": 0                     // order pre-set auot cancel time for TIF GTD order
            //        },
            //        {
            //            "code": -2011,
            //            "msg": "Unknown order sent."
            //        }
            //    ]
            //
            return this->parseOrders(response, market);
        }).share();
    }

    /**
     * @method
     * @name binance#fetchOrderTrades
     * @description fetch all the trades made from a single order
     * @see https://developers.binance.com/docs/binance-spot-api-docs/rest-api/account-endpoints#account-trade-list-user_data
     * @see https://developers.binance.com/docs/derivatives/usds-margined-futures/trade/rest-api/Account-Trade-List
     * @see https://developers.binance.com/docs/derivatives/coin-margined-futures/trade/rest-api/Account-Trade-List
     * @see https://developers.binance.com/docs/margin_trading/trade/Query-Margin-Account-Trade-List
     * @param {string} id order id
     * @param {string} symbol unified market symbol
     * @param {int} [since] the earliest time in ms to fetch trades for
     * @param {int} [limit] the maximum number of trades to retrieve
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object[]} a list of [trade structures]{@link https://docs.ccxt.com/?id=trade-structure}
     */
    std::shared_future<std::any> fetchOrderTrades(std::any id, std::any symbol = std::any{}, std::any since = std::any{}, std::any limit = std::any{}, std::any params = ccxt::dict {}) override
    {
        return std::async(std::launch::deferred, [=]() mutable -> std::any {
            if (isTrue(isEqual(symbol, std::any{})))
            {
                throw ArgumentsRequired(toString(add(this->id, std::string(" fetchOrderTrades() requires a symbol argument"))));
            }
            if (isTrue(isEqual(this->markets, std::any{})))
            {
                awaitValue(this->loadMarkets());
            }
            std::any market = this->market(symbol);
            std::any type = this->safeString(params, std::string("type"), ::getValue(market, std::string("type")));
            params = this->omit(params, std::string("type"));
            if (isTrue(!isEqual(type, std::string("spot"))))
            {
                throw NotSupported(toString(add(this->id, std::string(" fetchOrderTrades() supports spot markets only"))));
            }
            std::any request = ccxt::dict {
                { std::string("orderId"), id },
            };
            return awaitValue(this->fetchMyTrades(symbol, since, limit, this->extend(request, params)));
        }).share();
    }

    /**
     * @method
     * @name binance#fetchMyTrades
     * @description fetch all trades made by the user
     * @see https://developers.binance.com/docs/binance-spot-api-docs/rest-api/account-endpoints#account-trade-list-user_data
     * @see https://developers.binance.com/docs/derivatives/usds-margined-futures/trade/rest-api/Account-Trade-List
     * @see https://developers.binance.com/docs/derivatives/coin-margined-futures/trade/rest-api/Account-Trade-List
     * @see https://developers.binance.com/docs/margin_trading/trade/Query-Margin-Account-Trade-List
     * @see https://developers.binance.com/docs/derivatives/option/trade/Account-Trade-List
     * @see https://developers.binance.com/docs/derivatives/portfolio-margin/trade/UM-Account-Trade-List
     * @see https://developers.binance.com/docs/derivatives/portfolio-margin/trade/CM-Account-Trade-List
     * @see https://developers.binance.com/en/docs/catalog/advanced-trading-stocks-trading/api/rest-api/trade#equity-trade-history
     * @param {string} [symbol] unified market symbol
     * @param {int} [since] the earliest time in ms to fetch trades for
     * @param {int} [limit] the maximum number of trades structures to retrieve
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {boolean} [params.paginate] default false, when true will automatically paginate by calling this endpoint multiple times. See in the docs all the [available parameters](https://github.com/ccxt/ccxt/wiki/Manual#pagination-params)
     * @param {int} [params.until] the latest time in ms to fetch entries for
     * @param {boolean} [params.portfolioMargin] set to true if you would like to fetch trades for a portfolio margin account
     * @param {boolean} [params.stock] set to true if you would like to fetch tokenized stock trades
     * @returns {Trade[]} a list of [trade structures]{@link https://docs.ccxt.com/?id=trade-structure}
     */
    std::shared_future<std::any> fetchMyTrades(std::any symbol = std::any{}, std::any since = std::any{}, std::any limit = std::any{}, std::any params = ccxt::dict {}) override
    {
        return std::async(std::launch::deferred, [=]() mutable -> std::any {
            if (isTrue(isEqual(this->markets, std::any{})))
            {
                awaitValue(this->loadMarkets());
            }
            std::any paginate = false;
            std::any paginateparamsVariable = this->handleOptionAndParams(params, std::string("fetchMyTrades"), std::string("paginate"));
            paginate = ::getValue(paginateparamsVariable, 0);
            params = ::getValue(paginateparamsVariable, 1);
            if (isTrue(paginate))
            {
                return awaitValue(this->fetchPaginatedCallDynamic(std::string("fetchMyTrades"), symbol, since, limit, params));
            }
            std::any request = ccxt::dict {};
            std::any market = std::any{};
            std::any type = std::any{};
            std::any marginMode = std::any{};
            std::any stock = std::any{};
            std::any stockparamsVariable = this->handleOptionAndParams(params, std::string("fetchMyTrades"), std::string("stock"), false);
            stock = ::getValue(stockparamsVariable, 0);
            params = ::getValue(stockparamsVariable, 1);
            if (isTrue(!isEqual(symbol, std::any{})))
            {
                market = this->market(symbol);
                stock = this->safeBool(market, std::string("stock"), false);
                ::setValue(request, std::string("symbol"), ::getValue(market, std::string("id")));
            }
            std::any typeparamsVariable = this->handleMarketTypeAndParams(std::string("fetchMyTrades"), market, params);
            type = ::getValue(typeparamsVariable, 0);
            params = ::getValue(typeparamsVariable, 1);
            if (isTrue(isTrue(isTrue((!isEqual(stock, true))) && isTrue((!isEqual(type, std::string("option"))))) && isTrue((isEqual(symbol, std::any{})))))
            {
                throw ArgumentsRequired(toString(add(this->id, std::string(" fetchMyTrades() requires a symbol argument"))));
            }
            std::any endTime = this->safeInteger2(params, std::string("until"), std::string("endTime"));
            if (isTrue(!isEqual(since, std::any{})))
            {
                std::any startTime = since;
                ::setValue(request, std::string("startTime"), startTime);
                // If startTime and endTime are both not sent, then the last 7 days' data will be returned.
                // The time between startTime and endTime cannot be longer than 7 days.
                // The parameter fromId cannot be sent with startTime or endTime.
                std::any currentTimestamp = this->milliseconds();
                std::any oneWeek = multiply(multiply(multiply(multiply(7, 24), 60), 60), 1000);
                if (isTrue(isGreaterThanOrEqual((subtract(currentTimestamp, startTime)), oneWeek)))
                {
                    if (isTrue(isTrue((isEqual(endTime, std::any{}))) && isTrue((isEqual(this->safeBool(market, std::string("linear")), true)))))
                    {
                        endTime = this->sum(startTime, oneWeek);
                        std::any endTimeValue = (isTrue((isEqual(endTime, std::any{}))) ? std::any(0) : std::any(endTime));
                        endTime = mathMin(endTimeValue, currentTimestamp);
                    }
                }
            }
            if (isTrue(!isEqual(endTime, std::any{})))
            {
                ::setValue(request, std::string("endTime"), endTime);
                params = this->omit(params, ccxt::list{std::string("endTime"), std::string("until")});
            }
            if (isTrue(!isEqual(limit, std::any{})))
            {
                if (isTrue(isTrue((isEqual(type, std::string("option")))) || isTrue((isEqual(this->safeBool(market, std::string("contract")), true)))))
                {
                    limit = mathMin(limit, 1000); // above 1000, returns error
                }
                if (isTrue(isEqual(stock, true)))
                {
                    limit = mathMin(limit, 100); // max 100
                    ::setValue(request, std::string("size"), limit);
                } else
                {
                    ::setValue(request, std::string("limit"), limit);
                }
            }
            std::any response = std::any{};
            if (isTrue(isEqual(type, std::string("option"))))
            {
                response = awaitValue(this->eapiPrivateGetUserTrades(this->extend(request, params)));
            } else
            {
                std::any marginModeparamsVariable = this->handleMarginModeAndParams(std::string("fetchMyTrades"), params);
                marginMode = ::getValue(marginModeparamsVariable, 0);
                params = ::getValue(marginModeparamsVariable, 1);
                std::any isPortfolioMargin = std::any{};
                std::any isPortfolioMarginparamsVariable = this->handleOptionAndParams2(params, std::string("fetchMyTrades"), std::string("papi"), std::string("portfolioMargin"), false);
                isPortfolioMargin = ::getValue(isPortfolioMarginparamsVariable, 0);
                params = ::getValue(isPortfolioMarginparamsVariable, 1);
                if (isTrue(isEqual(stock, true)))
                {
                    if (isTrue(isEqual(endTime, std::any{})))
                    {
                        endTime = this->milliseconds();
                        ::setValue(request, std::string("endTime"), endTime);
                    }
                    if (isTrue(isEqual(since, std::any{})))
                    {
                        std::any oneWeek = multiply(multiply(multiply(multiply(7, 24), 60), 60), 1000);
                        ::setValue(request, std::string("startTime"), subtract(endTime, oneWeek));
                    }
                    response = awaitValue(this->sapiGetEquityTradeHistory(this->extend(request, params)));
                } else if (isTrue(isTrue(isEqual(type, std::string("spot"))) || isTrue(isEqual(type, std::string("margin")))))
                {
                    if (isTrue(isPortfolioMargin))
                    {
                        response = awaitValue(this->papiGetMarginMyTrades(this->extend(request, params)));
                    } else if (isTrue(isTrue((isEqual(type, std::string("margin")))) || isTrue((!isEqual(marginMode, std::any{})))))
                    {
                        if (isTrue(isEqual(marginMode, std::string("isolated"))))
                        {
                            ::setValue(request, std::string("isIsolated"), true);
                        }
                        response = awaitValue(this->sapiGetMarginMyTrades(this->extend(request, params)));
                    } else
                    {
                        response = awaitValue(this->privateGetMyTrades(this->extend(request, params)));
                    }
                } else if (isTrue(isEqual(this->safeBool(market, std::string("linear")), true)))
                {
                    if (isTrue(isPortfolioMargin))
                    {
                        response = awaitValue(this->papiGetUmUserTrades(this->extend(request, params)));
                    } else
                    {
                        response = awaitValue(this->fapiPrivateGetUserTrades(this->extend(request, params)));
                    }
                } else if (isTrue(isEqual(this->safeBool(market, std::string("inverse")), true)))
                {
                    if (isTrue(isPortfolioMargin))
                    {
                        response = awaitValue(this->papiGetCmUserTrades(this->extend(request, params)));
                    } else
                    {
                        response = awaitValue(this->dapiPrivateGetUserTrades(this->extend(request, params)));
                    }
                }
            }
            //
            // spot trade
            //
            //     [
            //         {
            //             "symbol": "BNBBTC",
            //             "id": 28457,
            //             "orderId": 100234,
            //             "price": "4.00000100",
            //             "qty": "12.00000000",
            //             "commission": "10.10000000",
            //             "commissionAsset": "BNB",
            //             "time": 1499865549590,
            //             "isBuyer": true,
            //             "isMaker": false,
            //             "isBestMatch": true,
            //         }
            //     ]
            //
            // futures trade
            //
            //     [
            //         {
            //             "accountId": 20,
            //             "buyer": False,
            //             "commission": "-0.07819010",
            //             "commissionAsset": "USDT",
            //             "counterPartyId": 653,
            //             "id": 698759,
            //             "maker": False,
            //             "orderId": 25851813,
            //             "price": "7819.01",
            //             "qty": "0.002",
            //             "quoteQty": "0.01563",
            //             "realizedPnl": "-0.91539999",
            //             "side": "SELL",
            //             "symbol": "BTCUSDT",
            //             "time": 1569514978020
            //         }
            //     ]
            //
            // options (eapi)
            //
            //     [
            //         {
            //             "id": 1125899906844226012,
            //             "tradeId": 73,
            //             "orderId": 4638761100843040768,
            //             "symbol": "ETH-230211-1500-C",
            //             "price": "18.70000000",
            //             "quantity": "-0.57000000",
            //             "fee": "0.17305890",
            //             "realizedProfit": "-3.53400000",
            //             "side": "SELL",
            //             "type": "LIMIT",
            //             "volatility": "0.30000000",
            //             "liquidity": "MAKER",
            //             "time": 1676085216845,
            //             "priceScale": 1,
            //             "quantityScale": 2,
            //             "optionSide": "CALL",
            //             "quoteAsset": "USDT"
            //         }
            //     ]
            //
            // linear portfolio margin
            //
            //     [
            //         {
            //             "symbol": "BTCUSDT",
            //             "id": 4575108247,
            //             "orderId": 261942655610,
            //             "side": "SELL",
            //             "price": "47263.40",
            //             "qty": "0.010",
            //             "realizedPnl": "27.38400000",
            //             "marginAsset": "USDT",
            //             "quoteQty": "472.63",
            //             "commission": "0.18905360",
            //             "commissionAsset": "USDT",
            //             "time": 1707530039409,
            //             "buyer": false,
            //             "maker": false,
            //             "positionSide": "LONG"
            //         }
            //     ]
            //
            // inverse portfolio margin
            //
            //     [
            //         {
            //             "symbol": "ETHUSD_PERP",
            //             "id": 701907838,
            //             "orderId": 71548909034,
            //             "pair": "ETHUSD",
            //             "side": "SELL",
            //             "price": "2498.15",
            //             "qty": "1",
            //             "realizedPnl": "0.00012517",
            //             "marginAsset": "ETH",
            //             "baseQty": "0.00400296",
            //             "commission": "0.00000160",
            //             "commissionAsset": "ETH",
            //             "time": 1707530317519,
            //             "positionSide": "LONG",
            //             "buyer": false,
            //             "maker": false
            //         }
            //     ]
            //
            // spot margin portfolio margin
            //
            //     [
            //         {
            //             "symbol": "ADAUSDT",
            //             "id": 470227543,
            //             "orderId": 4421170947,
            //             "price": "0.53880000",
            //             "qty": "10.00000000",
            //             "quoteQty": "5.38800000",
            //             "commission": "0.00538800",
            //             "commissionAsset": "USDT",
            //             "time": 1707545780522,
            //             "isBuyer": false,
            //             "isMaker": false,
            //             "isBestMatch": true
            //         }
            //     ]
            //
            // tokenized equities
            //
            //     {
            //         "page": 1,
            //         "size": 20,
            //         "total": 1,
            //         "rows": [
            //             {
            //                 "executionId": "cc942eb9-eaa0-47e7-8273-2a9bc10c5741",
            //                 "orderId": "ef66a86f-202b-4b41-b15c-e1c90f975f17",
            //                 "symbol": "AAPL",
            //                 "quote": "USDC",
            //                 "side": "BUY",
            //                 "orderType": "MARKET",
            //                 "price": "309.16",
            //                 "qty": "0.0576724",
            //                 "total": "17.83",
            //                 "executionAt": 1785936600545,
            //                 "updatedAt": 1785936601012
            //             }
            //         ]
            //     }
            std::any responseList = ccxt::list{};
            if (isTrue(!isEqual(response, std::any{})))
            {
                if (isTrue(isEqual(stock, true)))
                {
                    std::any rows = this->safeList(response, std::string("rows"), ccxt::list{});
                    responseList = rows;
                } else
                {
                    responseList = this->toArray(response);
                }
            }
            return this->parseTrades(responseList, market, since, limit);
        }).share();
    }

    /**
     * @method
     * @name binance#fetchMyDustTrades
     * @description fetch all dust trades made by the user
     * @see https://developers.binance.com/docs/wallet/asset/dust-log
     * @param {string} symbol not used by fetchMyDustTrades ()
     * @param {int} [since] the earliest time in ms to fetch my dust trades for
     * @param {int} [limit] the maximum number of dust trades to retrieve
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {string} [params.type] 'spot' or 'margin', default spot
     * @returns {object[]} a list of [trade structures]{@link https://docs.ccxt.com/?id=trade-structure}
     */
    virtual std::shared_future<std::any> fetchMyDustTrades(std::any symbol = std::any{}, std::any since = std::any{}, std::any limit = std::any{}, std::any params = ccxt::dict {})
    {
        return std::async(std::launch::deferred, [=]() mutable -> std::any {
            //
            // Binance provides an opportunity to trade insignificant (i.e. non-tradable and non-withdrawable)
            // token leftovers (of any asset) into `BNB` coin which in turn can be used to pay trading fees with it.
            // The corresponding trades history is called the `Dust Log` and can be requested via the following end-point:
            // https://github.com/binance-exchange/binance-official-api-docs/blob/master/wapi-api.md#dustlog-user_data
            //
            if (isTrue(isEqual(this->markets, std::any{})))
            {
                awaitValue(this->loadMarkets());
            }
            std::any request = ccxt::dict {};
            if (isTrue(!isEqual(since, std::any{})))
            {
                ::setValue(request, std::string("startTime"), since);
                ::setValue(request, std::string("endTime"), this->sum(since, 7776000000));
            }
            std::any accountType = this->safeStringUpper(params, std::string("type"));
            params = this->omit(params, std::string("type"));
            if (isTrue(!isEqual(accountType, std::any{})))
            {
                ::setValue(request, std::string("accountType"), accountType);
            }
            std::any response = awaitValue(this->sapiGetAssetDribblet(this->extend(request, params)));
            //     {
            //       "total": "4",
            //       "userAssetDribblets": [
            //         {
            //           "operateTime": "1627575731000",
            //           "totalServiceChargeAmount": "0.00001453",
            //           "totalTransferedAmount": "0.00072693",
            //           "transId": "70899815863",
            //           "userAssetDribbletDetails": [
            //             {
            //               "fromAsset": "LTC",
            //               "amount": "0.000006",
            //               "transferedAmount": "0.00000267",
            //               "serviceChargeAmount": "0.00000005",
            //               "operateTime": "1627575731000",
            //               "transId": "70899815863"
            //             },
            //             {
            //               "fromAsset": "GBP",
            //               "amount": "0.15949157",
            //               "transferedAmount": "0.00072426",
            //               "serviceChargeAmount": "0.00001448",
            //               "operateTime": "1627575731000",
            //               "transId": "70899815863"
            //             }
            //           ]
            //         },
            //       ]
            //     }
            std::any results = this->safeList(response, std::string("userAssetDribblets"), ccxt::list{});
            std::any rows = this->safeInteger(response, std::string("total"), 0);
            std::any data = ccxt::list{};
            for (std::any i = 0; isLessThan(i, rows); postFixIncrement(i))
            {
                std::any logs = this->safeList(::getValue(results, i), std::string("userAssetDribbletDetails"), ccxt::list{});
                for (std::any j = 0; isLessThan(j, getArrayLength(logs)); postFixIncrement(j))
                {
                    ::setValue(::getValue(logs, j), std::string("isDustTrade"), true);
                    arrayPush(data, ::getValue(logs, j));
                }
            }
            std::any trades = this->parseTrades(data, std::any{}, since, limit);
            return this->filterBySinceLimit(trades, since, limit);
        }).share();
    }

    virtual std::any parseDustTrade(std::any trade, std::any market = std::any{})
    {
        //
        //     {
        //       "fromAsset": "USDT",
        //       "amount": "0.009669",
        //       "transferedAmount": "0.00002992",
        //       "serviceChargeAmount": "0.00000059",
        //       "operateTime": "1628076010000",
        //       "transId": "71416578712",
        //       "isDustTrade": true
        //     }
        //
        std::any orderId = this->safeString(trade, std::string("transId"));
        std::any timestamp = this->safeInteger(trade, std::string("operateTime"));
        std::any currencyId = this->safeString(trade, std::string("fromAsset"));
        std::any tradedCurrency = this->safeCurrencyCode(currencyId);
        std::any bnb = this->currency(std::string("BNB"));
        std::any earnedCurrency = ::getValue(bnb, std::string("code"));
        std::any applicantSymbol = add(add(earnedCurrency, std::string("/")), tradedCurrency);
        std::any tradedCurrencyIsQuote = false;
        if (isTrue(isTrue((!isEqual(this->markets, std::any{}))) && isTrue((inOp(this->markets, applicantSymbol)))))
        {
            tradedCurrencyIsQuote = true;
        }
        std::any feeCostString = this->safeString(trade, std::string("serviceChargeAmount"));
        std::any fee = ccxt::dict {
            { std::string("currency"), earnedCurrency },
            { std::string("cost"), this->parseNumber(feeCostString) },
        };
        std::any symbol = std::any{};
        std::any amountString = std::any{};
        std::any costString = std::any{};
        std::any side = std::any{};
        if (isTrue(tradedCurrencyIsQuote))
        {
            symbol = applicantSymbol;
            amountString = this->safeString(trade, std::string("transferedAmount"));
            costString = this->safeString(trade, std::string("amount"));
            side = std::string("buy");
        } else
        {
            symbol = add(add(tradedCurrency, std::string("/")), earnedCurrency);
            amountString = this->safeString(trade, std::string("amount"));
            costString = this->safeString(trade, std::string("transferedAmount"));
            side = std::string("sell");
        }
        std::any priceString = std::any{};
        if (isTrue(!isEqual(costString, std::any{})))
        {
            if (isTrue(isTrue((!isEqual(amountString, std::any{}))) && isTrue((!isEqual(amountString, std::string(""))))))
            {
                priceString = ccxt::Precise::stringDiv(costString, amountString);
            }
        }
        std::any id = std::any{};
        std::any amount = this->parseNumber(amountString);
        std::any price = this->parseNumber(priceString);
        std::any cost = this->parseNumber(costString);
        std::any type = std::any{};
        std::any takerOrMaker = std::any{};
        return ccxt::dict {
            { std::string("id"), id },
            { std::string("timestamp"), timestamp },
            { std::string("datetime"), this->iso8601(timestamp) },
            { std::string("symbol"), symbol },
            { std::string("order"), orderId },
            { std::string("type"), type },
            { std::string("takerOrMaker"), takerOrMaker },
            { std::string("side"), side },
            { std::string("amount"), amount },
            { std::string("price"), price },
            { std::string("cost"), cost },
            { std::string("fee"), fee },
            { std::string("info"), trade },
        };
    }

    /**
     * @method
     * @name binance#fetchDeposits
     * @description fetch all deposits made to an account
     * @see https://developers.binance.com/docs/wallet/capital/deposite-history
     * @see https://developers.binance.com/docs/fiat/rest-api/Get-Fiat-Deposit-Withdraw-History
     * @param {string} code unified currency code
     * @param {int} [since] the earliest time in ms to fetch deposits for
     * @param {int} [limit] the maximum number of deposits structures to retrieve
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {bool} [params.fiat] if true, only fiat deposits will be returned
     * @param {int} [params.until] the latest time in ms to fetch entries for
     * @param {boolean} [params.paginate] default false, when true will automatically paginate by calling this endpoint multiple times. See in the docs all the [available parameters](https://github.com/ccxt/ccxt/wiki/Manual#pagination-params)
     * @returns {object[]} a list of [transaction structures]{@link https://docs.ccxt.com/?id=transaction-structure}
     */
    std::shared_future<std::any> fetchDeposits(std::any code = std::any{}, std::any since = std::any{}, std::any limit = std::any{}, std::any params = ccxt::dict {}) override
    {
        return std::async(std::launch::deferred, [=]() mutable -> std::any {
            if (isTrue(isEqual(this->markets, std::any{})))
            {
                awaitValue(this->loadMarkets());
            }
            std::any paginate = false;
            std::any paginateparamsVariable = this->handleOptionAndParams(params, std::string("fetchDeposits"), std::string("paginate"));
            paginate = ::getValue(paginateparamsVariable, 0);
            params = ::getValue(paginateparamsVariable, 1);
            if (isTrue(paginate))
            {
                return awaitValue(this->fetchPaginatedCallDynamic(std::string("fetchDeposits"), code, since, limit, params));
            }
            std::any currency = std::any{};
            std::any response = std::any{};
            std::any request = ccxt::dict {};
            std::any legalMoney = this->safeDict(this->options, std::string("legalMoney"), ccxt::dict {});
            std::any fiatOnly = this->safeBool(params, std::string("fiat"), false);
            params = this->omit(params, std::string("fiatOnly"));
            std::any until = this->safeInteger(params, std::string("until"));
            params = this->omit(params, std::string("until"));
            if (isTrue(isTrue((isEqual(fiatOnly, true))) || isTrue((isTrue((!isEqual(code, std::any{}))) && isTrue((inOp(legalMoney, code)))))))
            {
                if (isTrue(!isEqual(code, std::any{})))
                {
                    currency = this->currency(code);
                }
                ::setValue(request, std::string("transactionType"), 0);
                if (isTrue(!isEqual(since, std::any{})))
                {
                    ::setValue(request, std::string("beginTime"), since);
                }
                if (isTrue(!isEqual(until, std::any{})))
                {
                    ::setValue(request, std::string("endTime"), until);
                }
                std::any raw = awaitValue(this->sapiGetFiatOrders(this->extend(request, params)));
                response = this->safeList(raw, std::string("data"), ccxt::list{});
            } else
            {
                if (isTrue(!isEqual(code, std::any{})))
                {
                    currency = this->currency(code);
                    ::setValue(request, std::string("coin"), ::getValue(currency, std::string("id")));
                }
                if (isTrue(!isEqual(since, std::any{})))
                {
                    ::setValue(request, std::string("startTime"), since);
                    // max 3 months range https://github.com/ccxt/ccxt/issues/6495
                    std::any endTime = this->sum(since, 7776000000);
                    if (isTrue(!isEqual(until, std::any{})))
                    {
                        endTime = mathMin(endTime, until);
                    }
                    ::setValue(request, std::string("endTime"), endTime);
                }
                if (isTrue(!isEqual(limit, std::any{})))
                {
                    ::setValue(request, std::string("limit"), limit);
                }
                response = awaitValue(this->sapiGetCapitalDepositHisrec(this->extend(request, params)));
            }
            if (isTrue(isEqual(response, std::any{})))
            {
                throw NullResponse(toString(add(this->id, std::string(" method() returned empty response"))));
            }
            std::any responseList = ccxt::list{};
            if (isTrue(!isEqual(response, std::any{})))
            {
                responseList = this->toArray(response);
            }
            for (std::any i = 0; isLessThan(i, getArrayLength(responseList)); postFixIncrement(i))
            {
                ::setValue(::getValue(responseList, i), std::string("type"), std::string("deposit"));
            }
            return this->parseTransactions(responseList, currency, since, limit);
        }).share();
    }

    /**
     * @method
     * @name binance#fetchWithdrawals
     * @description fetch all withdrawals made from an account
     * @see https://developers.binance.com/docs/wallet/capital/withdraw-history
     * @see https://developers.binance.com/docs/fiat/rest-api/Get-Fiat-Deposit-Withdraw-History
     * @param {string} code unified currency code
     * @param {int} [since] the earliest time in ms to fetch withdrawals for
     * @param {int} [limit] the maximum number of withdrawals structures to retrieve
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {bool} [params.fiat] if true, only fiat withdrawals will be returned
     * @param {int} [params.until] the latest time in ms to fetch withdrawals for
     * @param {boolean} [params.paginate] default false, when true will automatically paginate by calling this endpoint multiple times. See in the docs all the [available parameters](https://github.com/ccxt/ccxt/wiki/Manual#pagination-params)
     * @returns {object[]} a list of [transaction structures]{@link https://docs.ccxt.com/?id=transaction-structure}
     */
    std::shared_future<std::any> fetchWithdrawals(std::any code = std::any{}, std::any since = std::any{}, std::any limit = std::any{}, std::any params = ccxt::dict {}) override
    {
        return std::async(std::launch::deferred, [=]() mutable -> std::any {
            if (isTrue(isEqual(this->markets, std::any{})))
            {
                awaitValue(this->loadMarkets());
            }
            std::any paginate = false;
            std::any paginateparamsVariable = this->handleOptionAndParams(params, std::string("fetchWithdrawals"), std::string("paginate"));
            paginate = ::getValue(paginateparamsVariable, 0);
            params = ::getValue(paginateparamsVariable, 1);
            if (isTrue(paginate))
            {
                return awaitValue(this->fetchPaginatedCallDynamic(std::string("fetchWithdrawals"), code, since, limit, params));
            }
            std::any legalMoney = this->safeDict(this->options, std::string("legalMoney"), ccxt::dict {});
            std::any fiatOnly = this->safeBool(params, std::string("fiat"), false);
            params = this->omit(params, std::string("fiatOnly"));
            std::any request = ccxt::dict {};
            std::any until = this->safeInteger(params, std::string("until"));
            if (isTrue(!isEqual(until, std::any{})))
            {
                params = this->omit(params, std::string("until"));
                ::setValue(request, std::string("endTime"), until);
            }
            std::any response = std::any{};
            std::any currency = std::any{};
            if (isTrue(isTrue((isEqual(fiatOnly, true))) || isTrue((isTrue((!isEqual(code, std::any{}))) && isTrue((inOp(legalMoney, code)))))))
            {
                if (isTrue(!isEqual(code, std::any{})))
                {
                    currency = this->currency(code);
                }
                ::setValue(request, std::string("transactionType"), 1);
                if (isTrue(!isEqual(since, std::any{})))
                {
                    ::setValue(request, std::string("beginTime"), since);
                }
                std::any raw = awaitValue(this->sapiGetFiatOrders(this->extend(request, params)));
                response = this->safeList(raw, std::string("data"), ccxt::list{});
            } else
            {
                if (isTrue(!isEqual(code, std::any{})))
                {
                    currency = this->currency(code);
                    ::setValue(request, std::string("coin"), ::getValue(currency, std::string("id")));
                }
                if (isTrue(!isEqual(since, std::any{})))
                {
                    ::setValue(request, std::string("startTime"), since);
                    // max 3 months range https://github.com/ccxt/ccxt/issues/6495
                    ::setValue(request, std::string("endTime"), this->sum(since, 7776000000));
                }
                if (isTrue(!isEqual(limit, std::any{})))
                {
                    ::setValue(request, std::string("limit"), limit);
                }
                response = awaitValue(this->sapiGetCapitalWithdrawHistory(this->extend(request, params)));
            }
            if (isTrue(isEqual(response, std::any{})))
            {
                throw NullResponse(toString(add(this->id, std::string(" method() returned empty response"))));
            }
            if (isTrue(isString(response)))
            {
                response = this->parseJson(response);
            }
            std::any responseList = ccxt::list{};
            if (isTrue(!isEqual(response, std::any{})))
            {
                responseList = this->toArray(response);
            }
            for (std::any i = 0; isLessThan(i, getArrayLength(responseList)); postFixIncrement(i))
            {
                ::setValue(::getValue(responseList, i), std::string("type"), std::string("withdrawal"));
            }
            return this->parseTransactions(responseList, currency, since, limit);
        }).share();
    }

    virtual std::any parseTransactionStatusByType(std::any status, std::any type = std::any{})
    {
        if (isTrue(isEqual(type, std::any{})))
        {
            return status;
        }
        std::any statusesByType = ccxt::dict {
            { std::string("deposit"), ccxt::dict {
                { std::string("0"), std::string("pending") },
                { std::string("1"), std::string("ok") },
                { std::string("6"), std::string("ok") },
                { std::string("Processing"), std::string("pending") },
                { std::string("Failed"), std::string("failed") },
                { std::string("Successful"), std::string("ok") },
                { std::string("Refunding"), std::string("canceled") },
                { std::string("Refunded"), std::string("canceled") },
                { std::string("Refund Failed"), std::string("failed") },
            } },
            { std::string("withdrawal"), ccxt::dict {
                { std::string("0"), std::string("pending") },
                { std::string("1"), std::string("canceled") },
                { std::string("2"), std::string("pending") },
                { std::string("3"), std::string("failed") },
                { std::string("4"), std::string("pending") },
                { std::string("5"), std::string("failed") },
                { std::string("6"), std::string("ok") },
                { std::string("Processing"), std::string("pending") },
                { std::string("Failed"), std::string("failed") },
                { std::string("Successful"), std::string("ok") },
                { std::string("Refunding"), std::string("canceled") },
                { std::string("Refunded"), std::string("canceled") },
                { std::string("Refund Failed"), std::string("failed") },
            } },
        };
        std::any statuses = this->safeDict(statusesByType, type, ccxt::dict {});
        return this->safeString(statuses, status, status);
    }

    std::any parseTransaction(std::any transaction, std::any currency = std::any{}) override
    {
        //
        // fetchDeposits
        //
        //     {
        //       "amount": "4500",
        //       "coin": "USDT",
        //       "network": "BSC",
        //       "status": 1,
        //       "address": "0xc9c923c87347ca0f3451d6d308ce84f691b9f501",
        //       "addressTag": "",
        //       "txId": "Internal transfer 51376627901",
        //       "insertTime": 1618394381000,
        //       "transferType": 1,
        //       "confirmTimes": "1/15"
        //     }
        //
        // fetchWithdrawals
        //
        //     {
        //       "id": "69e53ad305124b96b43668ceab158a18",
        //       "amount": "28.75",
        //       "transactionFee": "0.25",
        //       "coin": "XRP",
        //       "status": 6,
        //       "address": "r3T75fuLjX51mmfb5Sk1kMNuhBgBPJsjza",
        //       "addressTag": "101286922",
        //       "txId": "19A5B24ED0B697E4F0E9CD09FCB007170A605BC93C9280B9E6379C5E6EF0F65A",
        //       "applyTime": "2021-04-15 12:09:16",
        //       "network": "XRP",
        //       "transferType": 0
        //     }
        //
        // fiat transaction
        // withdraw
        //     {
        //       "orderNo": "CJW684897551397171200",
        //       "fiatCurrency": "GBP",
        //       "indicatedAmount": "29.99",
        //       "amount": "28.49",
        //       "totalFee": "1.50",
        //       "method": "bank transfer",
        //       "status": "Successful",
        //       "createTime": 1614898701000,
        //       "updateTime": 1614898820000
        //     }
        //
        // deposit
        //     {
        //       "orderNo": "25ced37075c1470ba8939d0df2316e23",
        //       "fiatCurrency": "EUR",
        //       "transactionType": 0,
        //       "indicatedAmount": "15.00",
        //       "amount": "15.00",
        //       "totalFee": "0.00",
        //       "method": "card",
        //       "status": "Failed",
        //       "createTime": "1627501026000",
        //       "updateTime": "1627501027000"
        //     }
        //
        // withdraw
        //
        //    { id: "9a67628b16ba4988ae20d329333f16bc" }
        //
        std::any id = this->safeString2(transaction, std::string("id"), std::string("orderNo"));
        std::any address = this->safeString(transaction, std::string("address"));
        std::any tag = this->safeString(transaction, std::string("addressTag")); // set but unused
        if (isTrue(!isEqual(tag, std::any{})))
        {
            if (isTrue(isLessThan(getStringLength(tag), 1)))
            {
                tag = std::any{};
            }
        }
        std::any txid = this->safeString(transaction, std::string("txId"));
        if (isTrue(isTrue((!isEqual(txid, std::any{}))) && isTrue((isGreaterThanOrEqual(getIndexOf(txid, std::string("Internal transfer ")), 0)))))
        {
            txid = slice(txid, 18, std::any{});
        }
        std::any currencyId = this->safeString2(transaction, std::string("coin"), std::string("fiatCurrency"));
        std::any code = this->safeCurrencyCode(currencyId, currency);
        std::any timestamp = std::any{};
        timestamp = this->safeInteger2(transaction, std::string("insertTime"), std::string("createTime"));
        if (isTrue(isEqual(timestamp, std::any{})))
        {
            timestamp = this->parse8601(this->safeString(transaction, std::string("applyTime")));
        }
        std::any updated = this->safeInteger2(transaction, std::string("successTime"), std::string("updateTime"));
        std::any type = this->safeString(transaction, std::string("type"));
        if (isTrue(isEqual(type, std::any{})))
        {
            std::any txType = this->safeString(transaction, std::string("transactionType"));
            if (isTrue(!isEqual(txType, std::any{})))
            {
                type = (isTrue((isEqual(txType, std::string("0")))) ? std::any(std::string("deposit")) : std::any(std::string("withdrawal")));
            }
            std::any legalMoneyCurrenciesById = this->safeDict(this->options, std::string("legalMoneyCurrenciesById"));
            code = this->safeString(legalMoneyCurrenciesById, code, code);
        }
        std::any status = this->parseTransactionStatusByType(this->safeString(transaction, std::string("status")), type);
        std::any amount = this->safeNumber(transaction, std::string("amount"));
        std::any feeCost = this->safeNumber2(transaction, std::string("transactionFee"), std::string("totalFee"));
        std::any fee = std::any{};
        if (isTrue(!isEqual(feeCost, std::any{})))
        {
            fee = ccxt::dict {
                { std::string("currency"), code },
                { std::string("cost"), feeCost },
            };
        }
        std::any internalInteger = this->safeInteger(transaction, std::string("transferType"));
        std::any internal = std::any{};
        if (isTrue(!isEqual(internalInteger, std::any{})))
        {
            internal = (isTrue((!isEqual(internalInteger, 0))) ? std::any(true) : std::any(false));
        }
        std::any networkId = this->safeString(transaction, std::string("network"));
        std::any network = this->networkIdToCode(networkId, code);
        return ccxt::dict {
            { std::string("info"), transaction },
            { std::string("id"), id },
            { std::string("txid"), txid },
            { std::string("timestamp"), timestamp },
            { std::string("datetime"), this->iso8601(timestamp) },
            { std::string("network"), network },
            { std::string("address"), address },
            { std::string("addressTo"), address },
            { std::string("addressFrom"), std::any{} },
            { std::string("tag"), tag },
            { std::string("tagTo"), tag },
            { std::string("tagFrom"), std::any{} },
            { std::string("type"), type },
            { std::string("amount"), amount },
            { std::string("currency"), code },
            { std::string("status"), status },
            { std::string("updated"), updated },
            { std::string("internal"), internal },
            { std::string("comment"), std::any{} },
            { std::string("fee"), fee },
        };
    }

    virtual std::any parseTransferStatus(std::any status)
    {
        std::any statuses = ccxt::dict {
            { std::string("CONFIRMED"), std::string("ok") },
        };
        return this->safeString(statuses, status, status);
    }

    std::any parseTransfer(std::any transfer, std::any currency = std::any{}) override
    {
        //
        // transfer
        //
        //     {
        //         "tranId":13526853623
        //     }
        //
        // fetchTransfers
        //
        //     {
        //         "timestamp": 1614640878000,
        //         "asset": "USDT",
        //         "amount": "25",
        //         "type": "MAIN_UMFUTURE",
        //         "status": "CONFIRMED",
        //         "tranId": 43000126248
        //     }
        //
        //     {
        //             "orderType": "C2C", // Enum：PAY(C2B Merchant Acquiring Payment), PAY_REFUND(C2B Merchant Acquiring Payment,refund), C2C(C2C Transfer Payment),CRYPTO_BOX(Crypto box), CRYPTO_BOX_RF(Crypto Box, refund), C2C_HOLDING(Transfer to new Binance user), C2C_HOLDING_RF(Transfer to new Binance user,refund), PAYOUT(B2C Disbursement Payment), REMITTANCE（Send cash)
        //             "transactionId": "M_P_71505104267788288",
        //             "transactionTime": 1610090460133, //trade timestamp
        //             "amount": "23.72469206", //order amount(up to 8 decimal places), positive is income, negative is expenditure
        //             "currency": "BNB",
        //             "walletType": 1, //main wallet type, 1 for funding wallet, 2 for spot wallet, 3 for fiat wallet, 4 or 6 for card payment, 5 for earn wallet
        //             "walletTypes": [1,2], //array format，there are multiple values when using combination payment
        //             "fundsDetail": [ // details
        //                     {
        //                         "currency": "USDT", //asset
        //                         "amount": "1.2",
        //                         "walletAssetCost":[ //details of asset cost per wallet
        //                             {"1":"0.6"},
        //                             {"2":"0.6"}
        //                         ]
        //                     },
        //                     {
        //                         "currency": "ETH",
        //                         "amount": "0.0001",
        //                         "walletAssetCost":[
        //                             {"1":"0.00005"},
        //                             {"2":"0.00005"}
        //                         ]
        //                     }
        //                 ],
        //             "payerInfo":{
        //                     "name":"Jack", //nickname or merchant name
        //                     "type":"USER", //account type，USER for personal，MERCHANT for merchant
        //                     "binanceId":"12345678", //binance uid
        //                     "accountId":"67736251" //binance pay id
        //                 },
        //             "receiverInfo":{
        //                     "name":"Alan", //nickname or merchant name
        //                     "type":"MERCHANT", //account type，USER for personal，MERCHANT for merchant
        //                     "email":"alan@binance.com", //email
        //                     "binanceId":"34355667", //binance uid
        //                     "accountId":"21326891", //binance pay id
        //                     "countryCode":"1", //International area code
        //                     "phoneNumber":"8057651210",
        //                     "mobileCode":"US", //country code
        //                     "extend":[ //extension field
        //                             "institutionName": "",
        //                             "cardNumber": "",
        //                             "digitalWalletId": ""
        //                     ]
        //                 }
        //             }
        std::any id = this->safeString2(transfer, std::string("tranId"), std::string("transactionId"));
        std::any currencyId = this->safeString2(transfer, std::string("asset"), std::string("currency"));
        std::any code = this->safeCurrencyCode(currencyId, currency);
        std::any amount = this->safeNumber(transfer, std::string("amount"));
        std::any type = this->safeString(transfer, std::string("type"));
        std::any fromAccount = std::any{};
        std::any toAccount = std::any{};
        std::any accountsById = this->safeDict(this->options, std::string("accountsById"), ccxt::dict {});
        if (isTrue(!isEqual(type, std::any{})))
        {
            std::any parts = split(type, std::string("_"));
            fromAccount = this->safeValue(parts, 0);
            toAccount = this->safeValue(parts, 1);
            fromAccount = this->safeString(accountsById, fromAccount, fromAccount);
            toAccount = this->safeString(accountsById, toAccount, toAccount);
        }
        std::any walletType = this->safeInteger(transfer, std::string("walletType"));
        if (isTrue(!isEqual(walletType, std::any{})))
        {
            std::any payer = this->safeDict(transfer, std::string("payerInfo"), ccxt::dict {});
            std::any receiver = this->safeDict(transfer, std::string("receiverInfo"), ccxt::dict {});
            fromAccount = this->safeString(payer, std::string("accountId"));
            toAccount = this->safeString(receiver, std::string("accountId"));
        }
        std::any timestamp = this->safeInteger2(transfer, std::string("timestamp"), std::string("transactionTime"));
        std::any status = this->parseTransferStatus(this->safeString(transfer, std::string("status")));
        return ccxt::dict {
            { std::string("info"), transfer },
            { std::string("id"), id },
            { std::string("timestamp"), timestamp },
            { std::string("datetime"), this->iso8601(timestamp) },
            { std::string("currency"), code },
            { std::string("amount"), amount },
            { std::string("fromAccount"), fromAccount },
            { std::string("toAccount"), toAccount },
            { std::string("status"), status },
        };
    }

    std::any parseIncome(std::any income, std::any market = std::any{}) override
    {
        //
        //     {
        //       "symbol": "ETHUSDT",
        //       "incomeType": "FUNDING_FEE",
        //       "income": "0.00134317",
        //       "asset": "USDT",
        //       "time": "1621584000000",
        //       "info": "FUNDING_FEE",
        //       "tranId": "4480321991774044580",
        //       "tradeId": ""
        //     }
        //
        std::any marketId = this->safeString(income, std::string("symbol"));
        std::any currencyId = this->safeString(income, std::string("asset"));
        std::any timestamp = this->safeInteger(income, std::string("time"));
        return ccxt::dict {
            { std::string("info"), income },
            { std::string("symbol"), this->safeSymbol(marketId, market, std::any{}, std::string("swap")) },
            { std::string("code"), this->safeCurrencyCode(currencyId) },
            { std::string("timestamp"), timestamp },
            { std::string("datetime"), this->iso8601(timestamp) },
            { std::string("id"), this->safeString(income, std::string("tranId")) },
            { std::string("amount"), this->safeNumber(income, std::string("income")) },
        };
    }

    /**
     * @method
     * @name binance#transfer
     * @description transfer currency internally between wallets on the same account
     * @see https://developers.binance.com/docs/wallet/asset/user-universal-transfer
     * @param {string} code unified currency code
     * @param {float} amount amount to transfer
     * @param {string} fromAccount account to transfer from
     * @param {string} toAccount account to transfer to
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {string} [params.type] exchange specific transfer type
     * @param {string} [params.symbol] the unified symbol, required for isolated margin transfers
     * @returns {object} a [transfer structure]{@link https://docs.ccxt.com/?id=transfer-structure}
     */
    std::shared_future<std::any> transfer(std::any code, std::any amount, std::any fromAccount, std::any toAccount, std::any params = ccxt::dict {}) override
    {
        return std::async(std::launch::deferred, [=]() mutable -> std::any {
            if (isTrue(isEqual(this->markets, std::any{})))
            {
                awaitValue(this->loadMarkets());
            }
            std::any currency = this->currency(code);
            std::any request = ccxt::dict {
                { std::string("asset"), ::getValue(currency, std::string("id")) },
                { std::string("amount"), this->currencyToPrecision(code, amount) },
            };
            ::setValue(request, std::string("type"), this->safeString(params, std::string("type")));
            params = this->omit(params, std::string("type"));
            if (isTrue(isEqual(::getValue(request, std::string("type")), std::any{})))
            {
                std::any symbol = this->safeString(params, std::string("symbol"));
                std::any market = std::any{};
                if (isTrue(!isEqual(symbol, std::any{})))
                {
                    market = this->market(symbol);
                    params = this->omit(params, std::string("symbol"));
                }
                std::any fromId = toUpperCase(this->convertTypeToAccount(fromAccount));
                std::any toId = toUpperCase(this->convertTypeToAccount(toAccount));
                std::any isolatedSymbol = std::any{};
                if (isTrue(!isEqual(market, std::any{})))
                {
                    isolatedSymbol = ::getValue(market, std::string("id"));
                }
                if (isTrue(isEqual(fromId, std::string("ISOLATED"))))
                {
                    if (isTrue(isEqual(symbol, std::any{})))
                    {
                        throw ArgumentsRequired(toString(add(add(this->id, std::string(" transfer () requires params[\"symbol\"] when fromAccount is ")), fromAccount)));
                    }
                }
                if (isTrue(isEqual(toId, std::string("ISOLATED"))))
                {
                    if (isTrue(isEqual(symbol, std::any{})))
                    {
                        throw ArgumentsRequired(toString(add(add(this->id, std::string(" transfer () requires params[\"symbol\"] when toAccount is ")), toAccount)));
                    }
                }
                std::any accountsById = this->safeDict(this->options, std::string("accountsById"), ccxt::dict {});
                std::any fromIsolated = !isTrue((inOp(accountsById, fromId)));
                std::any toIsolated = !isTrue((inOp(accountsById, toId)));
                if (isTrue(isTrue(fromIsolated) && isTrue((isEqual(market, std::any{})))))
                {
                    isolatedSymbol = fromId; // allow user provide symbol as the from/to account
                }
                if (isTrue(isTrue(toIsolated) && isTrue((isEqual(market, std::any{})))))
                {
                    isolatedSymbol = toId;
                }
                if (isTrue(isTrue(fromIsolated) || isTrue(toIsolated)))
                {
                    std::any fromFuture = isTrue(isEqual(fromId, std::string("UMFUTURE"))) || isTrue(isEqual(fromId, std::string("CMFUTURE")));
                    std::any toFuture = isTrue(isEqual(toId, std::string("UMFUTURE"))) || isTrue(isEqual(toId, std::string("CMFUTURE")));
                    std::any fromSpot = isEqual(fromId, std::string("MAIN"));
                    std::any toSpot = isEqual(toId, std::string("MAIN"));
                    std::any funding = isTrue(isEqual(fromId, std::string("FUNDING"))) || isTrue(isEqual(toId, std::string("FUNDING")));
                    std::any option = isTrue(isEqual(fromId, std::string("OPTION"))) || isTrue(isEqual(toId, std::string("OPTION")));
                    std::any prohibitedWithIsolated = isTrue(isTrue(isTrue(fromFuture) || isTrue(toFuture)) || isTrue(funding)) || isTrue(option);
                    if (isTrue(isTrue((isTrue(fromIsolated) || isTrue(toIsolated))) && isTrue(prohibitedWithIsolated)))
                    {
                        throw BadRequest(toString(add(add(add(add(this->id, std::string(" transfer () does not allow transfers between ")), fromAccount), std::string(" and ")), toAccount)));
                    } else if (isTrue(isTrue(toSpot) && isTrue(fromIsolated)))
                    {
                        fromId = std::string("ISOLATED_MARGIN");
                        ::setValue(request, std::string("fromSymbol"), isolatedSymbol);
                    } else if (isTrue(isTrue(fromSpot) && isTrue(toIsolated)))
                    {
                        toId = std::string("ISOLATED_MARGIN");
                        ::setValue(request, std::string("toSymbol"), isolatedSymbol);
                    } else
                    {
                        if (isTrue(isTrue(fromIsolated) && isTrue(toIsolated)))
                        {
                            ::setValue(request, std::string("fromSymbol"), fromId);
                            ::setValue(request, std::string("toSymbol"), toId);
                            fromId = std::string("ISOLATEDMARGIN");
                            toId = std::string("ISOLATEDMARGIN");
                        } else
                        {
                            if (isTrue(fromIsolated))
                            {
                                ::setValue(request, std::string("fromSymbol"), isolatedSymbol);
                                fromId = std::string("ISOLATEDMARGIN");
                            }
                            if (isTrue(toIsolated))
                            {
                                ::setValue(request, std::string("toSymbol"), isolatedSymbol);
                                toId = std::string("ISOLATEDMARGIN");
                            }
                        }
                    }
                    ::setValue(request, std::string("type"), add(add(fromId, std::string("_")), toId));
                } else
                {
                    ::setValue(request, std::string("type"), add(add(fromId, std::string("_")), toId));
                }
            }
            std::any response = awaitValue(this->sapiPostAssetTransfer(this->extend(request, params)));
            //
            //     {
            //         "tranId":13526853623
            //     }
            //
            return this->parseTransfer(response, currency);
        }).share();
    }

    /**
     * @method
     * @name binance#fetchTransfers
     * @description fetch a history of internal transfers made on an account
     * @see https://developers.binance.com/docs/wallet/asset/query-user-universal-transfer
     * @param {string} code unified currency code of the currency transferred
     * @param {int} [since] the earliest time in ms to fetch transfers for
     * @param {int} [limit] the maximum number of transfers structures to retrieve
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {int} [params.until] the latest time in ms to fetch transfers for
     * @param {boolean} [params.paginate] default false, when true will automatically paginate by calling this endpoint multiple times. See in the docs all the [available parameters](https://github.com/ccxt/ccxt/wiki/Manual#pagination-params)
     * @param {boolean} [params.internal] default false, when true will fetch pay trade history
     * @returns {object[]} a list of [transfer structures]{@link https://docs.ccxt.com/?id=transfer-structure}
     */
    std::shared_future<std::any> fetchTransfers(std::any code = std::any{}, std::any since = std::any{}, std::any limit = std::any{}, std::any params = ccxt::dict {}) override
    {
        return std::async(std::launch::deferred, [=]() mutable -> std::any {
            if (isTrue(isEqual(this->markets, std::any{})))
            {
                awaitValue(this->loadMarkets());
            }
            std::any internal = this->safeBool(params, std::string("internal"));
            params = this->omit(params, std::string("internal"));
            std::any paginate = false;
            std::any paginateparamsVariable = this->handleOptionAndParams(params, std::string("fetchTransfers"), std::string("paginate"));
            paginate = ::getValue(paginateparamsVariable, 0);
            params = ::getValue(paginateparamsVariable, 1);
            if (isTrue(isTrue(paginate) && isTrue((!isEqual(internal, true)))))
            {
                return awaitValue(this->fetchPaginatedCallDynamic(std::string("fetchTransfers"), code, since, limit, params));
            }
            std::any currency = std::any{};
            if (isTrue(!isEqual(code, std::any{})))
            {
                currency = this->currency(code);
            }
            std::any request = ccxt::dict {};
            std::any limitKey = std::string("limit");
            if (isTrue(!isEqual(internal, true)))
            {
                std::any defaultType = this->safeString2(this->options, std::string("fetchTransfers"), std::string("defaultType"), std::string("spot"));
                std::any fromAccount = this->safeString(params, std::string("fromAccount"), defaultType);
                std::any defaultTo = (isTrue((isEqual(fromAccount, std::string("future")))) ? std::any(std::string("spot")) : std::any(std::string("future")));
                std::any toAccount = this->safeString(params, std::string("toAccount"), defaultTo);
                std::any type = this->safeString(params, std::string("type"));
                std::any accountsByType = this->safeDict(this->options, std::string("accountsByType"), ccxt::dict {});
                std::any fromId = this->safeString(accountsByType, fromAccount);
                std::any toId = this->safeString(accountsByType, toAccount);
                if (isTrue(isEqual(type, std::any{})))
                {
                    if (isTrue(isEqual(fromId, std::any{})))
                    {
                        std::any keys = getObjectKeys(accountsByType);
                        throw ExchangeError(toString(add(add(this->id, std::string(" fromAccount parameter must be one of ")), join(keys, std::string(", ")))));
                    }
                    if (isTrue(isEqual(toId, std::any{})))
                    {
                        std::any keys = getObjectKeys(accountsByType);
                        throw ExchangeError(toString(add(add(this->id, std::string(" toAccount parameter must be one of ")), join(keys, std::string(", ")))));
                    }
                    type = add(add(fromId, std::string("_")), toId);
                }
                ::setValue(request, std::string("type"), type);
                limitKey = std::string("size");
            }
            if (isTrue(!isEqual(limit, std::any{})))
            {
                ::setValue(request, limitKey, limit);
            }
            if (isTrue(!isEqual(since, std::any{})))
            {
                ::setValue(request, std::string("startTime"), since);
            }
            std::any until = this->safeInteger(params, std::string("until"));
            if (isTrue(!isEqual(until, std::any{})))
            {
                params = this->omit(params, std::string("until"));
                ::setValue(request, std::string("endTime"), until);
            }
            std::any response = std::any{};
            if (isTrue(isEqual(internal, true)))
            {
                response = awaitValue(this->sapiGetPayTransactions(this->extend(request, params)));
            } else
            {
                response = awaitValue(this->sapiGetAssetTransfer(this->extend(request, params)));
            }
            std::any rows = this->safeList2(response, std::string("rows"), std::string("data"), ccxt::list{});
            return this->parseTransfers(rows, currency, since, limit);
        }).share();
    }

    /**
     * @method
     * @name binance#fetchDepositAddress
     * @description fetch the deposit address for a currency associated with this account
     * @see https://developers.binance.com/docs/wallet/capital/deposite-address
     * @param {string} code unified currency code
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {string} [params.network] network for fetch deposit address
     * @returns {object} an [address structure]{@link https://docs.ccxt.com/?id=address-structure}
     */
    std::shared_future<std::any> fetchDepositAddress(std::any code, std::any params = ccxt::dict {}) override
    {
        return std::async(std::launch::deferred, [=]() mutable -> std::any {
            if (isTrue(isEqual(this->markets, std::any{})))
            {
                awaitValue(this->loadMarkets());
            }
            std::any currency = this->currency(code);
            std::any request = ccxt::dict {
                { std::string("coin"), ::getValue(currency, std::string("id")) },
            };
            std::any networkCode = std::any{};
            std::any networkCodeparamsVariable = this->handleNetworkCodeAndParams(params);
            networkCode = ::getValue(networkCodeparamsVariable, 0);
            params = ::getValue(networkCodeparamsVariable, 1);
            if (isTrue(!isEqual(networkCode, std::any{})))
            {
                ::setValue(request, std::string("network"), this->networkCodeToId(networkCode, ::getValue(currency, std::string("code"))));
            }
            // has support for the 'network' parameter
            std::any response = awaitValue(this->sapiGetCapitalDepositAddress(this->extend(request, params)));
            //
            //     {
            //         "currency": "XRP",
            //         "address": "rEb8TK3gBgk5auZkwc6sHnwrGVJH8DuaLh",
            //         "tag": "108618262",
            //         "info": {
            //             "coin": "XRP",
            //             "address": "rEb8TK3gBgk5auZkwc6sHnwrGVJH8DuaLh",
            //             "tag": "108618262",
            //             "url": "https://bithomp.com/explorer/rEb8TK3gBgk5auZkwc6sHnwrGVJH8DuaLh"
            //         }
            //     }
            //
            return this->parseDepositAddress(response, currency);
        }).share();
    }

    std::any parseDepositAddress(std::any response, std::any currency = std::any{}) override
    {
        //
        //     {
        //         "coin": "XRP",
        //         "address": "rEb8TK3gBgk5auZkwc6sHnwrGVJH8DuaLh",
        //         "tag": "108618262",
        //         "url": "https://bithomp.com/explorer/rEb8TK3gBgk5auZkwc6sHnwrGVJH8DuaLh"
        //     }
        //
        std::any url = this->safeString(response, std::string("url"));
        std::any address = this->safeString(response, std::string("address"));
        std::any currencyId = this->safeString(response, std::string("currency"));
        std::any code = this->safeCurrencyCode(currencyId, currency);
        // deposit-address endpoint provides only network url (not network ID/CODE)
        // so we should map the url to network (their data is inside currencies)
        std::any networkCode = this->getNetworkCodeByNetworkUrl(code, url);
        std::any tag = this->safeString(response, std::string("tag"), std::string(""));
        if (isTrue(isEqual(getStringLength(tag), 0)))
        {
            tag = std::any{};
        }
        this->checkAddress(address);
        return ccxt::dict {
            { std::string("info"), response },
            { std::string("currency"), code },
            { std::string("network"), networkCode },
            { std::string("address"), address },
            { std::string("tag"), tag },
        };
    }

