            //         },
            //         {
            //           "network": "BSC",
            //           "coin": "BAT",
            //           "withdrawIntegerMultiple": "0.00000001",
            //           "isDefault": false,
            //           "depositEnable": true,
            //           "withdrawEnable": true,
            //           "depositDesc": '',
