    std::any parseDepositWithdrawFee(std::any fee, std::any currency = std::any{}) override
    {
        //
        //    {
        //        "coin": "BAT",
        //        "depositAllEnable": true,
        //        "withdrawAllEnable": true,
        //        "name": "Basic Attention Token",
        //        "free": "0",
        //        "locked": "0",
        //        "freeze": "0",
        //        "withdrawing": "0",
        //        "ipoing": "0",
        //        "ipoable": "0",
        //        "storage": "0",
        //        "isLegalMoney": false,
        //        "trading": true,
        //        "networkList": [
        //            {
        //                "network": "BNB",
        //                "coin": "BAT",
        //                "withdrawIntegerMultiple": "0.00000001",
        //                "isDefault": false,
        //                "depositEnable": true,
        //                "withdrawEnable": true,
        //                "depositDesc": '',
        //                "withdrawDesc": '',
        //                "specialTips": "The name of this asset is Basic Attention Token (BAT). Both a MEMO and an Address are required to successfully deposit your BEP2 tokens to Binance.",
        //                "name": "BEP2",
        //                "resetAddressStatus": false,
        //                "addressRegex": "^(bnb1)[0-9a-z]{38}$",
        //                "memoRegex": "^[0-9A-Za-z\\-_]{1,120}$",
        //                "withdrawFee": "0.27",
        //                "withdrawMin": "0.54",
        //                "withdrawMax": "10000000000",
        //                "minConfirm": "1",
        //                "unLockConfirm": "0"
        //            },
        //            ...
        //        ]
        //    }
        //
        std::any code = this->safeString(currency, std::string("code"));
        std::any networkList = this->safeList(fee, std::string("networkList"), ccxt::list{});
        std::any result = this->depositWithdrawFee(fee);
        for (std::any j = 0; isLessThan(j, getArrayLength(networkList)); postFixIncrement(j))
        {
            std::any networkEntry = ::getValue(networkList, j);
            std::any networkId = this->safeString(networkEntry, std::string("network"));
            std::any networkCode = this->networkIdToCode(networkId, code);
            std::any withdrawFee = this->safeNumber(networkEntry, std::string("withdrawFee"));
            std::any isDefault = this->safeBool(networkEntry, std::string("isDefault"));
            if (isTrue(isEqual(isDefault, true)))
            {
                ::setValue(result, std::string("withdraw"), ccxt::dict {
    { std::string("fee"), withdrawFee },
    { std::string("percentage"), std::any{} },
});
            }
            if (isTrue(!isEqual(networkCode, std::any{})))
            {
                ::setValue(::getValue(result, std::string("networks")), networkCode, ccxt::dict {
    { std::string("withdraw"), ccxt::dict {
        { std::string("fee"), withdrawFee },
        { std::string("percentage"), std::any{} },
    } },
    { std::string("deposit"), ccxt::dict {
        { std::string("fee"), std::any{} },
        { std::string("percentage"), std::any{} },
    } },
});
            }
        }
        return result;
    }

    /**
     * @method
     * @name binance#withdraw
     * @description make a withdrawal
     * @see https://developers.binance.com/docs/wallet/capital/withdraw
     * @param {string} code unified currency code
     * @param {float} amount the amount to withdraw
     * @param {string} address the address to withdraw to
     * @param {string} tag
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} a [transaction structure]{@link https://docs.ccxt.com/?id=transaction-structure}
     */
    std::shared_future<std::any> withdraw(std::any code, std::any amount, std::any address, std::any tag = std::any{}, std::any params = ccxt::dict {}) override
    {
        return std::async(std::launch::deferred, [=]() mutable -> std::any {
            std::any tagparamsVariable = this->handleWithdrawTagAndParams(tag, params);
            tag = ::getValue(tagparamsVariable, 0);
            params = ::getValue(tagparamsVariable, 1);
            this->checkAddress(address);
            if (isTrue(isEqual(this->markets, std::any{})))
            {
                awaitValue(this->loadMarkets());
            }
            std::any currency = this->currency(code);
            std::any request = ccxt::dict {
                { std::string("coin"), ::getValue(currency, std::string("id")) },
                { std::string("address"), address },
            };
            if (isTrue(!isEqual(tag, std::any{})))
            {
                ::setValue(request, std::string("addressTag"), tag);
            }
            std::any networkCode = std::any{};
            std::any networkCodeparamsVariable = this->handleNetworkCodeAndParams(params);
            networkCode = ::getValue(networkCodeparamsVariable, 0);
            params = ::getValue(networkCodeparamsVariable, 1);
            if (isTrue(!isEqual(networkCode, std::any{})))
            {
                ::setValue(request, std::string("network"), this->networkCodeToId(networkCode, ::getValue(currency, std::string("code"))));
            }
            ::setValue(request, std::string("amount"), this->currencyToPrecision(::getValue(currency, std::string("code")), amount, networkCode));
            std::any response = awaitValue(this->sapiPostCapitalWithdrawApply(this->extend(request, params)));
            //     { id: '9a67628b16ba4988ae20d329333f16bc' }
            return this->parseTransaction(response, currency);
        }).share();
    }

    virtual std::any parseTradingFee(std::any fee, std::any market = std::any{})
    {
        //
        // spot
        //     [
        //       {
        //         "symbol": "BTCUSDT",
        //         "makerCommission": "0.001",
        //         "takerCommission": "0.001"
        //       }
        //     ]
        //
        // swap
        //     {
        //         "symbol": "BTCUSD_PERP",
        //         "makerCommissionRate": "0.00015",  // 0.015%
        //         "takerCommissionRate": "0.00040"   // 0.040%
        //     }
        //
        std::any marketId = this->safeString(fee, std::string("symbol"));
        std::any symbol = this->safeSymbol(marketId, market, std::any{}, std::string("spot"));
        return ccxt::dict {
            { std::string("info"), fee },
            { std::string("symbol"), symbol },
            { std::string("maker"), this->safeNumber2(fee, std::string("makerCommission"), std::string("makerCommissionRate")) },
            { std::string("taker"), this->safeNumber2(fee, std::string("takerCommission"), std::string("takerCommissionRate")) },
            { std::string("percentage"), std::any{} },
            { std::string("tierBased"), std::any{} },
        };
    }

    /**
     * @method
     * @name binance#fetchTradingFee
     * @description fetch the trading fees for a market
     * @see https://developers.binance.com/docs/wallet/asset/trade-fee
     * @see https://developers.binance.com/docs/derivatives/usds-margined-futures/account/rest-api/User-Commission-Rate
     * @see https://developers.binance.com/docs/derivatives/coin-margined-futures/account/rest-api/User-Commission-Rate
     * @see https://developers.binance.com/docs/derivatives/portfolio-margin/account/Get-User-Commission-Rate-for-UM
     * @see https://developers.binance.com/docs/derivatives/portfolio-margin/account/Get-User-Commission-Rate-for-CM
     * @param {string} symbol unified market symbol
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {boolean} [params.portfolioMargin] set to true if you would like to fetch trading fees in a portfolio margin account
     * @param {string} [params.subType] "linear" or "inverse"
     * @returns {object} a [fee structure]{@link https://docs.ccxt.com/?id=fee-structure}
     */
    std::shared_future<std::any> fetchTradingFee(std::any symbol, std::any params = ccxt::dict {}) override
    {
        return std::async(std::launch::deferred, [=]() mutable -> std::any {
            if (isTrue(isEqual(this->markets, std::any{})))
            {
                awaitValue(this->loadMarkets());
            }
            std::any market = this->market(symbol);
            std::any type = ::getValue(market, std::string("type"));
            std::any subType = std::any{};
            std::any subTypeparamsVariable = this->handleSubTypeAndParams(std::string("fetchTradingFee"), market, params);
            subType = ::getValue(subTypeparamsVariable, 0);
            params = ::getValue(subTypeparamsVariable, 1);
            std::any isPortfolioMargin = std::any{};
            std::any isPortfolioMarginparamsVariable = this->handleOptionAndParams2(params, std::string("fetchTradingFee"), std::string("papi"), std::string("portfolioMargin"), false);
            isPortfolioMargin = ::getValue(isPortfolioMarginparamsVariable, 0);
            params = ::getValue(isPortfolioMarginparamsVariable, 1);
            std::any isLinear = this->isLinear(type, subType);
            std::any isInverse = this->isInverse(type, subType);
            std::any request = ccxt::dict {
                { std::string("symbol"), ::getValue(market, std::string("id")) },
            };
            std::any response = std::any{};
            if (isTrue(isLinear))
            {
                if (isTrue(isPortfolioMargin))
                {
                    response = awaitValue(this->papiGetUmCommissionRate(this->extend(request, params)));
                } else
                {
                    response = awaitValue(this->fapiPrivateGetCommissionRate(this->extend(request, params)));
                }
            } else if (isTrue(isInverse))
            {
                if (isTrue(isPortfolioMargin))
                {
                    response = awaitValue(this->papiGetCmCommissionRate(this->extend(request, params)));
                } else
                {
                    response = awaitValue(this->dapiPrivateGetCommissionRate(this->extend(request, params)));
                }
            } else
            {
                response = awaitValue(this->sapiGetAssetTradeFee(this->extend(request, params)));
            }
            //
            // spot
            //
            //     [
            //       {
            //         "symbol": "BTCUSDT",
            //         "makerCommission": "0.001",
            //         "takerCommission": "0.001"
            //       }
            //     ]
            //
            // swap
            //
            //     {
            //         "symbol": "BTCUSD_PERP",
            //         "makerCommissionRate": "0.00015",  // 0.015%
            //         "takerCommissionRate": "0.00040"   // 0.040%
            //     }
            //
            std::any data = response;
            if (isTrue(isArray(data)))
            {
                data = this->safeDict(data, 0, ccxt::dict {});
            }
            if (isTrue(isEqual(data, std::any{})))
            {
                throw NullResponse(toString(add(this->id, std::string(" parseTradingFee() returned empty response"))));
            }
            return this->parseTradingFee(data, market);
        }).share();
    }

    /**
     * @method
     * @name binance#fetchTradingFees
     * @description fetch the trading fees for multiple markets
     * @see https://developers.binance.com/docs/wallet/asset/trade-fee
     * @see https://developers.binance.com/docs/derivatives/usds-margined-futures/account/rest-api/Account-Information-V2
     * @see https://developers.binance.com/docs/derivatives/coin-margined-futures/account/rest-api/Account-Information
     * @see https://developers.binance.com/docs/derivatives/usds-margined-futures/account/rest-api/Account-Config
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {string} [params.subType] "linear" or "inverse"
     * @returns {object} a dictionary of [fee structures]{@link https://docs.ccxt.com/?id=fee-structure} indexed by market symbols
     */
    std::shared_future<std::any> fetchTradingFees(std::any params = ccxt::dict {}) override
    {
        return std::async(std::launch::deferred, [=]() mutable -> std::any {
            if (isTrue(isEqual(this->markets, std::any{})))
            {
                awaitValue(this->loadMarkets());
            }
            std::any type = std::any{};
            std::any typeparamsVariable = this->handleMarketTypeAndParams(std::string("fetchTradingFees"), std::any{}, params);
            type = ::getValue(typeparamsVariable, 0);
            params = ::getValue(typeparamsVariable, 1);
            std::any subType = std::any{};
            std::any subTypeparamsVariable = this->handleSubTypeAndParams(std::string("fetchTradingFees"), std::any{}, params, std::string("linear"));
            subType = ::getValue(subTypeparamsVariable, 0);
            params = ::getValue(subTypeparamsVariable, 1);
            std::any isSpotOrMargin = isTrue((isEqual(type, std::string("spot")))) || isTrue((isEqual(type, std::string("margin"))));
            std::any isLinear = this->isLinear(type, subType);
            std::any isInverse = this->isInverse(type, subType);
            std::any response = std::any{};
            if (isTrue(isSpotOrMargin))
            {
                response = awaitValue(this->sapiGetAssetTradeFee(params));
            } else if (isTrue(isLinear))
            {
                response = awaitValue(this->fapiPrivateGetAccountConfig(params));
            } else if (isTrue(isInverse))
            {
                response = awaitValue(this->dapiPrivateGetAccount(params));
            }
            //
            // sapi / spot
            //
            //    [
            //       {
            //         "symbol": "ZRXBNB",
            //         "makerCommission": "0.001",
            //         "takerCommission": "0.001"
            //       },
            //       {
            //         "symbol": "ZRXBTC",
            //         "makerCommission": "0.001",
            //         "takerCommission": "0.001"
            //       },
            //    ]
            //
            // fapi / future / linear
            //
            //     {
            //         "feeTier": 0,       // account commisssion tier
            //         "canTrade": true,   // if can trade
            //         "canDeposit": true,     // if can transfer in asset
            //         "canWithdraw": true,    // if can transfer out asset
            //         "updateTime": 0,
            //         "totalInitialMargin": "0.00000000",    // total initial margin required with current mark price (useless with isolated positions), only for USDT asset
            //         "totalMaintMargin": "0.00000000",     // total maintenance margin required, only for USDT asset
            //         "totalWalletBalance": "23.72469206",     // total wallet balance, only for USDT asset
            //         "totalUnrealizedProfit": "0.00000000",   // total unrealized profit, only for USDT asset
            //         "totalMarginBalance": "23.72469206",     // total margin balance, only for USDT asset
            //         "totalPositionInitialMargin": "0.00000000",    // initial margin required for positions with current mark price, only for USDT asset
            //         "totalOpenOrderInitialMargin": "0.00000000",   // initial margin required for open orders with current mark price, only for USDT asset
            //         "totalCrossWalletBalance": "23.72469206",      // crossed wallet balance, only for USDT asset
            //         "totalCrossUnPnl": "0.00000000",      // unrealized profit of crossed positions, only for USDT asset
            //         "availableBalance": "23.72469206",       // available balance, only for USDT asset
            //         "maxWithdrawAmount": "23.72469206"     // maximum amount for transfer out, only for USDT asset
            //         ...
            //     }
            //
            // dapi / delivery / inverse
            //
            //     {
            //         "canDeposit": true,
            //         "canTrade": true,
            //         "canWithdraw": true,
            //         "feeTier": 2,
            //         "updateTime": 0
            //     }
            //
            if (isTrue(isSpotOrMargin))
            {
                //
                //    [
                //       {
                //         "symbol": "ZRXBNB",
                //         "makerCommission": "0.001",
                //         "takerCommission": "0.001"
                //       },
                //       {
                //         "symbol": "ZRXBTC",
                //         "makerCommission": "0.001",
                //         "takerCommission": "0.001"
                //       },
                //    ]
                //
                std::any result = ccxt::dict {};
                if (isTrue(isEqual(response, std::any{})))
                {
                    throw NullResponse(toString(add(this->id, std::string(" method() returned empty response"))));
                }
                std::any fees = this->toArray(response);
                for (std::any i = 0; isLessThan(i, getArrayLength(fees)); postFixIncrement(i))
                {
                    std::any fee = this->parseTradingFee(::getValue(fees, i));
                    std::any symbol = ::getValue(fee, std::string("symbol"));
                    if (isTrue(!isEqual(symbol, std::any{})))
                    {
                        ::setValue(result, symbol, fee);
                    }
                }
                return result;
            } else if (isTrue(isLinear))
            {
                //
                //     {
                //         "feeTier": 0,       // account commisssion tier
                //         "canTrade": true,   // if can trade
                //         "canDeposit": true,     // if can transfer in asset
                //         "canWithdraw": true,    // if can transfer out asset
                //         "updateTime": 0,
                //         "totalInitialMargin": "0.00000000",    // total initial margin required with current mark price (useless with isolated positions), only for USDT asset
                //         "totalMaintMargin": "0.00000000",     // total maintenance margin required, only for USDT asset
                //         "totalWalletBalance": "23.72469206",     // total wallet balance, only for USDT asset
                //         "totalUnrealizedProfit": "0.00000000",   // total unrealized profit, only for USDT asset
                //         "totalMarginBalance": "23.72469206",     // total margin balance, only for USDT asset
                //         "totalPositionInitialMargin": "0.00000000",    // initial margin required for positions with current mark price, only for USDT asset
                //         "totalOpenOrderInitialMargin": "0.00000000",   // initial margin required for open orders with current mark price, only for USDT asset
                //         "totalCrossWalletBalance": "23.72469206",      // crossed wallet balance, only for USDT asset
                //         "totalCrossUnPnl": "0.00000000",      // unrealized profit of crossed positions, only for USDT asset
                //         "availableBalance": "23.72469206",       // available balance, only for USDT asset
                //         "maxWithdrawAmount": "23.72469206"     // maximum amount for transfer out, only for USDT asset
                //         ...
                //     }
                //
                std::any markets = this->markets;
                if (isTrue(isEqual(markets, std::any{})))
                {
                    throw ExchangeError(toString(add(this->id, std::string(" markets not loaded"))));
                }
                std::any symbols = getObjectKeys(markets);
                std::any result = ccxt::dict {};
                std::any feeTier = this->safeInteger(response, std::string("feeTier"));
                std::any feeTiers = ::getValue(::getValue(::getValue(this->fees, std::string("linear")), std::string("trading")), std::string("tiers"));
                std::any maker = ::getValue(::getValue(::getValue(feeTiers, std::string("maker")), feeTier), 1);
                std::any taker = ::getValue(::getValue(::getValue(feeTiers, std::string("taker")), feeTier), 1);
                for (std::any i = 0; isLessThan(i, getArrayLength(symbols)); postFixIncrement(i))
                {
                    std::any symbol = ::getValue(symbols, i);
                    std::any market = ::getValue(markets, symbol);
                    if (isTrue(isEqual(::getValue(market, std::string("linear")), true)))
                    {
                        ::setValue(result, symbol, ccxt::dict {
    { std::string("info"), ccxt::dict {
        { std::string("feeTier"), feeTier },
    } },
    { std::string("symbol"), symbol },
    { std::string("maker"), maker },
    { std::string("taker"), taker },
});
                    }
                }
                return result;
            } else if (isTrue(isInverse))
            {
                //
                //     {
                //         "canDeposit": true,
                //         "canTrade": true,
                //         "canWithdraw": true,
                //         "feeTier": 2,
                //         "updateTime": 0
                //     }
                //
                std::any markets = this->markets;
                if (isTrue(isEqual(markets, std::any{})))
                {
                    throw ExchangeError(toString(add(this->id, std::string(" markets not loaded"))));
                }
                std::any symbols = getObjectKeys(markets);
                std::any result = ccxt::dict {};
                std::any feeTier = this->safeInteger(response, std::string("feeTier"));
                std::any feeTiers = ::getValue(::getValue(::getValue(this->fees, std::string("inverse")), std::string("trading")), std::string("tiers"));
                std::any maker = ::getValue(::getValue(::getValue(feeTiers, std::string("maker")), feeTier), 1);
                std::any taker = ::getValue(::getValue(::getValue(feeTiers, std::string("taker")), feeTier), 1);
                for (std::any i = 0; isLessThan(i, getArrayLength(symbols)); postFixIncrement(i))
                {
                    std::any symbol = ::getValue(symbols, i);
                    std::any market = ::getValue(markets, symbol);
                    if (isTrue(isEqual(::getValue(market, std::string("inverse")), true)))
                    {
                        ::setValue(result, symbol, ccxt::dict {
    { std::string("info"), ccxt::dict {
        { std::string("feeTier"), feeTier },
    } },
    { std::string("symbol"), symbol },
    { std::string("maker"), maker },
    { std::string("taker"), taker },
});
                    }
                }
                return result;
            }
            throw NotSupported(toString(add(add(add(this->id, std::string(" fetchTradingFees() is not supported for ")), type), std::string(" markets"))));
            return std::any{};
        }).share();
    }

    /**
     * @method
     * @name binance#futuresTransfer
     * @ignore
     * @description transfer between futures account
     * @see https://developers.binance.com/docs/derivatives/usds-margined-futures/account/rest-api/New-Future-Account-Transfer
     * @param {string} code unified currency code
     * @param {float} amount the amount to transfer
     * @param {string} type 1 - transfer from spot account to USDT-Ⓜ futures account, 2 - transfer from USDT-Ⓜ futures account to spot account, 3 - transfer from spot account to COIN-Ⓜ futures account, 4 - transfer from COIN-Ⓜ futures account to spot account
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {float} params.recvWindow
     * @returns {object} a [transfer structure]{@link https://docs.ccxt.com/?id=futures-transfer-structure}
     */
    virtual std::shared_future<std::any> futuresTransfer(std::any code, std::any amount, std::any type, std::any params = ccxt::dict {})
    {
        return std::async(std::launch::deferred, [=]() mutable -> std::any {
            if (isTrue(isTrue((isLessThan(type, 1))) || isTrue((isGreaterThan(type, 4)))))
            {
                throw ArgumentsRequired(toString(add(this->id, std::string(" type must be between 1 and 4"))));
            }
            if (isTrue(isEqual(this->markets, std::any{})))
            {
                awaitValue(this->loadMarkets());
            }
            std::any currency = this->currency(code);
            std::any request = ccxt::dict {
                { std::string("asset"), ::getValue(currency, std::string("id")) },
                { std::string("amount"), amount },
                { std::string("type"), type },
            };
            std::any response = awaitValue(this->sapiPostFuturesTransfer(this->extend(request, params)));
            //
            //   {
            //       "tranId": 100000001
            //   }
            //
            return this->parseTransfer(response, currency);
        }).share();
    }

    /**
     * @method
     * @name binance#fetchFundingRate
     * @description fetch the current funding rate
     * @see https://developers.binance.com/docs/derivatives/usds-margined-futures/market-data/rest-api/Mark-Price
     * @see https://developers.binance.com/docs/derivatives/coin-margined-futures/market-data/rest-api/Index-Price-and-Mark-Price
     * @param {string} symbol unified market symbol
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} a [funding rate structure]{@link https://docs.ccxt.com/?id=funding-rate-structure}
     */
    std::shared_future<std::any> fetchFundingRate(std::any symbol, std::any params = ccxt::dict {}) override
    {
        return std::async(std::launch::deferred, [=]() mutable -> std::any {
            if (isTrue(isEqual(this->markets, std::any{})))
            {
                awaitValue(this->loadMarkets());
            }
            std::any market = this->market(symbol);
            std::any request = ccxt::dict {
                { std::string("symbol"), ::getValue(market, std::string("id")) },
            };
            std::any response = std::any{};
            if (isTrue(isEqual(::getValue(market, std::string("linear")), true)))
            {
                response = awaitValue(this->fapiPublicGetPremiumIndex(this->extend(request, params)));
            } else if (isTrue(isEqual(::getValue(market, std::string("inverse")), true)))
            {
                response = awaitValue(this->dapiPublicGetPremiumIndex(this->extend(request, params)));
            } else
            {
                throw NotSupported(toString(add(this->id, std::string(" fetchFundingRate() supports linear and inverse contracts only"))));
            }
            if (isTrue(isEqual(response, std::any{})))
            {
                throw NullResponse(toString(add(this->id, std::string(" fetchFundingRate() returned empty response"))));
            }
            if (isTrue(isEqual(::getValue(market, std::string("inverse")), true)))
            {
                response = ::getValue(response, 0);
            }
            //
            //     {
            //         "symbol": "BTCUSDT",
            //         "markPrice": "45802.81129892",
            //         "indexPrice": "45745.47701915",
            //         "estimatedSettlePrice": "45133.91753671",
            //         "lastFundingRate": "0.00063521",
            //         "interestRate": "0.00010000",
            //         "nextFundingTime": "1621267200000",
            //         "time": "1621252344001"
            //     }
            //
            return this->parseFundingRate(response, market);
        }).share();
    }

    /**
     * @method
     * @name binance#fetchFundingRateHistory
     * @description fetches historical funding rate prices
     * @see https://developers.binance.com/docs/derivatives/usds-margined-futures/market-data/rest-api/Get-Funding-Rate-History
     * @see https://developers.binance.com/docs/derivatives/coin-margined-futures/market-data/rest-api/Get-Funding-Rate-History-of-Perpetual-Futures
     * @param {string} symbol unified symbol of the market to fetch the funding rate history for
     * @param {int} [since] timestamp in ms of the earliest funding rate to fetch
     * @param {int} [limit] the maximum amount of [funding rate structures]{@link https://docs.ccxt.com/?id=funding-rate-history-structure} to fetch
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {int} [params.until] timestamp in ms of the latest funding rate
     * @param {boolean} [params.paginate] default false, when true will automatically paginate by calling this endpoint multiple times. See in the docs all the [available parameters](https://github.com/ccxt/ccxt/wiki/Manual#pagination-params)
     * @param {string} [params.subType] "linear" or "inverse"
     * @returns {object[]} a list of [funding rate structures]{@link https://docs.ccxt.com/?id=funding-rate-history-structure}
     */
    std::shared_future<std::any> fetchFundingRateHistory(std::any symbol = std::any{}, std::any since = std::any{}, std::any limit = std::any{}, std::any params = ccxt::dict {}) override
    {
        return std::async(std::launch::deferred, [=]() mutable -> std::any {
            if (isTrue(isEqual(this->markets, std::any{})))
            {
                awaitValue(this->loadMarkets());
            }
            std::any request = ccxt::dict {};
            std::any paginate = false;
            std::any paginateparamsVariable = this->handleOptionAndParams(params, std::string("fetchFundingRateHistory"), std::string("paginate"));
            paginate = ::getValue(paginateparamsVariable, 0);
            params = ::getValue(paginateparamsVariable, 1);
            if (isTrue(paginate))
            {
                return awaitValue(this->fetchPaginatedCallDeterministic(std::string("fetchFundingRateHistory"), symbol, since, limit, std::string("8h"), params));
            }
            std::any defaultType = this->safeString2(this->options, std::string("fetchFundingRateHistory"), std::string("defaultType"), std::string("future"));
            std::any type = this->safeString(params, std::string("type"), defaultType);
            std::any market = std::any{};
            if (isTrue(!isEqual(symbol, std::any{})))
            {
                market = this->market(symbol);
                symbol = ::getValue(market, std::string("symbol"));
                ::setValue(request, std::string("symbol"), ::getValue(market, std::string("id")));
            }
            std::any subType = std::any{};
            std::any subTypeparamsVariable = this->handleSubTypeAndParams(std::string("fetchFundingRateHistory"), market, params, std::string("linear"));
            subType = ::getValue(subTypeparamsVariable, 0);
            params = ::getValue(subTypeparamsVariable, 1);
            params = this->omit(params, std::string("type"));
            if (isTrue(!isEqual(since, std::any{})))
            {
                ::setValue(request, std::string("startTime"), since);
            }
            std::any until = this->safeInteger(params, std::string("until")); // unified in milliseconds
            std::any endTime = this->safeInteger(params, std::string("endTime"), until); // exchange-specific in milliseconds
            params = this->omit(params, ccxt::list{std::string("endTime"), std::string("until")});
            if (isTrue(!isEqual(endTime, std::any{})))
            {
                ::setValue(request, std::string("endTime"), endTime);
            }
            if (isTrue(!isEqual(limit, std::any{})))
            {
                ::setValue(request, std::string("limit"), limit);
            }
            std::any response = std::any{};
            if (isTrue(this->isLinear(type, subType)))
            {
                response = awaitValue(this->fapiPublicGetFundingRate(this->extend(request, params)));
            } else if (isTrue(this->isInverse(type, subType)))
            {
                response = awaitValue(this->dapiPublicGetFundingRate(this->extend(request, params)));
            } else
            {
                throw NotSupported(toString(add(add(add(this->id, std::string(" fetchFundingRateHistory() is not supported for ")), type), std::string(" markets"))));
            }
            //
            //     {
            //         "symbol": "BTCUSDT",
            //         "fundingRate": "0.00063521",
            //         "fundingTime": "1621267200000",
            //     }
            //
            return this->parseFundingRateHistories(response, market, since, limit);
        }).share();
    }

    std::any parseFundingRateHistory(std::any contract, std::any market = std::any{}) override
    {
        //
        //     {
        //         "symbol": "BTCUSDT",
        //         "fundingRate": "0.00063521",
        //         "fundingTime": "1621267200000",
        //     }
        //
        std::any timestamp = this->safeInteger(contract, std::string("fundingTime"));
        return ccxt::dict {
            { std::string("info"), contract },
            { std::string("symbol"), this->safeSymbol(this->safeString(contract, std::string("symbol")), std::any{}, std::any{}, std::string("swap")) },
            { std::string("fundingRate"), this->safeNumber(contract, std::string("fundingRate")) },
            { std::string("timestamp"), timestamp },
            { std::string("datetime"), this->iso8601(timestamp) },
        };
    }

    /**
     * @method
     * @name binance#fetchFundingRates
     * @description fetch the funding rate for multiple markets
     * @see https://developers.binance.com/docs/derivatives/usds-margined-futures/market-data/rest-api/Mark-Price
     * @see https://developers.binance.com/docs/derivatives/coin-margined-futures/market-data/rest-api/Index-Price-and-Mark-Price
     * @param {string[]|undefined} symbols list of unified market symbols
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {string} [params.subType] "linear" or "inverse"
     * @returns {object[]} a list of [funding rate structures]{@link https://docs.ccxt.com/?id=funding-rates-structure}, indexed by market symbols
     */
    std::shared_future<std::any> fetchFundingRates(std::any symbols = std::any{}, std::any params = ccxt::dict {}) override
    {
        return std::async(std::launch::deferred, [=]() mutable -> std::any {
            if (isTrue(isEqual(this->markets, std::any{})))
            {
                awaitValue(this->loadMarkets());
            }
            symbols = this->marketSymbols(symbols);
            std::any defaultType = this->safeString2(this->options, std::string("fetchFundingRates"), std::string("defaultType"), std::string("future"));
            std::any type = this->safeString(params, std::string("type"), defaultType);
            std::any subType = std::any{};
            std::any subTypeparamsVariable = this->handleSubTypeAndParams(std::string("fetchFundingRates"), std::any{}, params, std::string("linear"));
            subType = ::getValue(subTypeparamsVariable, 0);
            params = ::getValue(subTypeparamsVariable, 1);
            std::any query = this->omit(params, std::string("type"));
            std::any response = std::any{};
            if (isTrue(this->isLinear(type, subType)))
            {
                response = awaitValue(this->fapiPublicGetPremiumIndex(query));
            } else if (isTrue(this->isInverse(type, subType)))
            {
                response = awaitValue(this->dapiPublicGetPremiumIndex(query));
            } else
            {
                throw NotSupported(toString(add(this->id, std::string(" fetchFundingRates() supports linear and inverse contracts only"))));
            }
            return this->parseFundingRates(response, symbols);
        }).share();
    }

    std::any parseFundingRate(std::any contract, std::any market = std::any{}) override
    {
        // ensure it matches with https://www.binance.com/en/futures/funding-history/0
        //
        // fetchFundingRate, fetchFundingRates
        //
        //     {
        //         "symbol": "BTCUSDT",
        //         "markPrice": "45802.81129892",
        //         "indexPrice": "45745.47701915",
        //         "estimatedSettlePrice": "45133.91753671",
        //         "lastFundingRate": "0.00063521",
        //         "interestRate": "0.00010000",
        //         "nextFundingTime": "1621267200000",
        //         "time": "1621252344001"
        //     }
        //
        // fetchFundingInterval, fetchFundingIntervals
        //
        //     {
        //         "symbol": "BLZUSDT",
        //         "adjustedFundingRateCap": "0.03000000",
        //         "adjustedFundingRateFloor": "-0.03000000",
        //         "fundingIntervalHours": 4,
        //         "disclaimer": false
        //     }
        //
        std::any timestamp = this->safeInteger(contract, std::string("time"));
        std::any marketId = this->safeString(contract, std::string("symbol"));
        std::any symbol = this->safeSymbol(marketId, market, std::any{}, std::string("contract"));
        std::any markPrice = this->safeNumber(contract, std::string("markPrice"));
        std::any indexPrice = this->safeNumber(contract, std::string("indexPrice"));
        std::any interestRate = this->safeNumber(contract, std::string("interestRate"));
        std::any estimatedSettlePrice = this->safeNumber(contract, std::string("estimatedSettlePrice"));
        std::any fundingRate = this->safeNumber(contract, std::string("lastFundingRate"));
        std::any fundingTime = this->safeInteger(contract, std::string("nextFundingTime"));
        std::any interval = this->safeString(contract, std::string("fundingIntervalHours"));
        std::any intervalString = std::any{};
        if (isTrue(!isEqual(interval, std::any{})))
        {
            intervalString = add(interval, std::string("h"));
        }
        return ccxt::dict {
            { std::string("info"), contract },
            { std::string("symbol"), symbol },
            { std::string("markPrice"), markPrice },
            { std::string("indexPrice"), indexPrice },
            { std::string("interestRate"), interestRate },
            { std::string("estimatedSettlePrice"), estimatedSettlePrice },
            { std::string("timestamp"), timestamp },
            { std::string("datetime"), this->iso8601(timestamp) },
            { std::string("fundingRate"), fundingRate },
            { std::string("fundingTimestamp"), fundingTime },
            { std::string("fundingDatetime"), this->iso8601(fundingTime) },
            { std::string("nextFundingRate"), std::any{} },
            { std::string("nextFundingTimestamp"), std::any{} },
            { std::string("nextFundingDatetime"), std::any{} },
            { std::string("previousFundingRate"), std::any{} },
            { std::string("previousFundingTimestamp"), std::any{} },
            { std::string("previousFundingDatetime"), std::any{} },
            { std::string("interval"), intervalString },
        };
    }

    virtual std::any parseAccountPositions(std::any account, std::any filterClosed = false)
    {
        std::any positions = this->safeList(account, std::string("positions"), ccxt::list{});
        std::any assets = this->safeList(account, std::string("assets"), ccxt::list{});
        std::any balances = ccxt::dict {};
        for (std::any i = 0; isLessThan(i, getArrayLength(assets)); postFixIncrement(i))
        {
            std::any entry = ::getValue(assets, i);
            std::any currencyId = this->safeString(entry, std::string("asset"));
            std::any code = this->safeCurrencyCode(currencyId);
            std::any crossWalletBalance = this->safeString(entry, std::string("crossWalletBalance"));
            std::any crossUnPnl = this->safeString(entry, std::string("crossUnPnl"));
            if (isTrue(!isEqual(code, std::any{})))
            {
                ::setValue(balances, code, ccxt::dict {
    { std::string("crossMargin"), ccxt::Precise::stringAdd(crossWalletBalance, crossUnPnl) },
    { std::string("crossWalletBalance"), crossWalletBalance },
});
            }
        }
        std::any result = ccxt::list{};
        for (std::any i = 0; isLessThan(i, getArrayLength(positions)); postFixIncrement(i))
        {
            std::any position = ::getValue(positions, i);
            std::any marketId = this->safeString(position, std::string("symbol"));
            std::any market = this->safeMarket(marketId, std::any{}, std::any{}, std::string("contract"));
            std::any code = (isTrue((isEqual(::getValue(market, std::string("linear")), true))) ? std::any(::getValue(market, std::string("quote"))) : std::any(::getValue(market, std::string("base"))));
            std::any maintenanceMargin = this->safeString(position, std::string("maintMargin"));
            // check for maintenance margin so empty positions are not returned
            std::any isPositionOpen = isTrue((!isEqual(maintenanceMargin, std::string("0")))) && isTrue((!isEqual(maintenanceMargin, std::string("0.00000000"))));
            if (isTrue(!isTrue(filterClosed) || isTrue(isPositionOpen)))
            {
                // sometimes not all the codes are correctly returned...
                if (isTrue(inOp(balances, code)))
                {
                    std::any parsed = this->parseAccountPosition(this->extend(position, ccxt::dict {
                        { std::string("crossMargin"), ::getValue(::getValue(balances, code), std::string("crossMargin")) },
                        { std::string("crossWalletBalance"), ::getValue(::getValue(balances, code), std::string("crossWalletBalance")) },
                    }), market);
                    arrayPush(result, parsed);
                }
            }
        }
        return result;
    }

    virtual std::any parseAccountPosition(std::any position, std::any market = std::any{})
    {
        //
        // usdm
        //
        // v3 (similar for cross & isolated)
        //
        //    {
        //        "symbol": "WLDUSDT",
        //        "positionSide": "BOTH",
        //        "positionAmt": "-849",
        //        "unrealizedProfit": "11.17920750",
        //        "notional": "-1992.46079250",
        //        "isolatedMargin": "0",
        //        "isolatedWallet": "0",
        //        "initialMargin": "99.62303962",
        //        "maintMargin": "11.95476475",
        //        "updateTime": "1721995760449"
        //        "leverage": "50",                        // in v2
        //        "entryPrice": "2.34",                    // in v2
        //        "positionInitialMargin": "118.82116614", // in v2
        //        "openOrderInitialMargin": "0",           // in v2
        //        "isolated": false,                       // in v2
        //        "breakEvenPrice": "2.3395788",           // in v2
        //        "maxNotional": "25000",                  // in v2
        //        "bidNotional": "0",                      // in v2
        //        "askNotional": "0"                       // in v2
        //    }
        //
        // coinm
        //
        //     {
        //       "symbol": "BTCUSD_210625",
        //       "initialMargin": "0.00024393",
        //       "maintMargin": "0.00002439",
        //       "unrealizedProfit": "-0.00000163",
        //       "positionInitialMargin": "0.00024393",
        //       "openOrderInitialMargin": "0",
        //       "leverage": "10",
        //       "isolated": false,
        //       "positionSide": "BOTH",
        //       "entryPrice": "41021.20000069",
        //       "maxQty": "100",
        //       "notionalValue": "0.00243939",
        //       "isolatedWallet": "0",
        //       "crossMargin": "0.314"
        //       "crossWalletBalance": "34",
        //     }
        //
        // linear portfolio margin
        //
        //     {
        //         "symbol": "CTSIUSDT",
        //         "initialMargin": "0",
        //         "maintMargin": "0",
        //         "unrealizedProfit": "0.00000000",
        //         "positionInitialMargin": "0",
        //         "openOrderInitialMargin": "0",
        //         "leverage": "20",
        //         "entryPrice": "0.0",
        //         "maxNotional": "25000",
        //         "bidNotional": "0",
        //         "askNotional": "0",
        //         "positionSide": "SHORT",
        //         "positionAmt": "0",
        //         "updateTime": 0,
        //         "notional": "0",
        //         "breakEvenPrice": "0.0"
        //     }
        //
        // inverse portfolio margin
        //
        //     {
        //         "symbol": "TRXUSD_PERP",
        //         "initialMargin": "0",
        //         "maintMargin": "0",
        //         "unrealizedProfit": "0.00000000",
        //         "positionInitialMargin": "0",
        //         "openOrderInitialMargin": "0",
        //         "leverage": "20",
        //         "entryPrice": "0.00000000",
        //         "positionSide": "SHORT",
        //         "positionAmt": "0",
        //         "maxQty": "5000000",
        //         "updateTime": 0,
        //         "notionalValue": "0",
        //         "breakEvenPrice": "0.00000000"
        //     }
        //
        std::any marketId = this->safeString(position, std::string("symbol"));
        market = this->safeMarket(marketId, market, std::any{}, std::string("contract"));
        std::any symbol = this->safeString(market, std::string("symbol"));
        std::any leverageString = this->omitZero(this->safeString(position, std::string("leverage"))); // portfolio-margin accounts may return leverage "0", see #29244
        std::any leverage = (isTrue((!isEqual(leverageString, std::any{}))) ? std::any(parseInt(leverageString)) : std::any(std::any{}));
        std::any initialMarginString = this->safeString(position, std::string("initialMargin"));
        std::any initialMargin = this->parseNumber(initialMarginString);
        std::any initialMarginPercentageString = std::any{};
        if (isTrue(!isEqual(leverageString, std::any{})))
        {
            initialMarginPercentageString = ccxt::Precise::stringDiv(std::string("1"), leverageString, 8);
            if (isTrue(isEqual(leverage, std::any{})))
            {
                throw ExchangeError(toString(add(this->id, std::string(" method() missing leverage"))));
            }
            std::any rational = this->isRoundNumber(mod(1000, leverage));
            if (!isTrue(rational))
            {
                initialMarginPercentageString = ccxt::Precise::stringDiv(ccxt::Precise::stringAdd(initialMarginPercentageString, std::string("1e-8")), std::string("1"), 8);
            }
        }
        // as oppose to notionalValue
        std::any usdm = (inOp(position, std::string("notional")));
        std::any maintenanceMarginString = this->safeString(position, std::string("maintMargin"));
        std::any maintenanceMargin = this->parseNumber(maintenanceMarginString);
        std::any entryPriceString = this->safeString(position, std::string("entryPrice"));
        std::any entryPrice = this->parseNumber(entryPriceString);
        std::any notionalString = this->safeString2(position, std::string("notional"), std::string("notionalValue"));
        std::any notionalStringAbs = ccxt::Precise::stringAbs(notionalString);
        std::any notional = this->parseNumber(notionalStringAbs);
        std::any contractsString = this->safeString(position, std::string("positionAmt"));
        std::any contractsStringAbs = ccxt::Precise::stringAbs(contractsString);
        if (isTrue(isEqual(contractsString, std::any{})))
        {
            std::any entryNotional = ccxt::Precise::stringMul(ccxt::Precise::stringMul(leverageString, initialMarginString), entryPriceString);
            std::any contractSizeNew = this->safeString(market, std::string("contractSize"));
            contractsString = ccxt::Precise::stringDiv(entryNotional, contractSizeNew);
            contractsStringAbs = ccxt::Precise::stringDiv(ccxt::Precise::stringAdd(contractsString, std::string("0.5")), std::string("1"), 0);
        }
        std::any contracts = this->parseNumber(contractsStringAbs);
        std::any leverageBrackets = this->safeDict(this->options, std::string("leverageBrackets"), ccxt::dict {});
        std::any leverageBracket = this->safeList(leverageBrackets, symbol, ccxt::list{});
        std::any maintenanceMarginPercentageString = std::any{};
        for (std::any i = 0; isLessThan(i, getArrayLength(leverageBracket)); postFixIncrement(i))
        {
            std::any bracket = ::getValue(leverageBracket, i);
            if (isTrue(ccxt::Precise::stringLt(notionalStringAbs, ::getValue(bracket, 0))))
            {
                break;
            }
            maintenanceMarginPercentageString = ::getValue(bracket, 1);
        }
        std::any maintenanceMarginPercentage = this->parseNumber(maintenanceMarginPercentageString);
        std::any unrealizedPnlString = this->safeString(position, std::string("unrealizedProfit"));
        std::any unrealizedPnl = this->parseNumber(unrealizedPnlString);
        std::any timestamp = this->safeInteger(position, std::string("updateTime"));
        if (isTrue(isEqual(timestamp, 0)))
        {
            timestamp = std::any{};
        }
        std::any isolated = this->safeBool(position, std::string("isolated"));
        if (isTrue(isEqual(isolated, std::any{})))
        {
            std::any isolatedMarginRaw = this->safeString(position, std::string("isolatedMargin"));
            isolated = !isTrue(ccxt::Precise::stringEq(isolatedMarginRaw, std::string("0")));
        }
        std::any marginMode = std::any{};
        std::any collateralString = std::any{};
        std::any walletBalance = std::any{};
        if (isTrue(isolated))
        {
            marginMode = std::string("isolated");
            walletBalance = this->safeString(position, std::string("isolatedWallet"));
            collateralString = ccxt::Precise::stringAdd(walletBalance, unrealizedPnlString);
        } else
        {
            marginMode = std::string("cross");
            walletBalance = this->safeString(position, std::string("crossWalletBalance"));
            collateralString = this->safeString(position, std::string("crossMargin"));
        }
        std::any collateral = this->parseNumber(collateralString);
        std::any marginRatio = std::any{};
        std::any side = std::any{};
        std::any percentage = std::any{};
        std::any liquidationPriceStringRaw = std::any{};
        std::any liquidationPrice = std::any{};
        std::any contractSize = this->safeValue(market, std::string("contractSize"));
        std::any contractSizeString = this->numberToString(contractSize);
        if (isTrue(ccxt::Precise::stringEquals(notionalString, std::string("0"))))
        {
            entryPrice = std::any{};
        } else
        {
            side = (isTrue(ccxt::Precise::stringLt(notionalString, std::string("0"))) ? std::any(std::string("short")) : std::any(std::string("long")));
            marginRatio = this->parseNumber(ccxt::Precise::stringDiv(ccxt::Precise::stringAdd(ccxt::Precise::stringDiv(maintenanceMarginString, collateralString), std::string("5e-5")), std::string("1"), 4));
            percentage = this->parseNumber(ccxt::Precise::stringMul(ccxt::Precise::stringDiv(unrealizedPnlString, initialMarginString, 4), std::string("100")));
            if (isTrue(usdm))
            {
                // calculate liquidation price
                //
                // liquidationPrice = (walletBalance / (contracts * (±1 + mmp))) + (±entryPrice / (±1 + mmp))
                //
                // mmp = maintenanceMarginPercentage
                // where ± is negative for long and positive for short
                // TODO: calculate liquidation price for coinm contracts
                std::any onePlusMaintenanceMarginPercentageString = std::any{};
                std::any entryPriceSignString = entryPriceString;
                if (isTrue(isEqual(side, std::string("short"))))
                {
                    onePlusMaintenanceMarginPercentageString = ccxt::Precise::stringAdd(std::string("1"), maintenanceMarginPercentageString);
                } else
                {
                    onePlusMaintenanceMarginPercentageString = ccxt::Precise::stringAdd(std::string("-1"), maintenanceMarginPercentageString);
                    entryPriceSignString = ccxt::Precise::stringMul(std::string("-1"), entryPriceSignString);
                }
                std::any leftSide = ccxt::Precise::stringDiv(walletBalance, ccxt::Precise::stringMul(contractsStringAbs, onePlusMaintenanceMarginPercentageString));
                std::any rightSide = ccxt::Precise::stringDiv(entryPriceSignString, onePlusMaintenanceMarginPercentageString);
                liquidationPriceStringRaw = ccxt::Precise::stringAdd(leftSide, rightSide);
            } else
            {
                // calculate liquidation price
                //
                // liquidationPrice = (contracts * contractSize(±1 - mmp)) / (±1/entryPrice * contracts * contractSize - walletBalance)
                //
                std::any onePlusMaintenanceMarginPercentageString = std::any{};
                std::any entryPriceSignString = entryPriceString;
                if (isTrue(isEqual(side, std::string("short"))))
                {
                    onePlusMaintenanceMarginPercentageString = ccxt::Precise::stringSub(std::string("1"), maintenanceMarginPercentageString);
                } else
                {
                    onePlusMaintenanceMarginPercentageString = ccxt::Precise::stringSub(std::string("-1"), maintenanceMarginPercentageString);
                    entryPriceSignString = ccxt::Precise::stringMul(std::string("-1"), entryPriceSignString);
                }
                std::any size = ccxt::Precise::stringMul(contractsStringAbs, contractSizeString);
                std::any leftSide = ccxt::Precise::stringMul(size, onePlusMaintenanceMarginPercentageString);
                std::any rightSide = ccxt::Precise::stringSub(ccxt::Precise::stringMul(ccxt::Precise::stringDiv(std::string("1"), entryPriceSignString), size), walletBalance);
                liquidationPriceStringRaw = ccxt::Precise::stringDiv(leftSide, rightSide);
            }
            std::any pricePrecision = this->precisionFromString(this->safeString(::getValue(market, std::string("precision")), std::string("price")));
            std::any pricePrecisionPlusOne = add(pricePrecision, 1);
            std::any pricePrecisionPlusOneString = toString(pricePrecisionPlusOne);
            // round half up
            Precise rounder = Precise(add(std::string("5e-"), pricePrecisionPlusOneString));
            std::any rounderString = toString(rounder);
            std::any liquidationPriceRoundedString = ccxt::Precise::stringAdd(rounderString, liquidationPriceStringRaw);
            std::any truncatedLiquidationPrice = ccxt::Precise::stringDiv(liquidationPriceRoundedString, std::string("1"), pricePrecision);
            if (isTrue(isTrue(!isEqual(truncatedLiquidationPrice, std::any{})) && isTrue(isEqual(::getValue(truncatedLiquidationPrice, 0), std::string("-")))))
            {
                // user cannot be liquidated
                // since he has more collateral than the size of the position
                truncatedLiquidationPrice = std::any{};
            }
            liquidationPrice = this->parseNumber(truncatedLiquidationPrice);
        }
        std::any positionSide = this->safeString(position, std::string("positionSide"));
        std::any hedged = !isEqual(positionSide, std::string("BOTH"));
        return ccxt::dict {
            { std::string("info"), position },
            { std::string("id"), std::any{} },
            { std::string("symbol"), symbol },
            { std::string("timestamp"), timestamp },
            { std::string("datetime"), this->iso8601(timestamp) },
            { std::string("initialMargin"), initialMargin },
            { std::string("initialMarginPercentage"), this->parseNumber(initialMarginPercentageString) },
            { std::string("maintenanceMargin"), maintenanceMargin },
            { std::string("maintenanceMarginPercentage"), maintenanceMarginPercentage },
            { std::string("entryPrice"), entryPrice },
            { std::string("notional"), notional },
            { std::string("leverage"), this->parseNumber(leverageString) },
            { std::string("unrealizedPnl"), unrealizedPnl },
            { std::string("contracts"), contracts },
            { std::string("contractSize"), contractSize },
            { std::string("marginRatio"), marginRatio },
            { std::string("liquidationPrice"), liquidationPrice },
            { std::string("markPrice"), std::any{} },
            { std::string("collateral"), collateral },
            { std::string("marginMode"), marginMode },
            { std::string("side"), side },
            { std::string("hedged"), hedged },
            { std::string("percentage"), percentage },
        };
    }

    virtual std::any parsePositionRisk(std::any position, std::any market = std::any{})
    {
        //
        // usdm
        //
        //  {
        //     symbol: "WLDUSDT",
        //     positionSide: "BOTH",
        //     positionAmt: "5",
        //     entryPrice: "2.3483",
        //     breakEvenPrice: "2.349356735",
        //     markPrice: "2.39560000",
        //     unRealizedProfit: "0.23650000",
        //     liquidationPrice: "0",
        //     isolatedMargin: "0",
        //     notional: "11.97800000",
        //     isolatedWallet: "0",
        //     updateTime: "1722062678998",
        //     initialMargin: "2.39560000",         // not in v2
        //     maintMargin: "0.07186800",           // not in v2
        //     positionInitialMargin: "2.39560000", // not in v2
        //     openOrderInitialMargin: "0",         // not in v2
        //     adl: "2",                            // not in v2
        //     bidNotional: "0",                    // not in v2
        //     askNotional: "0",                    // not in v2
        //     marginAsset: "USDT",                 // not in v2
        //     // the below fields are only in v2
        //     leverage: "5",
        //     maxNotionalValue: "6000000",
        //     marginType: "cross",
        //     isAutoAddMargin: "false",
        //     isolated: false,
        //     adlQuantile: "2",
        //
        // coinm
        //
        //     {
        //       "symbol": "BTCUSD_PERP",
        //       "positionAmt": "2",
        //       "entryPrice": "37643.10000021",
        //       "markPrice": "38103.05510455",
        //       "unRealizedProfit": "0.00006413",
        //       "liquidationPrice": "25119.97445760",
        //       "leverage": "2",
        //       "maxQty": "1500",
        //       "marginType": "isolated",
        //       "isolatedMargin": "0.00274471",
        //       "isAutoAddMargin": "false",
        //       "positionSide": "BOTH",
        //       "notionalValue": "0.00524892",
        //       "isolatedWallet": "0.00268058"
        //     }
        //
        // inverse portfolio margin
        //
        //     {
        //         "symbol": "ETHUSD_PERP",
        //         "positionAmt": "1",
        //         "entryPrice": "2422.400000007",
        //         "markPrice": "2424.51267823",
        //         "unRealizedProfit": "0.0000036",
        //         "liquidationPrice": "293.57678898",
        //         "leverage": "100",
        //         "positionSide": "LONG",
        //         "updateTime": 1707371941861,
        //         "maxQty": "15",
        //         "notionalValue": "0.00412454",
        //         "breakEvenPrice": "2423.368960034"
        //     }
        //
        // linear portfolio margin
        //
        //     {
        //         "symbol": "BTCUSDT",
        //         "positionAmt": "0.01",
        //         "entryPrice": "44525.0",
        //         "markPrice": "45464.1735922",
        //         "unRealizedProfit": "9.39173592",
        //         "liquidationPrice": "38007.16308568",
        //         "leverage": "100",
        //         "positionSide": "LONG",
        //         "updateTime": 1707371879042,
        //         "maxNotionalValue": "500000.0",
        //         "notional": "454.64173592",
        //         "breakEvenPrice": "44542.81"
        //     }
        //
        std::any marketId = this->safeString(position, std::string("symbol"));
        market = this->safeMarket(marketId, market, std::any{}, std::string("contract"));
        std::any symbol = this->safeString(market, std::string("symbol"));
        std::any isolatedMarginString = this->safeString(position, std::string("isolatedMargin"));
        std::any leverageBrackets = this->safeDict(this->options, std::string("leverageBrackets"), ccxt::dict {});
        std::any leverageBracket = this->safeList(leverageBrackets, symbol, ccxt::list{});
        std::any notionalString = this->safeString2(position, std::string("notional"), std::string("notionalValue"));
        std::any notionalStringAbs = ccxt::Precise::stringAbs(notionalString);
        std::any maintenanceMarginPercentageString = std::any{};
        for (std::any i = 0; isLessThan(i, getArrayLength(leverageBracket)); postFixIncrement(i))
        {
            std::any bracket = ::getValue(leverageBracket, i);
            if (isTrue(ccxt::Precise::stringLt(notionalStringAbs, ::getValue(bracket, 0))))
            {
                break;
            }
            maintenanceMarginPercentageString = ::getValue(bracket, 1);
        }
        std::any notional = this->parseNumber(notionalStringAbs);
        std::any contractsAbs = ccxt::Precise::stringAbs(this->safeString(position, std::string("positionAmt")));
        std::any contracts = this->parseNumber(contractsAbs);
        std::any unrealizedPnlString = this->safeString(position, std::string("unRealizedProfit"));
        std::any unrealizedPnl = this->parseNumber(unrealizedPnlString);
        std::any liquidationPriceString = this->omitZero(this->safeString(position, std::string("liquidationPrice")));
        std::any liquidationPrice = this->parseNumber(liquidationPriceString);
        std::any collateralString = std::any{};
        std::any marginMode = this->safeString(position, std::string("marginType"));
        if (isTrue(isTrue(isEqual(marginMode, std::any{})) && isTrue(!isEqual(isolatedMarginString, std::any{}))))
        {
            marginMode = (isTrue(ccxt::Precise::stringEq(isolatedMarginString, std::string("0"))) ? std::any(std::string("cross")) : std::any(std::string("isolated")));
        }
        std::any side = std::any{};
        if (isTrue(ccxt::Precise::stringGt(notionalString, std::string("0"))))
        {
            side = std::string("long");
        } else if (isTrue(ccxt::Precise::stringLt(notionalString, std::string("0"))))
        {
            side = std::string("short");
        }
        std::any entryPriceString = this->safeString(position, std::string("entryPrice"));
        std::any entryPrice = this->parseNumber(entryPriceString);
        std::any contractSize = this->safeValue(market, std::string("contractSize"));
        std::any contractSizeString = this->numberToString(contractSize);
        // as oppose to notionalValue
        std::any linear = (inOp(position, std::string("notional")));
        if (isTrue(isEqual(marginMode, std::string("cross"))))
        {
            // calculate collateral
            std::any precision = this->safeDict(market, std::string("precision"), ccxt::dict {});
            std::any basePrecisionValue = this->safeString(precision, std::string("base"));
            std::any quotePrecisionValue = this->safeString2(precision, std::string("quote"), std::string("price"));
            std::any precisionIsUndefined = isTrue((isEqual(basePrecisionValue, std::any{}))) && isTrue((isEqual(quotePrecisionValue, std::any{})));
            if (!isTrue(precisionIsUndefined))
            {
                if (isTrue(linear))
                {
                    // walletBalance = (liquidationPrice * (±1 + mmp) ± entryPrice) * contracts
                    std::any onePlusMaintenanceMarginPercentageString = std::any{};
                    std::any entryPriceSignString = entryPriceString;
                    if (isTrue(isEqual(side, std::string("short"))))
                    {
                        onePlusMaintenanceMarginPercentageString = ccxt::Precise::stringAdd(std::string("1"), maintenanceMarginPercentageString);
                        entryPriceSignString = ccxt::Precise::stringMul(std::string("-1"), entryPriceSignString);
                    } else
                    {
                        onePlusMaintenanceMarginPercentageString = ccxt::Precise::stringAdd(std::string("-1"), maintenanceMarginPercentageString);
                    }
                    std::any inner = ccxt::Precise::stringMul(liquidationPriceString, onePlusMaintenanceMarginPercentageString);
                    std::any leftSide = ccxt::Precise::stringAdd(inner, entryPriceSignString);
                    std::any quotePrecision = this->precisionFromString(this->safeString2(precision, std::string("quote"), std::string("price")));
                    if (isTrue(!isEqual(quotePrecision, std::any{})))
                    {
                        collateralString = ccxt::Precise::stringDiv(ccxt::Precise::stringMul(leftSide, contractsAbs), std::string("1"), quotePrecision);
                    }
                } else
                {
                    // walletBalance = (contracts * contractSize) * (±1/entryPrice - (±1 - mmp) / liquidationPrice)
                    std::any onePlusMaintenanceMarginPercentageString = std::any{};
                    std::any entryPriceSignString = entryPriceString;
                    if (isTrue(isEqual(side, std::string("short"))))
                    {
                        onePlusMaintenanceMarginPercentageString = ccxt::Precise::stringSub(std::string("1"), maintenanceMarginPercentageString);
                    } else
                    {
                        onePlusMaintenanceMarginPercentageString = ccxt::Precise::stringSub(std::string("-1"), maintenanceMarginPercentageString);
                        entryPriceSignString = ccxt::Precise::stringMul(std::string("-1"), entryPriceSignString);
                    }
                    std::any leftSide = ccxt::Precise::stringMul(contractsAbs, contractSizeString);
                    std::any rightSide = ccxt::Precise::stringSub(ccxt::Precise::stringDiv(std::string("1"), entryPriceSignString), ccxt::Precise::stringDiv(onePlusMaintenanceMarginPercentageString, liquidationPriceString));
                    std::any basePrecision = this->precisionFromString(this->safeString(precision, std::string("base")));
                    if (isTrue(!isEqual(basePrecision, std::any{})))
                    {
                        collateralString = ccxt::Precise::stringDiv(ccxt::Precise::stringMul(leftSide, rightSide), std::string("1"), basePrecision);
                    }
                }
            }
        } else
        {
            collateralString = this->safeString(position, std::string("isolatedMargin"));
        }
        collateralString = (isTrue((isEqual(collateralString, std::any{}))) ? std::any(std::string("0")) : std::any(collateralString));
        std::any collateral = this->parseNumber(collateralString);
        std::any markPrice = this->parseNumber(this->omitZero(this->safeString(position, std::string("markPrice"))));
        std::any timestamp = this->safeInteger(position, std::string("updateTime"));
        if (isTrue(isEqual(timestamp, 0)))
        {
            timestamp = std::any{};
        }
        std::any maintenanceMarginPercentage = this->parseNumber(maintenanceMarginPercentageString);
        std::any maintenanceMarginString = ccxt::Precise::stringMul(maintenanceMarginPercentageString, notionalStringAbs);
        if (isTrue(isEqual(maintenanceMarginString, std::any{})))
        {
            // for a while, this new value was a backup to the existing calculations, but in future we might prioritize this
            maintenanceMarginString = this->safeString(position, std::string("maintMargin"));
        }
        std::any maintenanceMargin = this->parseNumber(maintenanceMarginString);
        std::any initialMarginString = std::any{};
        std::any initialMarginPercentageString = std::any{};
        std::any leverageString = this->omitZero(this->safeString(position, std::string("leverage"))); // portfolio-margin accounts may return leverage "0", see #29244
        if (isTrue(!isEqual(leverageString, std::any{})))
        {
            std::any leverage = parseInt(leverageString);
            std::any rational = this->isRoundNumber(mod(1000, leverage));
            initialMarginPercentageString = ccxt::Precise::stringDiv(std::string("1"), leverageString, 8);
            if (!isTrue(rational))
            {
                initialMarginPercentageString = ccxt::Precise::stringAdd(initialMarginPercentageString, std::string("1e-8"));
            }
            std::any unrounded = ccxt::Precise::stringMul(notionalStringAbs, initialMarginPercentageString);
            initialMarginString = ccxt::Precise::stringDiv(unrounded, std::string("1"), 8);
        } else
        {
            initialMarginString = this->safeString(position, std::string("initialMargin"));
            std::any unrounded = ccxt::Precise::stringMul(initialMarginString, std::string("1"));
            initialMarginPercentageString = ccxt::Precise::stringDiv(unrounded, notionalStringAbs, 8);
        }
        std::any marginRatio = std::any{};
        std::any percentage = std::any{};
        if (!isTrue(ccxt::Precise::stringEquals(collateralString, std::string("0"))))
        {
            marginRatio = this->parseNumber(ccxt::Precise::stringDiv(ccxt::Precise::stringAdd(ccxt::Precise::stringDiv(maintenanceMarginString, collateralString), std::string("5e-5")), std::string("1"), 4));
            percentage = this->parseNumber(ccxt::Precise::stringMul(ccxt::Precise::stringDiv(unrealizedPnlString, initialMarginString, 4), std::string("100")));
        }
        std::any positionSide = this->safeString(position, std::string("positionSide"));
        std::any hedged = !isEqual(positionSide, std::string("BOTH"));
        return this->safePosition(ccxt::dict {
            { std::string("info"), position },
            { std::string("id"), std::any{} },
            { std::string("symbol"), symbol },
            { std::string("contracts"), contracts },
            { std::string("contractSize"), contractSize },
            { std::string("unrealizedPnl"), unrealizedPnl },
            { std::string("leverage"), this->parseNumber(leverageString) },
            { std::string("liquidationPrice"), liquidationPrice },
            { std::string("collateral"), collateral },
            { std::string("notional"), notional },
            { std::string("markPrice"), markPrice },
            { std::string("entryPrice"), entryPrice },
            { std::string("timestamp"), timestamp },
            { std::string("initialMargin"), this->parseNumber(initialMarginString) },
            { std::string("initialMarginPercentage"), this->parseNumber(initialMarginPercentageString) },
            { std::string("maintenanceMargin"), maintenanceMargin },
            { std::string("maintenanceMarginPercentage"), maintenanceMarginPercentage },
            { std::string("marginRatio"), marginRatio },
            { std::string("datetime"), this->iso8601(timestamp) },
            { std::string("marginMode"), marginMode },
            { std::string("marginType"), marginMode },
            { std::string("side"), side },
            { std::string("hedged"), hedged },
            { std::string("percentage"), percentage },
            { std::string("stopLossPrice"), std::any{} },
            { std::string("takeProfitPrice"), std::any{} },
        });
    }

    virtual std::shared_future<std::any> loadLeverageBrackets(std::any reload = false, std::any params = ccxt::dict {})
    {
        return std::async(std::launch::deferred, [=]() mutable -> std::any {
            if (isTrue(isEqual(this->markets, std::any{})))
            {
                awaitValue(this->loadMarkets());
            }
            // by default cache the leverage bracket
            // it contains useful stuff like the maintenance margin and initial margin for positions
            std::any leverageBrackets = this->safeDict(this->options, std::string("leverageBrackets"));
            if (isTrue(isTrue((isEqual(leverageBrackets, std::any{}))) || isTrue((reload))))
            {
                std::any defaultType = this->safeString(this->options, std::string("defaultType"), std::string("future"));
                std::any type = this->safeString(params, std::string("type"), defaultType);
                std::any query = this->omit(params, std::string("type"));
                std::any subType = std::any{};
                std::any subTypeparamsVariable = this->handleSubTypeAndParams(std::string("loadLeverageBrackets"), std::any{}, params, std::string("linear"));
                subType = ::getValue(subTypeparamsVariable, 0);
                params = ::getValue(subTypeparamsVariable, 1);
                std::any isPortfolioMargin = std::any{};
                std::any isPortfolioMarginparamsVariable = this->handleOptionAndParams2(params, std::string("loadLeverageBrackets"), std::string("papi"), std::string("portfolioMargin"), false);
                isPortfolioMargin = ::getValue(isPortfolioMarginparamsVariable, 0);
                params = ::getValue(isPortfolioMarginparamsVariable, 1);
                std::any response = std::any{};
                if (isTrue(this->isLinear(type, subType)))
                {
                    if (isTrue(isPortfolioMargin))
                    {
                        response = awaitValue(this->papiGetUmLeverageBracket(query));
                    } else
                    {
                        response = awaitValue(this->fapiPrivateGetLeverageBracket(query));
                    }
                } else if (isTrue(this->isInverse(type, subType)))
                {
                    if (isTrue(isPortfolioMargin))
                    {
                        response = awaitValue(this->papiGetCmLeverageBracket(query));
                    } else
                    {
                        response = awaitValue(this->dapiPrivateV2GetLeverageBracket(query));
                    }
                } else
                {
                    throw NotSupported(toString(add(this->id, std::string(" loadLeverageBrackets() supports linear and inverse contracts only"))));
                }
                ::setValue(this->options, std::string("leverageBrackets"), this->createSafeDictionary());
                if (isTrue(isEqual(response, std::any{})))
                {
                    throw NullResponse(toString(add(this->id, std::string(" loadLeverageBrackets() returned empty response"))));
                }
                std::any entries = this->toArray(response);
                for (std::any i = 0; isLessThan(i, getArrayLength(entries)); postFixIncrement(i))
                {
                    std::any entry = ::getValue(entries, i);
                    std::any marketId = this->safeString(entry, std::string("symbol"));
                    std::any symbol = this->safeSymbol(marketId, std::any{}, std::any{}, std::string("contract"));
                    std::any brackets = this->safeList(entry, std::string("brackets"), ccxt::list{});
                    std::any result = ccxt::list{};
                    for (std::any j = 0; isLessThan(j, getArrayLength(brackets)); postFixIncrement(j))
                    {
                        std::any bracket = ::getValue(brackets, j);
                        std::any floorValue = this->safeString2(bracket, std::string("notionalFloor"), std::string("qtyFloor"));
                        std::any maintenanceMarginPercentage = this->safeString(bracket, std::string("maintMarginRatio"));
                        arrayPush(result, ccxt::list{floorValue, maintenanceMarginPercentage});
                    }
                    ::setValue(::getValue(this->options, std::string("leverageBrackets")), symbol, result);
                }
            }
            return ::getValue(this->options, std::string("leverageBrackets"));
        }).share();
    }

    /**
     * @method
     * @name binance#fetchLeverageTiers
     * @description retrieve information on the maximum leverage, and maintenance margin for trades of varying trade sizes
     * @see https://developers.binance.com/docs/derivatives/usds-margined-futures/account/rest-api/Notional-and-Leverage-Brackets
     * @see https://developers.binance.com/docs/derivatives/coin-margined-futures/account/rest-api/Notional-Bracket-for-Pair
     * @see https://developers.binance.com/docs/derivatives/portfolio-margin/account/UM-Notional-and-Leverage-Brackets
     * @see https://developers.binance.com/docs/derivatives/portfolio-margin/account/CM-Notional-and-Leverage-Brackets
     * @param {string[]|undefined} symbols list of unified market symbols
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {boolean} [params.portfolioMargin] set to true if you would like to fetch the leverage tiers for a portfolio margin account
     * @param {string} [params.subType] "linear" or "inverse"
     * @returns {object} a dictionary of [leverage tiers structures]{@link https://docs.ccxt.com/?id=leverage-tiers-structure}, indexed by market symbols
     */
    std::shared_future<std::any> fetchLeverageTiers(std::any symbols = std::any{}, std::any params = ccxt::dict {}) override
    {
        return std::async(std::launch::deferred, [=]() mutable -> std::any {
            if (isTrue(isEqual(this->markets, std::any{})))
            {
                awaitValue(this->loadMarkets());
            }
            std::any type = std::any{};
            std::any typeparamsVariable = this->handleMarketTypeAndParams(std::string("fetchLeverageTiers"), std::any{}, params);
            type = ::getValue(typeparamsVariable, 0);
            params = ::getValue(typeparamsVariable, 1);
            std::any subType = std::any{};
            std::any subTypeparamsVariable = this->handleSubTypeAndParams(std::string("fetchLeverageTiers"), std::any{}, params, std::string("linear"));
            subType = ::getValue(subTypeparamsVariable, 0);
            params = ::getValue(subTypeparamsVariable, 1);
            std::any isPortfolioMargin = std::any{};
            std::any isPortfolioMarginparamsVariable = this->handleOptionAndParams2(params, std::string("fetchLeverageTiers"), std::string("papi"), std::string("portfolioMargin"), false);
            isPortfolioMargin = ::getValue(isPortfolioMarginparamsVariable, 0);
            params = ::getValue(isPortfolioMarginparamsVariable, 1);
            std::any response = std::any{};
            if (isTrue(this->isLinear(type, subType)))
            {
                if (isTrue(isPortfolioMargin))
                {
                    response = awaitValue(this->papiGetUmLeverageBracket(params));
                } else
                {
                    response = awaitValue(this->fapiPrivateGetLeverageBracket(params));
                }
            } else if (isTrue(this->isInverse(type, subType)))
            {
                if (isTrue(isPortfolioMargin))
                {
                    response = awaitValue(this->papiGetCmLeverageBracket(params));
                } else
                {
                    response = awaitValue(this->dapiPrivateV2GetLeverageBracket(params));
                }
            } else
            {
                throw NotSupported(toString(add(this->id, std::string(" fetchLeverageTiers() supports linear and inverse contracts only"))));
            }
            //
            // usdm
            //
            //    [
            //        {
            //            "symbol": "SUSHIUSDT",
            //            "brackets": [
            //                {
            //                    "bracket": 1,
            //                    "initialLeverage": 50,
            //                    "notionalCap": 50000,
            //                    "notionalFloor": 0,
            //                    "maintMarginRatio": 0.01,
            //                    "cum": 0.0
            //                },
            //                ...
            //            ]
            //        }
            //    ]
            //
            // coinm
            //
            //     [
            //         {
            //             "symbol":"XRPUSD_210326",
            //             "brackets":[
            //                 {
            //                     "bracket":1,
            //                     "initialLeverage":20,
            //                     "qtyCap":500000,
            //                     "qtyFloor":0,
            //                     "maintMarginRatio":0.0185,
            //                     "cum":0.0
            //                 }
            //             ]
            //         }
            //     ]
            //
            return this->parseLeverageTiers(response, symbols, std::string("symbol"));
        }).share();
    }

    std::any parseMarketLeverageTiers(std::any info, std::any market = std::any{}) override
    {
        /**
         * @ignore
         * @method
         * @param {object} info Exchange response for 1 market
         * @param {object} market CCXT market
         */
        //
        //    {
        //        "symbol": "SUSHIUSDT",
        //        "brackets": [
        //            {
        //                "bracket": 1,
        //                "initialLeverage": 50,
        //                "notionalCap": 50000,
        //                "notionalFloor": 0,
        //                "maintMarginRatio": 0.01,
        //                "cum": 0.0
        //            },
        //            ...
        //        ]
        //    }
        //
        std::any marketId = this->safeString(info, std::string("symbol"));
        market = this->safeMarket(marketId, market, std::any{}, std::string("contract"));
        std::any brackets = this->safeList(info, std::string("brackets"), ccxt::list{});
        std::any tiers = ccxt::list{};
        for (std::any j = 0; isLessThan(j, getArrayLength(brackets)); postFixIncrement(j))
        {
            std::any bracket = ::getValue(brackets, j);
            arrayPush(tiers, ccxt::dict {
                { std::string("tier"), this->safeNumber(bracket, std::string("bracket")) },
                { std::string("symbol"), this->safeSymbol(marketId, market) },
                { std::string("currency"), ::getValue(market, std::string("quote")) },
                { std::string("minNotional"), this->safeNumber2(bracket, std::string("notionalFloor"), std::string("qtyFloor")) },
                { std::string("maxNotional"), this->safeNumber2(bracket, std::string("notionalCap"), std::string("qtyCap")) },
                { std::string("maintenanceMarginRate"), this->safeNumber(bracket, std::string("maintMarginRatio")) },
                { std::string("maxLeverage"), this->safeNumber(bracket, std::string("initialLeverage")) },
                { std::string("info"), bracket },
            });
        }
        return tiers;
    }

    /**
     * @method
     * @name binance#fetchPosition
     * @description fetch data on an open position
     * @see https://developers.binance.com/docs/derivatives/option/trade/Option-Position-Information
     * @param {string} symbol unified market symbol of the market the position is held in
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} a [position structure]{@link https://docs.ccxt.com/?id=position-structure}
     */
    std::shared_future<std::any> fetchPosition(std::any symbol, std::any params = ccxt::dict {}) override
    {
        return std::async(std::launch::deferred, [=]() mutable -> std::any {
            if (isTrue(isEqual(this->markets, std::any{})))
            {
                awaitValue(this->loadMarkets());
            }
            std::any market = this->market(symbol);
            if (isTrue(!isEqual(::getValue(market, std::string("option")), true)))
            {
                throw NotSupported(toString(add(this->id, std::string(" fetchPosition() supports option markets only"))));
            }
            std::any request = ccxt::dict {
                { std::string("symbol"), ::getValue(market, std::string("id")) },
            };
            std::any response = awaitValue(this->eapiPrivateGetPosition(this->extend(request, params)));
            //
            //     [
            //         {
            //             "entryPrice": "27.70000000",
            //             "symbol": "ETH-230426-1850-C",
            //             "side": "LONG",
            //             "quantity": "0.50000000",
            //             "reducibleQty": "0.50000000",
            //             "markValue": "10.250000000",
            //             "ror": "-0.2599",
            //             "unrealizedPNL": "-3.600000000",
            //             "markPrice": "20.5",
            //             "strikePrice": "1850.00000000",
            //             "positionCost": "13.85000000",
            //             "expiryDate": 1682496000000,
            //             "priceScale": 1,
            //             "quantityScale": 2,
            //             "optionSide": "CALL",
            //             "quoteAsset": "USDT",
            //             "time": 1682492427106
            //         }
            //     ]
            //
            return this->parseOptionPosition(this->safeDict(response, 0, ccxt::dict {}), market);
        }).share();
    }

    /**
     * @method
     * @name binance#fetchOptionPositions
     * @description fetch data on open options positions
     * @see https://developers.binance.com/docs/derivatives/option/trade/Option-Position-Information
     * @param {string[]|undefined} symbols list of unified market symbols
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object[]} a list of [position structures]{@link https://docs.ccxt.com/?id=position-structure}
     */
    virtual std::shared_future<std::any> fetchOptionPositions(std::any symbols = std::any{}, std::any params = ccxt::dict {})
    {
        return std::async(std::launch::deferred, [=]() mutable -> std::any {
            if (isTrue(isEqual(this->markets, std::any{})))
            {
                awaitValue(this->loadMarkets());
            }
            symbols = this->marketSymbols(symbols);
            std::any request = ccxt::dict {};
            std::any market = std::any{};
            if (isTrue(!isEqual(symbols, std::any{})))
            {
                std::any symbol = std::any{};
                if (isTrue(isArray(symbols)))
                {
                    std::any symbolsLength = getArrayLength(symbols);
                    if (isTrue(isGreaterThan(symbolsLength, 1)))
                    {
                        throw BadRequest(toString(add(this->id, std::string(" fetchPositions() symbols argument cannot contain more than 1 symbol"))));
                    }
                    symbol = ::getValue(symbols, 0);
                } else
                {
                    symbol = symbols;
                }
                market = this->market(symbol);
                ::setValue(request, std::string("symbol"), ::getValue(market, std::string("id")));
            }
            std::any response = awaitValue(this->eapiPrivateGetPosition(this->extend(request, params)));
            //
            //     [
            //         {
            //             "entryPrice": "27.70000000",
            //             "symbol": "ETH-230426-1850-C",
            //             "side": "LONG",
            //             "quantity": "0.50000000",
            //             "reducibleQty": "0.50000000",
            //             "markValue": "10.250000000",
            //             "ror": "-0.2599",
            //             "unrealizedPNL": "-3.600000000",
            //             "markPrice": "20.5",
            //             "strikePrice": "1850.00000000",
            //             "positionCost": "13.85000000",
            //             "expiryDate": 1682496000000,
            //             "priceScale": 1,
            //             "quantityScale": 2,
            //             "optionSide": "CALL",
            //             "quoteAsset": "USDT",
            //             "time": 1682492427106
            //         }
            //     ]
            //
            std::any result = ccxt::list{};
            std::any positions = this->toArray(response);
            for (std::any i = 0; isLessThan(i, getArrayLength(positions)); postFixIncrement(i))
            {
                arrayPush(result, this->parseOptionPosition(::getValue(positions, i), market));
            }
            return this->filterByArrayPositions(result, std::string("symbol"), symbols, false);
        }).share();
    }

    virtual std::any parseOptionPosition(std::any position, std::any market = std::any{})
    {
        //
        //     {
        //         "entryPrice": "27.70000000",
        //         "symbol": "ETH-230426-1850-C",
        //         "side": "LONG",
        //         "quantity": "0.50000000",
        //         "reducibleQty": "0.50000000",
        //         "markValue": "10.250000000",
        //         "ror": "-0.2599",
        //         "unrealizedPNL": "-3.600000000",
        //         "markPrice": "20.5",
        //         "strikePrice": "1850.00000000",
        //         "positionCost": "13.85000000",
        //         "expiryDate": 1682496000000,
        //         "priceScale": 1,
        //         "quantityScale": 2,
        //         "optionSide": "CALL",
        //         "quoteAsset": "USDT",
        //         "time": 1682492427106
        //     }
        //
        std::any marketId = this->safeString(position, std::string("symbol"));
        market = this->safeMarket(marketId, market, std::any{}, std::string("swap"));
        std::any symbol = ::getValue(market, std::string("symbol"));
        std::any side = this->safeStringLower(position, std::string("side"));
        std::any quantity = this->safeString(position, std::string("quantity"));
        if (isTrue(!isEqual(side, std::string("long"))))
        {
            quantity = ccxt::Precise::stringMul(std::string("-1"), quantity);
        }
        std::any timestamp = this->safeInteger(position, std::string("time"));
        return this->safePosition(ccxt::dict {
            { std::string("info"), position },
            { std::string("id"), std::any{} },
            { std::string("symbol"), symbol },
            { std::string("entryPrice"), this->safeNumber(position, std::string("entryPrice")) },
            { std::string("markPrice"), this->safeNumber(position, std::string("markPrice")) },
            { std::string("notional"), this->safeNumber(position, std::string("markValue")) },
            { std::string("collateral"), this->safeNumber(position, std::string("positionCost")) },
            { std::string("unrealizedPnl"), this->safeNumber(position, std::string("unrealizedPNL")) },
            { std::string("side"), side },
            { std::string("contracts"), this->parseNumber(quantity) },
            { std::string("contractSize"), std::any{} },
            { std::string("timestamp"), timestamp },
            { std::string("datetime"), this->iso8601(timestamp) },
            { std::string("hedged"), std::any{} },
            { std::string("maintenanceMargin"), std::any{} },
            { std::string("maintenanceMarginPercentage"), std::any{} },
            { std::string("initialMargin"), std::any{} },
            { std::string("initialMarginPercentage"), std::any{} },
            { std::string("leverage"), std::any{} },
            { std::string("liquidationPrice"), std::any{} },
            { std::string("marginRatio"), std::any{} },
            { std::string("marginMode"), std::any{} },
            { std::string("percentage"), std::any{} },
        });
    }

    /**
     * @method
     * @name binance#fetchPositions
     * @description fetch all open positions
     * @see https://developers.binance.com/docs/derivatives/usds-margined-futures/account/rest-api/Account-Information-V2
     * @see https://developers.binance.com/docs/derivatives/coin-margined-futures/account/rest-api/Account-Information
     * @see https://developers.binance.com/docs/derivatives/usds-margined-futures/trade/rest-api/Position-Information-V2
     * @see https://developers.binance.com/docs/derivatives/coin-margined-futures/trade/rest-api/Position-Information
     * @see https://developers.binance.com/docs/derivatives/option/trade/Option-Position-Information
     * @param {string[]} [symbols] list of unified market symbols
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {object} [params.params] extra parameters specific to the exchange API endpoint
     * @param {string} [params.method] method name to call, "positionRisk", "account" or "option", default is "positionRisk"
     * @param {bool} [params.useV2] set to true if you want to use the obsolete endpoint, where some more additional fields were provided
     * @returns {object[]} a list of [position structure]{@link https://docs.ccxt.com/?id=position-structure}
     */
    std::shared_future<std::any> fetchPositions(std::any symbols = std::any{}, std::any params = ccxt::dict {}) override
    {
        return std::async(std::launch::deferred, [=]() mutable -> std::any {
            std::any defaultMethod = std::any{};
            std::any defaultMethodparamsVariable = this->handleOptionAndParams(params, std::string("fetchPositions"), std::string("method"));
            defaultMethod = ::getValue(defaultMethodparamsVariable, 0);
            params = ::getValue(defaultMethodparamsVariable, 1); // check if there is a key in options|params
            if (isTrue(isEqual(defaultMethod, std::any{})))
            {
                // check if .options['fetchPositions'] dict exist at all
                std::any options = this->safeDict(this->options, std::string("fetchPositions"));
                if (isTrue(isEqual(options, std::any{})))
                {
                    // if undefined, for backward compatibility, check if it is a string
                    defaultMethod = this->safeString(this->options, std::string("fetchPositions"), std::string("positionRisk"));
                } else
                {
                    // if it is a dict, then it doesn't seem to have any 'method', so set default value
                    defaultMethod = std::string("positionRisk");
                }
            }
            if (isTrue(isEqual(defaultMethod, std::string("positionRisk"))))
            {
                return awaitValue(this->fetchPositionsRisk(symbols, params));
            } else if (isTrue(isEqual(defaultMethod, std::string("account"))))
            {
                return awaitValue(this->fetchAccountPositions(symbols, params));
            } else if (isTrue(isEqual(defaultMethod, std::string("option"))))
            {
                return awaitValue(this->fetchOptionPositions(symbols, params));
            } else
            {
                throw NotSupported(toString(add(add(add(this->id, std::string(".options[\"fetchPositions\"][\"method\"] or params[\"method\"] = \"")), defaultMethod), std::string("\" is invalid, please choose between \"account\", \"positionRisk\" and \"option\""))));
            }
            return std::any{};
        }).share();
    }

    /**
     * @method
     * @name binance#fetchAccountPositions
     * @ignore
     * @description fetch account positions
     * @see https://developers.binance.com/docs/derivatives/usds-margined-futures/account/rest-api/Account-Information-V2
     * @see https://developers.binance.com/docs/derivatives/coin-margined-futures/account/rest-api/Account-Information
     * @see https://developers.binance.com/docs/derivatives/usds-margined-futures/trade/rest-api/Position-Information-V2
     * @see https://developers.binance.com/docs/derivatives/coin-margined-futures/trade/rest-api/Position-Information
     * @see https://developers.binance.com/docs/derivatives/usds-margined-futures/account/rest-api/Account-Information-V3
     * @param {string[]} [symbols] list of unified market symbols
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {boolean} [params.portfolioMargin] set to true if you would like to fetch positions in a portfolio margin account
     * @param {string} [params.subType] "linear" or "inverse"
     * @param {boolean} [params.filterClosed] set to true if you would like to filter out closed positions, default is false
     * @param {boolean} [params.useV2] set to true if you want to use obsolete endpoint, where some more additional fields were provided
     * @returns {object} data on account positions
     */
    virtual std::shared_future<std::any> fetchAccountPositions(std::any symbols = std::any{}, std::any params = ccxt::dict {})
    {
        return std::async(std::launch::deferred, [=]() mutable -> std::any {
            if (isTrue(!isEqual(symbols, std::any{})))
            {
                if (!isTrue(isArray(symbols)))
                {
                    throw ArgumentsRequired(toString(add(this->id, std::string(" fetchPositions() requires an array argument for symbols"))));
                }
            }
            if (isTrue(isEqual(this->markets, std::any{})))
            {
                awaitValue(this->loadMarkets());
            }
            awaitValue(this->loadLeverageBrackets(false, params));
            std::any defaultType = this->safeString(this->options, std::string("defaultType"), std::string("future"));
            std::any type = this->safeString(params, std::string("type"), defaultType);
            params = this->omit(params, std::string("type"));
            std::any subType = std::any{};
            std::any subTypeparamsVariable = this->handleSubTypeAndParams(std::string("fetchAccountPositions"), std::any{}, params, std::string("linear"));
            subType = ::getValue(subTypeparamsVariable, 0);
            params = ::getValue(subTypeparamsVariable, 1);
            std::any isPortfolioMargin = std::any{};
            std::any isPortfolioMarginparamsVariable = this->handleOptionAndParams2(params, std::string("fetchAccountPositions"), std::string("papi"), std::string("portfolioMargin"), false);
            isPortfolioMargin = ::getValue(isPortfolioMarginparamsVariable, 0);
            params = ::getValue(isPortfolioMarginparamsVariable, 1);
            std::any response = std::any{};
            if (isTrue(this->isLinear(type, subType)))
            {
                if (isTrue(isPortfolioMargin))
                {
                    response = awaitValue(this->papiV2GetUmAccount(params));
                } else
                {
                    std::any useV2 = std::any{};
                    std::any useV2paramsVariable = this->handleOptionAndParams(params, std::string("fetchAccountPositions"), std::string("useV2"), false);
                    useV2 = ::getValue(useV2paramsVariable, 0);
                    params = ::getValue(useV2paramsVariable, 1);
                    if (!isTrue(useV2))
                    {
                        response = awaitValue(this->fapiPrivateV3GetAccount(params));
                    } else
                    {
                        response = awaitValue(this->fapiPrivateV2GetAccount(params));
                    }
                }
            } else if (isTrue(this->isInverse(type, subType)))
            {
                if (isTrue(isPortfolioMargin))
                {
                    response = awaitValue(this->papiGetCmAccount(params));
                } else
                {
                    response = awaitValue(this->dapiPrivateGetAccount(params));
                }
            } else
            {
                throw NotSupported(toString(add(this->id, std::string(" fetchPositions() supports linear and inverse contracts only"))));
            }
            std::any filterClosed = std::any{};
            std::any filterClosedparamsVariable = this->handleOptionAndParams(params, std::string("fetchAccountPositions"), std::string("filterClosed"), false);
            filterClosed = ::getValue(filterClosedparamsVariable, 0);
            params = ::getValue(filterClosedparamsVariable, 1);
            std::any result = this->parseAccountPositions(response, filterClosed);
            symbols = this->marketSymbols(symbols);
            return this->filterByArrayPositions(result, std::string("symbol"), symbols, false);
        }).share();
    }

    /**
     * @method
     * @name binance#fetchPositionsRisk
     * @ignore
     * @description fetch positions risk
     * @see https://developers.binance.com/docs/derivatives/usds-margined-futures/trade/rest-api/Position-Information-V2
     * @see https://developers.binance.com/docs/derivatives/coin-margined-futures/trade/rest-api/Position-Information
     * @see https://developers.binance.com/docs/derivatives/portfolio-margin/account/Query-UM-Position-Information
     * @see https://developers.binance.com/docs/derivatives/portfolio-margin/account/Query-CM-Position-Information
     * @see https://developers.binance.com/docs/derivatives/usds-margined-futures/trade/rest-api/Position-Information-V3
     * @param {string[]|undefined} symbols list of unified market symbols
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {boolean} [params.portfolioMargin] set to true if you would like to fetch positions for a portfolio margin account
     * @param {string} [params.subType] "linear" or "inverse"
     * @param {bool} [params.useV2] set to true if you want to use the obsolete endpoint, where some more additional fields were provided
     * @returns {object} data on the positions risk
     */
    std::shared_future<std::any> fetchPositionsRisk(std::any symbols = std::any{}, std::any params = ccxt::dict {}) override
    {
        return std::async(std::launch::deferred, [=]() mutable -> std::any {
            if (isTrue(!isEqual(symbols, std::any{})))
            {
                if (!isTrue(isArray(symbols)))
                {
                    throw ArgumentsRequired(toString(add(this->id, std::string(" fetchPositionsRisk() requires an array argument for symbols"))));
                }
            }
            if (isTrue(isEqual(this->markets, std::any{})))
            {
                awaitValue(this->loadMarkets());
            }
            awaitValue(this->loadLeverageBrackets(false, params));
            std::any request = ccxt::dict {};
            std::any defaultType = std::string("future");
            defaultType = this->safeString(this->options, std::string("defaultType"), defaultType);
            std::any type = this->safeString(params, std::string("type"), defaultType);
            std::any subType = std::any{};
            std::any subTypeparamsVariable = this->handleSubTypeAndParams(std::string("fetchPositionsRisk"), std::any{}, params, std::string("linear"));
            subType = ::getValue(subTypeparamsVariable, 0);
            params = ::getValue(subTypeparamsVariable, 1);
            std::any isPortfolioMargin = std::any{};
            std::any isPortfolioMarginparamsVariable = this->handleOptionAndParams2(params, std::string("fetchPositionsRisk"), std::string("papi"), std::string("portfolioMargin"), false);
            isPortfolioMargin = ::getValue(isPortfolioMarginparamsVariable, 0);
            params = ::getValue(isPortfolioMarginparamsVariable, 1);
            params = this->omit(params, std::string("type"));
            std::any response = std::any{};
            if (isTrue(this->isLinear(type, subType)))
            {
                if (isTrue(isPortfolioMargin))
                {
                    response = awaitValue(this->papiGetUmPositionRisk(this->extend(request, params)));
                } else
                {
                    std::any useV2 = std::any{};
                    std::any useV2paramsVariable = this->handleOptionAndParams(params, std::string("fetchPositionsRisk"), std::string("useV2"), false);
                    useV2 = ::getValue(useV2paramsVariable, 0);
                    params = ::getValue(useV2paramsVariable, 1);
                    params = this->extend(request, params);
                    if (!isTrue(useV2))
                    {
                        response = awaitValue(this->fapiPrivateV3GetPositionRisk(params));
                    } else
                    {
                        response = awaitValue(this->fapiPrivateV2GetPositionRisk(params));
                    }
                }
            } else if (isTrue(this->isInverse(type, subType)))
            {
                if (isTrue(isPortfolioMargin))
                {
                    response = awaitValue(this->papiGetCmPositionRisk(this->extend(request, params)));
                } else
                {
                    response = awaitValue(this->dapiPrivateGetPositionRisk(this->extend(request, params)));
                }
            } else
            {
                throw NotSupported(toString(add(this->id, std::string(" fetchPositionsRisk() supports linear and inverse contracts only"))));
            }
            // ### Response examples ###
            //
            // For One-way position mode:
            //
            //     [
            //         {
            //             "symbol": "BTCUSDT",
            //             "positionSide": "BOTH",
            //             "positionAmt": "0.000",
            //             "entryPrice": "0.00000",
            //             "markPrice": "6679.50671178",
            //             "unRealizedProfit": "0.00000000",
            //             "liquidationPrice": "0",
            //             "isolatedMargin": "0.00000000",
            //             "marginType": "isolated",
            //             "isAutoAddMargin": "false",
            //             "leverage": "10",
            //             "maxNotionalValue": "20000000",
            //             "updateTime": 0
            //        }
            //     ]
            //
            // For Hedge position mode:
            //
            //     [
            //         {
            //             "entryPrice": "6563.66500",
            //             "marginType": "isolated",
            //             "isAutoAddMargin": "false",
            //             "isolatedMargin": "15517.54150468",
            //             "leverage": "10",
            //             "liquidationPrice": "5930.78",
            //             "markPrice": "6679.50671178",
            //             "maxNotionalValue": "20000000",
            //             "positionSide": "LONG",
            //             "positionAmt": "20.000", // negative value for 'SHORT'
            //             "symbol": "BTCUSDT",
            //             "unRealizedProfit": "2316.83423560"
            //             "updateTime": 1625474304765
            //         },
            //         .. second dict is similar, but with `positionSide: SHORT`
            //     ]
            //
            // inverse portfolio margin:
            //
            //     [
            //         {
            //             "symbol": "ETHUSD_PERP",
            //             "positionAmt": "1",
            //             "entryPrice": "2422.400000007",
            //             "markPrice": "2424.51267823",
            //             "unRealizedProfit": "0.0000036",
            //             "liquidationPrice": "293.57678898",
            //             "leverage": "100",
            //             "positionSide": "LONG",
            //             "updateTime": 1707371941861,
            //             "maxQty": "15",
            //             "notionalValue": "0.00412454",
            //             "breakEvenPrice": "2423.368960034"
            //         }
            //     ]
            //
            // linear portfolio margin:
            //
            //     [
            //         {
            //             "symbol": "BTCUSDT",
            //             "positionAmt": "0.01",
            //             "entryPrice": "44525.0",
            //             "markPrice": "45464.1735922",
            //             "unRealizedProfit": "9.39173592",
            //             "liquidationPrice": "38007.16308568",
            //             "leverage": "100",
            //             "positionSide": "LONG",
            //             "updateTime": 1707371879042,
            //             "maxNotionalValue": "500000.0",
            //             "notional": "454.64173592",
            //             "breakEvenPrice": "44542.81"
            //         }
            //     ]
            //
            std::any result = ccxt::list{};
            if (isTrue(isEqual(response, std::any{})))
            {
                throw NullResponse(toString(add(this->id, std::string(" method() returned empty response"))));
            }
            std::any positions = this->toArray(response);
            for (std::any i = 0; isLessThan(i, getArrayLength(positions)); postFixIncrement(i))
            {
                std::any rawPosition = ::getValue(positions, i);
                std::any entryPriceString = this->safeString(rawPosition, std::string("entryPrice"));
                if (isTrue(ccxt::Precise::stringGt(entryPriceString, std::string("0"))))
                {
                    arrayPush(result, this->parsePositionRisk(rawPosition));
                }
            }
            symbols = this->marketSymbols(symbols);
            return this->filterByArrayPositions(result, std::string("symbol"), symbols, false);
        }).share();
    }

    /**
     * @method
     * @name binance#fetchFundingHistory
     * @description fetch the history of funding payments paid and received on this account
     * @see https://developers.binance.com/docs/derivatives/usds-margined-futures/account/rest-api/Get-Income-History
     * @see https://developers.binance.com/docs/derivatives/coin-margined-futures/account/rest-api/Get-Income-History
     * @see https://developers.binance.com/docs/derivatives/portfolio-margin/account/Get-UM-Income-History
     * @see https://developers.binance.com/docs/derivatives/portfolio-margin/account/Get-CM-Income-History
     * @param {string} symbol unified market symbol
     * @param {int} [since] the earliest time in ms to fetch funding history for
     * @param {int} [limit] the maximum number of funding history structures to retrieve
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {int} [params.until] timestamp in ms of the latest funding history entry
     * @param {boolean} [params.portfolioMargin] set to true if you would like to fetch the funding history for a portfolio margin account
     * @param {string} [params.subType] "linear" or "inverse"
     * @returns {object} a [funding history structure]{@link https://docs.ccxt.com/?id=funding-history-structure}
     */
    std::shared_future<std::any> fetchFundingHistory(std::any symbol = std::any{}, std::any since = std::any{}, std::any limit = std::any{}, std::any params = ccxt::dict {}) override
    {
        return std::async(std::launch::deferred, [=]() mutable -> std::any {
            if (isTrue(isEqual(this->markets, std::any{})))
            {
                awaitValue(this->loadMarkets());
            }
            std::any market = std::any{};
            std::any request = ccxt::dict {
                { std::string("incomeType"), std::string("FUNDING_FEE") },
            };
            if (isTrue(!isEqual(symbol, std::any{})))
            {
                market = this->market(symbol);
                ::setValue(request, std::string("symbol"), ::getValue(market, std::string("id")));
                if (isTrue(!isEqual(::getValue(market, std::string("swap")), true)))
                {
                    throw NotSupported(toString(add(this->id, std::string(" fetchFundingHistory() supports swap contracts only"))));
                }
            }
            std::any subType = std::any{};
            std::any subTypeparamsVariable = this->handleSubTypeAndParams(std::string("fetchFundingHistory"), market, params, std::string("linear"));
            subType = ::getValue(subTypeparamsVariable, 0);
            params = ::getValue(subTypeparamsVariable, 1);
            std::any isPortfolioMargin = std::any{};
            std::any isPortfolioMarginparamsVariable = this->handleOptionAndParams2(params, std::string("fetchFundingHistory"), std::string("papi"), std::string("portfolioMargin"), false);
            isPortfolioMargin = ::getValue(isPortfolioMarginparamsVariable, 0);
            params = ::getValue(isPortfolioMarginparamsVariable, 1);
            std::any requestparamsVariable = this->handleUntilOption(std::string("endTime"), request, params);
            request = ::getValue(requestparamsVariable, 0);
            params = ::getValue(requestparamsVariable, 1);
            if (isTrue(!isEqual(since, std::any{})))
            {
                ::setValue(request, std::string("startTime"), since);
            }
            if (isTrue(!isEqual(limit, std::any{})))
            {
                ::setValue(request, std::string("limit"), limit);
            }
            std::any defaultType = this->safeString2(this->options, std::string("fetchFundingHistory"), std::string("defaultType"), std::string("future"));
            std::any type = this->safeString(params, std::string("type"), defaultType);
            params = this->omit(params, std::string("type"));
            std::any response = std::any{};
            if (isTrue(this->isLinear(type, subType)))
            {
                if (isTrue(isPortfolioMargin))
                {
                    response = awaitValue(this->papiGetUmIncome(this->extend(request, params)));
                } else
                {
                    response = awaitValue(this->fapiPrivateGetIncome(this->extend(request, params)));
                }
            } else if (isTrue(this->isInverse(type, subType)))
            {
                if (isTrue(isPortfolioMargin))
                {
                    response = awaitValue(this->papiGetCmIncome(this->extend(request, params)));
                } else
                {
                    response = awaitValue(this->dapiPrivateGetIncome(this->extend(request, params)));
                }
            } else
            {
                throw NotSupported(toString(add(this->id, std::string(" fetchFundingHistory() supports linear and inverse contracts only"))));
            }
            return this->parseIncomes(response, market, since, limit);
        }).share();
    }

    /**
     * @method
     * @name binance#setLeverage
     * @description set the level of leverage for a market
     * @see https://developers.binance.com/docs/derivatives/usds-margined-futures/trade/rest-api/Change-Initial-Leverage
     * @see https://developers.binance.com/docs/derivatives/coin-margined-futures/trade/rest-api/Change-Initial-Leverage
     * @see https://developers.binance.com/docs/derivatives/portfolio-margin/account/Change-UM-Initial-Leverage
     * @see https://developers.binance.com/docs/derivatives/portfolio-margin/account/Change-CM-Initial-Leverage
     * @param {float} leverage the rate of leverage
     * @param {string} symbol unified market symbol
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {boolean} [params.portfolioMargin] set to true if you would like to set the leverage for a trading pair in a portfolio margin account
     * @returns {object} response from the exchange
     */
    std::shared_future<std::any> setLeverage(std::any leverage, std::any symbol = std::any{}, std::any params = ccxt::dict {}) override
    {
        return std::async(std::launch::deferred, [=]() mutable -> std::any {
            if (isTrue(isEqual(symbol, std::any{})))
            {
                throw ArgumentsRequired(toString(add(this->id, std::string(" setLeverage() requires a symbol argument"))));
            }
            // WARNING: THIS WILL INCREASE LIQUIDATION PRICE FOR OPEN ISOLATED LONG POSITIONS
            // AND DECREASE LIQUIDATION PRICE FOR OPEN ISOLATED SHORT POSITIONS
            if (isTrue(isTrue((isLessThan(leverage, 1))) || isTrue((isGreaterThan(leverage, 125)))))
            {
                throw BadRequest(toString(add(this->id, std::string(" leverage should be between 1 and 125"))));
            }
            if (isTrue(isEqual(this->markets, std::any{})))
            {
                awaitValue(this->loadMarkets());
            }
            std::any market = this->market(symbol);
            std::any request = ccxt::dict {
                { std::string("symbol"), ::getValue(market, std::string("id")) },
                { std::string("leverage"), leverage },
            };
            std::any isPortfolioMargin = std::any{};
            std::any isPortfolioMarginparamsVariable = this->handleOptionAndParams2(params, std::string("setLeverage"), std::string("papi"), std::string("portfolioMargin"), false);
            isPortfolioMargin = ::getValue(isPortfolioMarginparamsVariable, 0);
            params = ::getValue(isPortfolioMarginparamsVariable, 1);
            std::any response = std::any{};
            if (isTrue(isEqual(::getValue(market, std::string("linear")), true)))
            {
                if (isTrue(isPortfolioMargin))
                {
                    response = awaitValue(this->papiPostUmLeverage(this->extend(request, params)));
                } else
                {
                    response = awaitValue(this->fapiPrivatePostLeverage(this->extend(request, params)));
                }
            } else if (isTrue(isEqual(::getValue(market, std::string("inverse")), true)))
            {
                if (isTrue(isPortfolioMargin))
                {
                    response = awaitValue(this->papiPostCmLeverage(this->extend(request, params)));
                } else
                {
                    response = awaitValue(this->dapiPrivatePostLeverage(this->extend(request, params)));
                }
            } else
            {
                throw NotSupported(toString(add(this->id, std::string(" setLeverage() supports linear and inverse contracts only"))));
            }
            if (isTrue(isEqual(response, std::any{})))
            {
                throw NullResponse(toString(add(this->id, std::string(" setLeverage() returned empty response"))));
            }
            return response;
        }).share();
    }

    /**
     * @method
     * @name binance#setMarginMode
     * @description set margin mode to 'cross' or 'isolated'
     * @see https://developers.binance.com/docs/derivatives/usds-margined-futures/trade/rest-api/Change-Margin-Type
     * @see https://developers.binance.com/docs/derivatives/coin-margined-futures/trade/rest-api/Change-Margin-Type
     * @param {string} marginMode 'cross' or 'isolated'
     * @param {string} symbol unified market symbol
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} response from the exchange
     */
    std::shared_future<std::any> setMarginMode(std::any marginMode, std::any symbol = std::any{}, std::any params = ccxt::dict {}) override
    {
        return std::async(std::launch::deferred, [=]() mutable -> std::any {
            if (isTrue(isEqual(symbol, std::any{})))
            {
                throw ArgumentsRequired(toString(add(this->id, std::string(" setMarginMode() requires a symbol argument"))));
            }
            //
            // { "code": -4048 , "msg": "Margin type cannot be changed if there exists position." }
            //
            // or
            //
            // { "code": 200, "msg": "success" }
            //
            marginMode = toUpperCase(marginMode);
            if (isTrue(isEqual(marginMode, std::string("CROSS"))))
            {
                marginMode = std::string("CROSSED");
            }
            if (isTrue(isTrue((!isEqual(marginMode, std::string("ISOLATED")))) && isTrue((!isEqual(marginMode, std::string("CROSSED"))))))
            {
                throw BadRequest(toString(add(this->id, std::string(" marginMode must be either isolated or cross"))));
            }
            if (isTrue(isEqual(this->markets, std::any{})))
            {
                awaitValue(this->loadMarkets());
            }
            std::any market = this->market(symbol);
            std::any request = ccxt::dict {
                { std::string("symbol"), ::getValue(market, std::string("id")) },
                { std::string("marginType"), marginMode },
            };
            std::any response = std::any{};
            try
            {
                if (isTrue(isEqual(::getValue(market, std::string("linear")), true)))
                {
                    response = awaitValue(this->fapiPrivatePostMarginType(this->extend(request, params)));
                } else if (isTrue(isEqual(::getValue(market, std::string("inverse")), true)))
                {
                    response = awaitValue(this->dapiPrivatePostMarginType(this->extend(request, params)));
                } else
                {
                    throw NotSupported(toString(add(this->id, std::string(" setMarginMode() supports linear and inverse contracts only"))));
                }
            } catch(const std::exception& e)
            {
                // not an error
                // https://github.com/ccxt/ccxt/issues/11268
                // https://github.com/ccxt/ccxt/pull/11624
                // POST https://fapi.binance.com/fapi/v1/marginType 400 Bad Request
                // binanceusdm
                if (isTrue(isInstanceOf<MarginModeAlreadySet>(e)))
                {
                    std::any throwMarginModeAlreadySet = this->handleOption(std::string("setMarginMode"), std::string("throwMarginModeAlreadySet"), false);
                    if (isTrue(isEqual(throwMarginModeAlreadySet, true)))
                    {
                        throw;
                    } else
                    {
                        response = ccxt::dict {
                            { std::string("code"), -4046 },
                            { std::string("msg"), std::string("No need to change margin type.") },
                        };
                    }
                } else
                {
                    throw;
                }
            }
            if (isTrue(isEqual(response, std::any{})))
            {
                throw NullResponse(toString(add(this->id, std::string(" setMarginMode() returned empty response"))));
            }
            return response;
        }).share();
    }

    /**
     * @method
     * @name binance#setPositionMode
     * @description set hedged to true or false for a market
     * @see https://developers.binance.com/docs/derivatives/usds-margined-futures/trade/rest-api/Change-Position-Mode
     * @see https://developers.binance.com/docs/derivatives/coin-margined-futures/trade/rest-api/Change-Position-Mode
     * @see https://developers.binance.com/docs/derivatives/portfolio-margin/account/Get-UM-Current-Position-Mode
     * @see https://developers.binance.com/docs/derivatives/portfolio-margin/account/Get-CM-Current-Position-Mode
     * @param {bool} hedged set to true to use dualSidePosition
     * @param {string} symbol not used by setPositionMode ()
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {boolean} [params.portfolioMargin] set to true if you would like to set the position mode for a portfolio margin account
     * @param {string} [params.subType] "linear" or "inverse"
     * @returns {object} response from the exchange
     */
    std::shared_future<std::any> setPositionMode(std::any hedged, std::any symbol = std::any{}, std::any params = ccxt::dict {}) override
    {
        return std::async(std::launch::deferred, [=]() mutable -> std::any {
            std::any market = std::any{};
            if (isTrue(!isEqual(symbol, std::any{})))
            {
                market = this->market(symbol);
            }
            std::any type = std::any{};
            std::any typeparamsVariable = this->handleMarketTypeAndParams(std::string("setPositionMode"), market, params);
            type = ::getValue(typeparamsVariable, 0);
            params = ::getValue(typeparamsVariable, 1);
            std::any subType = std::any{};
            std::any subTypeparamsVariable = this->handleSubTypeAndParams(std::string("setPositionMode"), market, params);
            subType = ::getValue(subTypeparamsVariable, 0);
            params = ::getValue(subTypeparamsVariable, 1);
            std::any isPortfolioMargin = std::any{};
            std::any isPortfolioMarginparamsVariable = this->handleOptionAndParams2(params, std::string("setPositionMode"), std::string("papi"), std::string("portfolioMargin"), false);
            isPortfolioMargin = ::getValue(isPortfolioMarginparamsVariable, 0);
            params = ::getValue(isPortfolioMarginparamsVariable, 1);
            std::any dualSidePosition = std::any{};
            if (isTrue(hedged))
            {
                dualSidePosition = std::string("true");
            } else
            {
                dualSidePosition = std::string("false");
            }
            std::any request = ccxt::dict {
                { std::string("dualSidePosition"), dualSidePosition },
            };
            std::any response = std::any{};
            if (isTrue(this->isInverse(type, subType)))
            {
                if (isTrue(isPortfolioMargin))
                {
                    response = awaitValue(this->papiPostCmPositionSideDual(this->extend(request, params)));
                } else
                {
                    response = awaitValue(this->dapiPrivatePostPositionSideDual(this->extend(request, params)));
                }
            } else if (isTrue(this->isLinear(type, subType)))
            {
                if (isTrue(isPortfolioMargin))
                {
                    response = awaitValue(this->papiPostUmPositionSideDual(this->extend(request, params)));
                } else
                {
                    response = awaitValue(this->fapiPrivatePostPositionSideDual(this->extend(request, params)));
                }
            } else
            {
                throw BadRequest(toString(add(this->id, std::string(" setPositionMode() supports linear and inverse contracts only"))));
            }
            //
            //     {
            //       "code": 200,
            //       "msg": "success"
            //     }
            //
            if (isTrue(isEqual(response, std::any{})))
            {
                throw NullResponse(toString(add(this->id, std::string(" setPositionMode() returned empty response"))));
            }
            return response;
        }).share();
    }

    /**
     * @method
     * @name binance#fetchLeverages
     * @description fetch the set leverage for all markets
     * @see https://developers.binance.com/docs/derivatives/usds-margined-futures/account/rest-api/Account-Information-V2
     * @see https://developers.binance.com/docs/derivatives/coin-margined-futures/account/rest-api/Account-Information
     * @see https://developers.binance.com/docs/derivatives/portfolio-margin/account/Get-UM-Account-Detail
     * @see https://developers.binance.com/docs/derivatives/portfolio-margin/account/Get-CM-Account-Detail
     * @see https://developers.binance.com/docs/derivatives/usds-margined-futures/account/rest-api/Symbol-Config
     * @param {string[]} [symbols] a list of unified market symbols
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {string} [params.subType] "linear" or "inverse"
     * @returns {object} a list of [leverage structures]{@link https://docs.ccxt.com/?id=leverage-structure}
     */
    std::shared_future<std::any> fetchLeverages(std::any symbols = std::any{}, std::any params = ccxt::dict {}) override
    {
        return std::async(std::launch::deferred, [=]() mutable -> std::any {
            if (isTrue(isEqual(this->markets, std::any{})))
            {
                awaitValue(this->loadMarkets());
            }
            awaitValue(this->loadLeverageBrackets(false, params));
            std::any type = std::any{};
            std::any typeparamsVariable = this->handleMarketTypeAndParams(std::string("fetchLeverages"), std::any{}, params);
            type = ::getValue(typeparamsVariable, 0);
            params = ::getValue(typeparamsVariable, 1);
            std::any subType = std::any{};
            std::any subTypeparamsVariable = this->handleSubTypeAndParams(std::string("fetchLeverages"), std::any{}, params, std::string("linear"));
            subType = ::getValue(subTypeparamsVariable, 0);
            params = ::getValue(subTypeparamsVariable, 1);
            std::any isPortfolioMargin = std::any{};
            std::any isPortfolioMarginparamsVariable = this->handleOptionAndParams2(params, std::string("fetchLeverages"), std::string("papi"), std::string("portfolioMargin"), false);
            isPortfolioMargin = ::getValue(isPortfolioMarginparamsVariable, 0);
            params = ::getValue(isPortfolioMarginparamsVariable, 1);
            std::any response = std::any{};
            if (isTrue(this->isLinear(type, subType)))
            {
                if (isTrue(isPortfolioMargin))
                {
                    response = awaitValue(this->papiGetUmAccount(params));
                } else
                {
                    response = awaitValue(this->fapiPrivateGetSymbolConfig(params));
                }
            } else if (isTrue(this->isInverse(type, subType)))
            {
                if (isTrue(isPortfolioMargin))
                {
                    response = awaitValue(this->papiGetCmAccount(params));
                } else
                {
                    response = awaitValue(this->dapiPrivateGetAccount(params));
                }
            } else
            {
                throw NotSupported(toString(add(this->id, std::string(" fetchLeverages() supports linear and inverse contracts only"))));
            }
            std::any leverages = this->safeList(response, std::string("positions"), ccxt::list{});
            if (isTrue(isArray(response)))
            {
                leverages = response;
            }
            return this->parseLeverages(leverages, symbols, std::string("symbol"));
        }).share();
    }

    std::any parseLeverage(std::any leverage, std::any market = std::any{}) override
    {
        std::any marketId = this->safeString(leverage, std::string("symbol"));
        std::any marginModeRaw = this->safeBool(leverage, std::string("isolated"));
        std::any marginMode = std::any{};
        if (isTrue(!isEqual(marginModeRaw, std::any{})))
        {
            marginMode = (isTrue(marginModeRaw) ? std::any(std::string("isolated")) : std::any(std::string("cross")));
        }
        std::any marginTypeRaw = this->safeStringLower(leverage, std::string("marginType"));
        if (isTrue(!isEqual(marginTypeRaw, std::any{})))
        {
            marginMode = (isTrue((isEqual(marginTypeRaw, std::string("crossed")))) ? std::any(std::string("cross")) : std::any(std::string("isolated")));
        }
        std::any side = this->safeStringLower(leverage, std::string("positionSide"));
        std::any longLeverage = std::any{};
        std::any shortLeverage = std::any{};
        std::any leverageValue = this->safeInteger(leverage, std::string("leverage"));
        if (isTrue(isTrue((isEqual(side, std::any{}))) || isTrue((isEqual(side, std::string("both"))))))
        {
            longLeverage = leverageValue;
            shortLeverage = leverageValue;
        } else if (isTrue(isEqual(side, std::string("long"))))
        {
            longLeverage = leverageValue;
        } else if (isTrue(isEqual(side, std::string("short"))))
        {
            shortLeverage = leverageValue;
        }
        return ccxt::dict {
            { std::string("info"), leverage },
            { std::string("symbol"), this->safeSymbol(marketId, market) },
            { std::string("marginMode"), marginMode },
            { std::string("longLeverage"), longLeverage },
            { std::string("shortLeverage"), shortLeverage },
        };
    }

    /**
     * @method
     * @name binance#fetchSettlementHistory
     * @description fetches historical settlement records
     * @see https://developers.binance.com/docs/derivatives/option/market-data/Historical-Exercise-Records
     * @param {string} symbol unified market symbol of the settlement history
     * @param {int} [since] timestamp in ms
     * @param {int} [limit] number of records, default 100, max 100
     * @param {object} [params] exchange specific params
     * @returns {object[]} a list of [settlement history objects]{@link https://docs.ccxt.com/?id=settlement-history-structure}
     */
    virtual std::shared_future<std::any> fetchSettlementHistory(std::any symbol = std::any{}, std::any since = std::any{}, std::any limit = std::any{}, std::any params = ccxt::dict {})
    {
        return std::async(std::launch::deferred, [=]() mutable -> std::any {
            if (isTrue(isEqual(this->markets, std::any{})))
            {
                awaitValue(this->loadMarkets());
            }
            std::any market = (isTrue((isEqual(symbol, std::any{}))) ? std::any(std::any{}) : std::any(this->market(symbol)));
            std::any type = std::any{};
            std::any typeparamsVariable = this->handleMarketTypeAndParams(std::string("fetchSettlementHistory"), market, params);
            type = ::getValue(typeparamsVariable, 0);
            params = ::getValue(typeparamsVariable, 1);
            if (isTrue(!isEqual(type, std::string("option"))))
            {
                throw NotSupported(toString(add(this->id, std::string(" fetchSettlementHistory() supports option markets only"))));
            }
            std::any request = ccxt::dict {};
            if (isTrue(!isEqual(symbol, std::any{})))
            {
                symbol = this->safeString(market, std::string("symbol"));
                ::setValue(request, std::string("underlying"), add(this->safeString(market, std::string("baseId"), std::string("")), this->safeString(market, std::string("quoteId"), std::string(""))));
            }
            if (isTrue(!isEqual(since, std::any{})))
            {
                ::setValue(request, std::string("startTime"), since);
            }
            if (isTrue(!isEqual(limit, std::any{})))
            {
                ::setValue(request, std::string("limit"), limit);
            }
            std::any response = awaitValue(this->eapiPublicGetExerciseHistory(this->extend(request, params)));
            //
            //     [
            //         {
            //             "symbol": "ETH-230223-1900-P",
            //             "strikePrice": "1900",
            //             "realStrikePrice": "1665.5897334",
            //             "expiryDate": 1677139200000,
            //             "strikeResult": "REALISTIC_VALUE_STRICKEN"
            //         }
            //     ]
            //
            std::any settlements = this->parseSettlements(response, market);
            std::any sorted = this->sortBy(settlements, std::string("timestamp"));
            return this->filterBySymbolSinceLimit(sorted, symbol, since, limit);
        }).share();
    }

    /**
     * @method
     * @name binance#fetchMySettlementHistory
     * @description fetches historical settlement records of the user
     * @see https://developers.binance.com/docs/derivatives/option/trade/User-Exercise-Record
     * @param {string} symbol unified market symbol of the settlement history
     * @param {int} [since] timestamp in ms
     * @param {int} [limit] number of records
     * @param {object} [params] exchange specific params
     * @returns {object[]} a list of [settlement history objects]
     */
    virtual std::shared_future<std::any> fetchMySettlementHistory(std::any symbol = std::any{}, std::any since = std::any{}, std::any limit = std::any{}, std::any params = ccxt::dict {})
    {
        return std::async(std::launch::deferred, [=]() mutable -> std::any {
            if (isTrue(isEqual(this->markets, std::any{})))
            {
                awaitValue(this->loadMarkets());
            }
            std::any market = (isTrue((isEqual(symbol, std::any{}))) ? std::any(std::any{}) : std::any(this->market(symbol)));
            std::any type = std::any{};
            std::any typeparamsVariable = this->handleMarketTypeAndParams(std::string("fetchMySettlementHistory"), market, params);
            type = ::getValue(typeparamsVariable, 0);
            params = ::getValue(typeparamsVariable, 1);
            if (isTrue(!isEqual(type, std::string("option"))))
            {
                throw NotSupported(toString(add(this->id, std::string(" fetchMySettlementHistory() supports option markets only"))));
            }
            std::any request = ccxt::dict {};
            if (isTrue(!isEqual(symbol, std::any{})))
            {
                ::setValue(request, std::string("symbol"), this->safeString(market, std::string("id")));
                symbol = this->safeString(market, std::string("symbol"));
            }
            if (isTrue(!isEqual(since, std::any{})))
            {
                ::setValue(request, std::string("startTime"), since);
            }
            if (isTrue(!isEqual(limit, std::any{})))
            {
                ::setValue(request, std::string("limit"), limit);
            }
            std::any response = awaitValue(this->eapiPrivateGetExerciseRecord(this->extend(request, params)));
            //
            //     [
            //         {
            //             "id": "1125899906842897036",
            //             "currency": "USDT",
            //             "symbol": "BTC-230728-30000-C",
            //             "exercisePrice": "30000.00000000",
            //             "markPrice": "29160.71284993",
            //             "quantity": "1.00000000",
            //             "amount": "0.00000000",
            //             "fee": "0.00000000",
            //             "createDate": 1690531200000,
            //             "priceScale": 0,
            //             "quantityScale": 2,
            //             "optionSide": "CALL",
            //             "positionSide": "LONG",
            //             "quoteAsset": "USDT"
            //         }
            //     ]
            //
            std::any settlements = this->parseSettlements(response, market);
            std::any sorted = this->sortBy(settlements, std::string("timestamp"));
            return this->filterBySymbolSinceLimit(sorted, symbol, since, limit);
        }).share();
    }

    virtual std::any parseSettlement(std::any settlement, std::any market)
    {
        //
        // fetchSettlementHistory
        //
        //     {
        //         "symbol": "ETH-230223-1900-P",
        //         "strikePrice": "1900",
        //         "realStrikePrice": "1665.5897334",
        //         "expiryDate": 1677139200000,
        //         "strikeResult": "REALISTIC_VALUE_STRICKEN"
        //     }
        //
        // fetchMySettlementHistory
        //
        //     {
        //         "id": "1125899906842897036",
        //         "currency": "USDT",
        //         "symbol": "BTC-230728-30000-C",
        //         "exercisePrice": "30000.00000000",
        //         "markPrice": "29160.71284993",
        //         "quantity": "1.00000000",
        //         "amount": "0.00000000",
        //         "fee": "0.00000000",
        //         "createDate": 1690531200000,
        //         "priceScale": 0,
        //         "quantityScale": 2,
        //         "optionSide": "CALL",
        //         "positionSide": "LONG",
        //         "quoteAsset": "USDT"
        //     }
        //
        std::any timestamp = this->safeInteger2(settlement, std::string("expiryDate"), std::string("createDate"));
        std::any marketId = this->safeString(settlement, std::string("symbol"));
        return ccxt::dict {
            { std::string("info"), settlement },
            { std::string("symbol"), this->safeSymbol(marketId, market) },
            { std::string("price"), this->safeNumber2(settlement, std::string("realStrikePrice"), std::string("exercisePrice")) },
            { std::string("timestamp"), timestamp },
            { std::string("datetime"), this->iso8601(timestamp) },
        };
    }

    virtual std::any parseSettlements(std::any settlements, std::any market)
    {
        //
        // fetchSettlementHistory
        //
        //     [
        //         {
        //             "symbol": "ETH-230223-1900-P",
        //             "strikePrice": "1900",
        //             "realStrikePrice": "1665.5897334",
        //             "expiryDate": 1677139200000,
        //             "strikeResult": "EXTRINSIC_VALUE_EXPIRED"
        //         }
        //     ]
        //
        // fetchMySettlementHistory
        //
        //     [
        //         {
        //             "id": "1125899906842897036",
        //             "currency": "USDT",
        //             "symbol": "BTC-230728-30000-C",
        //             "exercisePrice": "30000.00000000",
        //             "markPrice": "29160.71284993",
        //             "quantity": "1.00000000",
        //             "amount": "0.00000000",
        //             "fee": "0.00000000",
        //             "createDate": 1690531200000,
        //             "priceScale": 0,
        //             "quantityScale": 2,
        //             "optionSide": "CALL",
        //             "positionSide": "LONG",
        //             "quoteAsset": "USDT"
        //         }
        //     ]
        //
        std::any result = ccxt::list{};
        for (std::any i = 0; isLessThan(i, getArrayLength(settlements)); postFixIncrement(i))
        {
            arrayPush(result, this->parseSettlement(::getValue(settlements, i), market));
        }
        return result;
    }

    /**
     * @method
     * @name binance#fetchLedgerEntry
     * @description fetch the history of changes, actions done by the user or operations that altered the balance of the user
     * @see https://developers.binance.com/docs/derivatives/option/account/Account-Funding-Flow
     * @param {string} id the identification number of the ledger entry
     * @param {string} code unified currency code
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} a [ledger structure]{@link https://docs.ccxt.com/?id=ledger-entry-structure}
     */
    std::shared_future<std::any> fetchLedgerEntry(std::any id, std::any code = std::any{}, std::any params = ccxt::dict {}) override
    {
        return std::async(std::launch::deferred, [=]() mutable -> std::any {
            if (isTrue(isEqual(this->markets, std::any{})))
            {
                awaitValue(this->loadMarkets());
            }
            std::any type = std::any{};
            std::any typeparamsVariable = this->handleMarketTypeAndParams(std::string("fetchLedgerEntry"), std::any{}, params);
            type = ::getValue(typeparamsVariable, 0);
            params = ::getValue(typeparamsVariable, 1);
            if (isTrue(!isEqual(type, std::string("option"))))
            {
                throw BadRequest(toString(add(this->id, std::string(" fetchLedgerEntry() can only be used for type option"))));
            }
            this->checkRequiredArgument(std::string("fetchLedgerEntry"), code, std::string("code"));
            std::any currency = this->currency(code);
            std::any request = ccxt::dict {
                { std::string("recordId"), id },
                { std::string("currency"), ::getValue(currency, std::string("id")) },
            };
            std::any response = awaitValue(this->eapiPrivateGetBill(this->extend(request, params)));
            //
            //     [
            //         {
            //             "id": "1125899906845701870",
            //             "asset": "USDT",
            //             "amount": "-0.16518203",
            //             "type": "FEE",
            //             "createDate": 1676621042489
            //         }
            //     ]
            //
            std::any first = this->safeDict(response, 0, response);
            return this->parseLedgerEntry(first, currency);
        }).share();
    }

    /**
     * @method
     * @name binance#fetchLedger
     * @description fetch the history of changes, actions done by the user or operations that altered the balance of the user
     * @see https://developers.binance.com/docs/derivatives/option/account/Account-Funding-Flow
     * @see https://developers.binance.com/docs/derivatives/usds-margined-futures/account/rest-api/Get-Income-History
     * @see https://developers.binance.com/docs/derivatives/coin-margined-futures/account/rest-api/Get-Income-History
     * @see https://developers.binance.com/docs/derivatives/portfolio-margin/account/Get-UM-Income-History
     * @see https://developers.binance.com/docs/derivatives/portfolio-margin/account/Get-CM-Income-History
     * @param {string} [code] unified currency code
     * @param {int} [since] timestamp in ms of the earliest ledger entry
     * @param {int} [limit] max number of ledger entries to return
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {int} [params.until] timestamp in ms of the latest ledger entry
     * @param {boolean} [params.paginate] default false, when true will automatically paginate by calling this endpoint multiple times. See in the docs all the [available parameters](https://github.com/ccxt/ccxt/wiki/Manual#pagination-params)
     * @param {boolean} [params.portfolioMargin] set to true if you would like to fetch the ledger for a portfolio margin account
     * @param {string} [params.subType] "linear" or "inverse"
     * @returns {object} a [ledger structure]{@link https://docs.ccxt.com/?id=ledger-entry-structure}
     */
    std::shared_future<std::any> fetchLedger(std::any code = std::any{}, std::any since = std::any{}, std::any limit = std::any{}, std::any params = ccxt::dict {}) override
    {
        return std::async(std::launch::deferred, [=]() mutable -> std::any {
            if (isTrue(isEqual(this->markets, std::any{})))
            {
                awaitValue(this->loadMarkets());
            }
            std::any paginate = false;
            std::any paginateparamsVariable = this->handleOptionAndParams(params, std::string("fetchLedger"), std::string("paginate"));
            paginate = ::getValue(paginateparamsVariable, 0);
            params = ::getValue(paginateparamsVariable, 1);
            if (isTrue(paginate))
            {
                return awaitValue(this->fetchPaginatedCallDynamic(std::string("fetchLedger"), code, since, limit, params, std::any{}, false));
            }
            std::any type = std::any{};
            std::any subType = std::any{};
            std::any currency = std::any{};
            if (isTrue(!isEqual(code, std::any{})))
            {
                currency = this->currency(code);
            }
            std::any request = ccxt::dict {};
            std::any typeparamsVariable = this->handleMarketTypeAndParams(std::string("fetchLedger"), std::any{}, params);
            type = ::getValue(typeparamsVariable, 0);
            params = ::getValue(typeparamsVariable, 1);
            std::any subTypeparamsVariable = this->handleSubTypeAndParams(std::string("fetchLedger"), std::any{}, params);
            subType = ::getValue(subTypeparamsVariable, 0);
            params = ::getValue(subTypeparamsVariable, 1);
            if (isTrue(!isEqual(since, std::any{})))
            {
                ::setValue(request, std::string("startTime"), since);
            }
            if (isTrue(!isEqual(limit, std::any{})))
            {
                ::setValue(request, std::string("limit"), limit);
            }
            std::any until = this->safeInteger(params, std::string("until"));
            if (isTrue(!isEqual(until, std::any{})))
            {
                params = this->omit(params, std::string("until"));
                ::setValue(request, std::string("endTime"), until);
            }
            std::any isPortfolioMargin = std::any{};
            std::any isPortfolioMarginparamsVariable = this->handleOptionAndParams2(params, std::string("fetchLedger"), std::string("papi"), std::string("portfolioMargin"), false);
            isPortfolioMargin = ::getValue(isPortfolioMarginparamsVariable, 0);
            params = ::getValue(isPortfolioMarginparamsVariable, 1);
            std::any response = std::any{};
            if (isTrue(isEqual(type, std::string("option"))))
            {
                this->checkRequiredArgument(std::string("fetchLedger"), code, std::string("code"));
                if (isTrue(isEqual(currency, std::any{})))
                {
                    throw ExchangeError(toString(add(this->id, std::string(" fetchLedger() could not resolve currency"))));
                }
                ::setValue(request, std::string("currency"), ::getValue(currency, std::string("id")));
                response = awaitValue(this->eapiPrivateGetBill(this->extend(request, params)));
            } else if (isTrue(this->isLinear(type, subType)))
            {
                if (isTrue(isPortfolioMargin))
                {
                    response = awaitValue(this->papiGetUmIncome(this->extend(request, params)));
                } else
                {
                    response = awaitValue(this->fapiPrivateGetIncome(this->extend(request, params)));
                }
            } else if (isTrue(this->isInverse(type, subType)))
            {
                if (isTrue(isPortfolioMargin))
                {
                    response = awaitValue(this->papiGetCmIncome(this->extend(request, params)));
                } else
                {
                    response = awaitValue(this->dapiPrivateGetIncome(this->extend(request, params)));
                }
            } else
            {
                throw NotSupported(toString(add(this->id, std::string(" fetchLedger() supports contract wallets only"))));
            }
            //
            // options (eapi)
            //
            //     [
            //         {
            //             "id": "1125899906845701870",
            //             "asset": "USDT",
            //             "amount": "-0.16518203",
            //             "type": "FEE",
            //             "createDate": 1676621042489
            //         }
            //     ]
            //
            // futures (fapi, dapi, papi)
            //
            //     [
            //         {
            //             "symbol": "",
            //             "incomeType": "TRANSFER",
            //             "income": "10.00000000",
            //             "asset": "USDT",
            //             "time": 1677645250000,
            //             "info": "TRANSFER",
            //             "tranId": 131001573082,
            //             "tradeId": ""
            //         }
            //     ]
            //
            return this->parseLedger(response, currency, since, limit);
        }).share();
    }

    std::any parseLedgerEntry(std::any item, std::any currency = std::any{}) override
    {
        //
        // options (eapi)
        //
        //     {
        //         "id": "1125899906845701870",
        //         "asset": "USDT",
        //         "amount": "-0.16518203",
        //         "type": "FEE",
        //         "createDate": 167662104241
        //     }
        //
        // futures (fapi, dapi, papi)
        //
        //     {
        //         "symbol": "",
        //         "incomeType": "TRANSFER",
        //         "income": "10.00000000",
        //         "asset": "USDT",
        //         "time": 1677645250000,
        //         "info": "TRANSFER",
        //         "tranId": 131001573082,
        //         "tradeId": ""
        //     }
        //
        std::any amount = this->safeString2(item, std::string("amount"), std::string("income"));
        std::any direction = std::any{};
        if (isTrue(ccxt::Precise::stringLe(amount, std::string("0"))))
        {
            direction = std::string("out");
            amount = ccxt::Precise::stringMul(std::string("-1"), amount);
        } else
        {
            direction = std::string("in");
        }
        std::any currencyId = this->safeString(item, std::string("asset"));
        std::any code = this->safeCurrencyCode(currencyId, currency);
        currency = this->safeCurrency(currencyId, currency);
        std::any timestamp = this->safeInteger2(item, std::string("createDate"), std::string("time"));
        std::any type = this->safeString2(item, std::string("type"), std::string("incomeType"));
        return this->safeLedgerEntry(ccxt::dict {
            { std::string("info"), item },
            { std::string("id"), this->safeString2(item, std::string("id"), std::string("tranId")) },
            { std::string("direction"), direction },
            { std::string("account"), std::any{} },
            { std::string("referenceAccount"), std::any{} },
            { std::string("referenceId"), this->safeString(item, std::string("tradeId")) },
            { std::string("type"), this->parseLedgerEntryType(type) },
            { std::string("currency"), code },
            { std::string("amount"), this->parseNumber(amount) },
            { std::string("timestamp"), timestamp },
            { std::string("datetime"), this->iso8601(timestamp) },
            { std::string("before"), std::any{} },
            { std::string("after"), std::any{} },
            { std::string("status"), std::any{} },
            { std::string("fee"), std::any{} },
        }, currency);
    }

    virtual std::any parseLedgerEntryType(std::any type)
    {
        std::any ledgerType = ccxt::dict {
            { std::string("FEE"), std::string("fee") },
            { std::string("FUNDING_FEE"), std::string("fee") },
            { std::string("OPTIONS_PREMIUM_FEE"), std::string("fee") },
            { std::string("POSITION_LIMIT_INCREASE_FEE"), std::string("fee") },
            { std::string("CONTRACT"), std::string("trade") },
            { std::string("REALIZED_PNL"), std::string("trade") },
            { std::string("TRANSFER"), std::string("transfer") },
            { std::string("CROSS_COLLATERAL_TRANSFER"), std::string("transfer") },
            { std::string("INTERNAL_TRANSFER"), std::string("transfer") },
            { std::string("COIN_SWAP_DEPOSIT"), std::string("deposit") },
            { std::string("COIN_SWAP_WITHDRAW"), std::string("withdrawal") },
            { std::string("OPTIONS_SETTLE_PROFIT"), std::string("settlement") },
            { std::string("DELIVERED_SETTELMENT"), std::string("settlement") },
            { std::string("WELCOME_BONUS"), std::string("cashback") },
            { std::string("CONTEST_REWARD"), std::string("cashback") },
            { std::string("COMMISSION_REBATE"), std::string("rebate") },
            { std::string("API_REBATE"), std::string("rebate") },
            { std::string("REFERRAL_KICKBACK"), std::string("referral") },
            { std::string("COMMISSION"), std::string("commission") },
        };
        return this->safeString(ledgerType, type, type);
    }

    virtual std::any getNetworkCodeByNetworkUrl(std::any currencyCode, std::any depositUrl = std::any{})
    {
        // depositUrl is like : https://bscscan.com/address/0xEF238AB229342849..
        if (isTrue(isEqual(depositUrl, std::any{})))
        {
            return std::any{};
        }
        std::any networkCode = std::any{};
        std::any currency = this->currency(currencyCode);
        std::any networks = this->safeDict(currency, std::string("networks"), ccxt::dict {});
        std::any networkCodes = getObjectKeys(networks);
        for (std::any i = 0; isLessThan(i, getArrayLength(networkCodes)); postFixIncrement(i))
        {
            std::any currentNetworkCode = ::getValue(networkCodes, i);
            std::any info = this->safeDict(::getValue(networks, currentNetworkCode), std::string("info"), ccxt::dict {});
            std::any siteUrl = this->safeString(info, std::string("contractAddressUrl"));
            // check if url matches the field's value
            std::any baseDomain = this->getBaseDomainFromUrl(siteUrl);
            if (isTrue(isTrue(isTrue(!isEqual(siteUrl, std::any{})) && isTrue(!isEqual(baseDomain, std::any{}))) && isTrue(startsWith(depositUrl, baseDomain))))
            {
                networkCode = currentNetworkCode;
            }
        }
        return networkCode;
    }

    virtual std::any getBaseDomainFromUrl(std::any url)
    {
        if (isTrue(isEqual(url, std::any{})))
        {
            return std::any{};
        }
        std::any urlParts = split(url, std::string("/"));
        std::any scheme = this->safeString(urlParts, 0);
        if (isTrue(isEqual(scheme, std::any{})))
        {
            return std::any{};
        }
        std::any domain = this->safeString(urlParts, 2);
        if (isTrue(isEqual(domain, std::any{})))
        {
            return std::any{};
        }
        return add(add(add(scheme, std::string("//")), domain), std::string("/"));
    }

    std::any sign(std::any path, std::any api = std::string("public"), std::any method = std::string("GET"), std::any params = ccxt::dict {}, std::any headers = std::any{}, std::any body = std::any{}) override
    {
        std::any urls = this->urls;
        if (!isTrue((inOp(::getValue(urls, std::string("api")), api))))
        {
            throw NotSupported(toString(add(add(add(this->id, std::string(" does not have a testnet/sandbox URL for ")), api), std::string(" endpoints"))));
        }
        std::any url = ::getValue(::getValue(this->urls, std::string("api")), api);
        url = add(url, add(std::string("/"), path));
        if (isTrue(isEqual(path, std::string("historicalTrades"))))
        {
            if (isTrue(isTrue((!isEqual(this->apiKey, std::any{}))) && isTrue((!isEqual(this->apiKey, std::string(""))))))
            {
                headers = ccxt::dict {
                    { std::string("X-MBX-APIKEY"), this->apiKey },
                };
            } else
            {
                throw AuthenticationError(toString(add(this->id, std::string(" historicalTrades endpoint requires `apiKey` credential"))));
            }
        }
        std::any userDataStream = isTrue(isTrue((isEqual(path, std::string("userDataStream")))) || isTrue((isEqual(path, std::string("listenKey"))))) || isTrue((isEqual(path, std::string("userListenToken"))));
        if (isTrue(userDataStream))
        {
            if (isTrue(isTrue((!isEqual(this->apiKey, std::any{}))) && isTrue((!isEqual(this->apiKey, std::string(""))))))
            {
                // v1 special case for userDataStream
                headers = ccxt::dict {
                    { std::string("X-MBX-APIKEY"), this->apiKey },
                    { std::string("Content-Type"), std::string("application/x-www-form-urlencoded") },
                };
                if (isTrue(!isEqual(method, std::string("GET"))))
                {
                    body = this->urlencode(params);
                }
            } else
            {
                throw AuthenticationError(toString(add(this->id, std::string(" userDataStream endpoint requires `apiKey` credential"))));
            }
        } else if (isTrue(isTrue(isTrue(isTrue(isTrue(isTrue(isTrue(isTrue(isTrue(isTrue(isTrue(isTrue((isEqual(api, std::string("private")))) || isTrue((isEqual(api, std::string("eapiPrivate"))))) || isTrue((isTrue(isEqual(api, std::string("sapi"))) && isTrue(!isEqual(path, std::string("system/status")))))) || isTrue((isEqual(api, std::string("sapiV2"))))) || isTrue((isEqual(api, std::string("sapiV3"))))) || isTrue((isEqual(api, std::string("sapiV4"))))) || isTrue((isEqual(api, std::string("dapiPrivate"))))) || isTrue((isEqual(api, std::string("dapiPrivateV2"))))) || isTrue((isEqual(api, std::string("fapiPrivate"))))) || isTrue((isEqual(api, std::string("fapiPrivateV2"))))) || isTrue((isEqual(api, std::string("fapiPrivateV3"))))) || isTrue((isTrue(isEqual(api, std::string("papiV2"))) || isTrue(isTrue(isEqual(api, std::string("papi"))) && isTrue(!isEqual(path, std::string("ping"))))))))
        {
            this->checkRequiredCredentials();
            if (isTrue(isTrue(isTrue((isGreaterThan(getIndexOf(url, std::string("testnet.binancefuture.com")), -1))) && isTrue(this->isSandboxModeEnabled)) && isTrue((!isEqual(this->safeBool(this->options, std::string("disableFuturesSandboxWarning")), true)))))
            {
                throw NotSupported(toString(add(this->id, std::string(" testnet/sandbox mode is not supported for futures anymore, please check the deprecation announcement https://t.me/ccxt_announcements/92 and consider using the demo trading instead."))));
            }
            if (isTrue(isTrue(isEqual(method, std::string("POST"))) && isTrue((isTrue((isEqual(path, std::string("order")))) || isTrue((isEqual(path, std::string("sor/order"))))))))
            {
                // inject in implicit API calls
                std::any newClientOrderId = this->safeString(params, std::string("newClientOrderId"));
                if (isTrue(isEqual(newClientOrderId, std::any{})))
                {
                    std::any isSpotOrMargin = (isTrue(isGreaterThan(getIndexOf(api, std::string("sapi")), -1)) || isTrue(isEqual(api, std::string("private"))));
                    std::any marketType = (isTrue(isSpotOrMargin) ? std::any(std::string("spot")) : std::any(std::string("future")));
                    std::any defaultId = (isTrue((!isTrue(isSpotOrMargin))) ? std::any(std::string("x-xcKtGhcu")) : std::any(std::string("x-TKT5PX2F")));
                    std::any broker = this->safeDict(this->options, std::string("broker"), ccxt::dict {});
                    std::any brokerId = this->safeString(broker, marketType, defaultId);
                    ::setValue(params, std::string("newClientOrderId"), add(brokerId, this->uuid22()));
                }
            }
            std::any query = std::any{};
            // handle batchOrders
            if (isTrue(isTrue((isEqual(path, std::string("batchOrders")))) && isTrue((isTrue((isEqual(method, std::string("POST")))) || isTrue((isEqual(method, std::string("PUT"))))))))
            {
                std::any batchOrders = this->safeList(params, std::string("batchOrders"), ccxt::list{});
                std::any checkedBatchOrders = batchOrders;
                if (isTrue(isTrue(isEqual(method, std::string("POST"))) && isTrue(isEqual(api, std::string("fapiPrivate")))))
                {
                    // check broker id if batchOrders are called with fapiPrivatePostBatchOrders
                    checkedBatchOrders = ccxt::list{};
                    for (std::any i = 0; isLessThan(i, getArrayLength(batchOrders)); postFixIncrement(i))
                    {
                        std::any batchOrder = ::getValue(batchOrders, i);
                        std::any newClientOrderId = this->safeString(batchOrder, std::string("newClientOrderId"));
                        if (isTrue(isEqual(newClientOrderId, std::any{})))
                        {
                            std::any defaultId = std::string("x-xcKtGhcu"); // batchOrders can not be spot or margin
                            std::any broker = this->safeDict(this->options, std::string("broker"), ccxt::dict {});
                            std::any brokerId = this->safeString(broker, std::string("future"), defaultId);
                            newClientOrderId = add(brokerId, this->uuid22());
                            ::setValue(batchOrder, std::string("newClientOrderId"), newClientOrderId);
                        }
                        arrayPush(checkedBatchOrders, batchOrder);
                    }
                }
                std::any queryBatch = (this->json(checkedBatchOrders));
                ::setValue(params, std::string("batchOrders"), queryBatch);
            }
            std::any defaultRecvWindow = this->safeInteger(this->options, std::string("recvWindow"));
            std::any extendedParams = this->extend(ccxt::dict {
                { std::string("timestamp"), this->nonce() },
            }, params);
            if (isTrue(!isEqual(defaultRecvWindow, std::any{})))
            {
                ::setValue(extendedParams, std::string("recvWindow"), defaultRecvWindow);
            }
            std::any recvWindow = this->safeInteger(params, std::string("recvWindow"));
            if (isTrue(!isEqual(recvWindow, std::any{})))
            {
                ::setValue(extendedParams, std::string("recvWindow"), recvWindow);
            }
            if (isTrue(isTrue((isEqual(api, std::string("sapi")))) && isTrue((isEqual(path, std::string("asset/dust"))))))
            {
                query = this->urlencodeWithArrayRepeat(extendedParams);
            } else if (isTrue(isTrue(isTrue(isTrue(isTrue((isEqual(path, std::string("batchOrders")))) || isTrue((isGreaterThanOrEqual(getIndexOf(path, std::string("sub-account")), 0)))) || isTrue((isEqual(path, std::string("capital/withdraw/apply"))))) || isTrue((isGreaterThanOrEqual(getIndexOf(path, std::string("staking")), 0)))) || isTrue((isGreaterThanOrEqual(getIndexOf(path, std::string("simple-earn")), 0)))))
            {
                if (isTrue(isTrue((isEqual(method, std::string("DELETE")))) && isTrue((isEqual(path, std::string("batchOrders"))))))
                {
                    std::any orderidlist = this->safeList(extendedParams, std::string("orderidlist"), ccxt::list{});
                    std::any origclientorderidlist = this->safeList2(extendedParams, std::string("origclientorderidlist"), std::string("origClientOrderIdList"), ccxt::list{});
                    extendedParams = this->omit(extendedParams, ccxt::list{std::string("orderidlist"), std::string("origclientorderidlist"), std::string("origClientOrderIdList")});
                    if (isTrue(inOp(extendedParams, std::string("symbol"))))
                    {
                        ::setValue(extendedParams, std::string("symbol"), this->encodeURIComponent(::getValue(extendedParams, std::string("symbol"))));
                    }
                    query = this->rawencode(extendedParams);
                    std::any orderidlistLength = getArrayLength(orderidlist);
                    std::any origclientorderidlistLength = getArrayLength(origclientorderidlist);
                    if (isTrue(isGreaterThan(orderidlistLength, 0)))
                    {
                        query = add(add(add(add(query, std::string("&")), std::string("orderidlist=%5B")), join(orderidlist, std::string("%2C"))), std::string("%5D"));
                    }
                    if (isTrue(isGreaterThan(origclientorderidlistLength, 0)))
                    {
                        // wrap clientOrderids around ""
                        std::any newClientOrderIds = ccxt::list{};
                        for (std::any i = 0; isLessThan(i, origclientorderidlistLength); postFixIncrement(i))
                        {
                            arrayPush(newClientOrderIds, add(add(std::string("%22"), ::getValue(origclientorderidlist, i)), std::string("%22")));
                        }
                        query = add(add(add(add(query, std::string("&")), std::string("origclientorderidlist=%5B")), join(newClientOrderIds, std::string("%2C"))), std::string("%5D"));
                    }
                } else
                {
                    query = this->rawencode(extendedParams);
                }
            } else
            {
                query = this->urlencode(extendedParams);
            }
            std::any signature = std::any{};
            if (isTrue(isGreaterThan(getIndexOf(this->secret, std::string("PRIVATE KEY")), -1)))
            {
                if (isTrue(isGreaterThan(getStringLength(this->secret), 120)))
                {
                    signature = this->encodeURIComponent(rsa(query, this->secret, sha256));
                } else
                {
                    signature = this->encodeURIComponent(eddsa(this->encode(query), this->secret, ed25519));
                }
            } else
            {
                signature = this->hmac(this->encode(query), this->encode(this->secret), sha256);
            }
            query = add(query, add(add(std::string("&"), std::string("signature=")), signature));
            headers = ccxt::dict {
                { std::string("X-MBX-APIKEY"), this->apiKey },
            };
            if (isTrue(isTrue((isEqual(method, std::string("GET")))) || isTrue((isEqual(method, std::string("DELETE"))))))
            {
                url = add(url, add(std::string("?"), query));
            } else
            {
                body = query;
                ::setValue(headers, std::string("Content-Type"), std::string("application/x-www-form-urlencoded"));
            }
        } else
        {
            if (isTrue(isGreaterThan(getArrayLength(getObjectKeys(params)), 0)))
            {
                url = add(url, add(std::string("?"), this->urlencode(params)));
            }
        }
        return ccxt::dict {
            { std::string("url"), url },
            { std::string("method"), method },
            { std::string("body"), body },
            { std::string("headers"), headers },
        };
    }

    virtual std::any getExceptionsByUrl(std::any url, std::any exactOrBroad)
    {
        if (isTrue(isEqual(url, std::any{})))
        {
            return ccxt::dict {};
        }
        std::any marketType = std::any{};
        std::any hostname = (isTrue((!isEqual(this->hostname, std::any{}))) ? std::any(this->hostname) : std::any(std::string("binance.com")));
        if (isTrue(isTrue(isTrue(startsWith(url, add(add(std::string("https://api."), hostname), std::string("/")))) || isTrue(startsWith(url, std::string("https://demo-api")))) || isTrue(startsWith(url, std::string("https://testnet.binance.vision")))))
        {
            marketType = std::string("spot");
        } else if (isTrue(isTrue(isTrue(startsWith(url, add(add(std::string("https://dapi."), hostname), std::string("/")))) || isTrue(startsWith(url, std::string("https://demo-dapi")))) || isTrue(startsWith(url, std::string("https://testnet.binancefuture.com/dapi")))))
        {
            marketType = std::string("inverse");
        } else if (isTrue(isTrue(isTrue(startsWith(url, add(add(std::string("https://fapi."), hostname), std::string("/")))) || isTrue(startsWith(url, std::string("https://demo-fapi")))) || isTrue(startsWith(url, std::string("https://testnet.binancefuture.com/fapi")))))
        {
            marketType = std::string("linear");
        } else if (isTrue(startsWith(url, add(add(std::string("https://eapi."), hostname), std::string("/")))))
        {
            marketType = std::string("option");
        } else if (isTrue(startsWith(url, add(add(std::string("https://papi."), hostname), std::string("/")))))
        {
            marketType = std::string("portfolioMargin");
        }
        if (isTrue(!isEqual(marketType, std::any{})))
        {
            std::any exceptionsForMarketType = this->safeDict(this->exceptions, marketType, ccxt::dict {});
            return this->safeDict(exceptionsForMarketType, exactOrBroad, ccxt::dict {});
        }
        return ccxt::dict {};
    }

    std::any handleErrors(std::any code, std::any reason, std::any url, std::any method, std::any headers, std::any body, std::any response, std::any requestHeaders, std::any requestBody) override
    {
        if (isTrue(isTrue((isEqual(code, 418))) || isTrue((isEqual(code, 429)))))
        {
            throw DDoSProtection(toString(add(add(add(add(add(add(this->id, std::string(" ")), toString(code)), std::string(" ")), reason), std::string(" ")), body)));
        }
        // error response in a form: { "code": -1013, "msg": "Invalid quantity." }
        // following block contains legacy checks against message patterns in "msg" property
        // will switch "code" checks eventually, when we know all of them
        if (isTrue(isTrue((isGreaterThanOrEqual(code, 400))) && isTrue((!isEqual(body, std::any{})))))
        {
            if (isTrue(isGreaterThanOrEqual(getIndexOf(body, std::string("Price * QTY is zero or less")), 0)))
            {
                throw InvalidOrder(toString(add(add(this->id, std::string(" order cost = amount * price is zero or less ")), body)));
            }
            if (isTrue(isGreaterThanOrEqual(getIndexOf(body, std::string("LOT_SIZE")), 0)))
            {
                throw InvalidOrder(toString(add(add(this->id, std::string(" order amount should be evenly divisible by lot size ")), body)));
            }
            if (isTrue(isGreaterThanOrEqual(getIndexOf(body, std::string("PRICE_FILTER")), 0)))
            {
                throw InvalidOrder(toString(add(add(this->id, std::string(" order price is invalid, i.e. exceeds allowed price precision, exceeds min price or max price limits or is invalid value in general, use this.priceToPrecision (symbol, amount) ")), body)));
            }
        }
        if (isTrue(isEqual(response, std::any{})))
        {
            return std::any{};  // fallback to default error handler
        }
        // response in format {'msg': 'The coin does not exist.', 'success': true/false}
        std::any success = this->safeBool(response, std::string("success"), true);
        if (isTrue(!isEqual(success, true)))
        {
            std::any messageNew = this->safeString(response, std::string("msg"));
            std::any parsedMessage = std::any{};
            if (isTrue(!isEqual(messageNew, std::any{})))
            {
                try
                {
                    parsedMessage = parseJson(messageNew);
                } catch(const std::exception& e)
                {
                    // do nothing
                    parsedMessage = std::any{};
                }
                if (isTrue(!isEqual(parsedMessage, std::any{})))
                {
                    response = parsedMessage;
                }
            }
        }
        std::any message = this->safeString(response, std::string("msg"));
        if (isTrue(!isEqual(message, std::any{})))
        {
            this->throwExactlyMatchedException(this->getExceptionsByUrl(url, std::string("exact")), message, add(add(this->id, std::string(" ")), message));
            this->throwExactlyMatchedException(::getValue(this->exceptions, std::string("exact")), message, add(add(this->id, std::string(" ")), message));
            this->throwBroadlyMatchedException(this->getExceptionsByUrl(url, std::string("broad")), message, add(add(this->id, std::string(" ")), message));
            this->throwBroadlyMatchedException(::getValue(this->exceptions, std::string("broad")), message, add(add(this->id, std::string(" ")), message));
        }
        // checks against error codes
        std::any error = this->safeString(response, std::string("code"));
        if (isTrue(!isEqual(error, std::any{})))
        {
            // https://github.com/ccxt/ccxt/issues/6501
            // https://github.com/ccxt/ccxt/issues/7742
            if (isTrue(isTrue((isEqual(error, std::string("200")))) || isTrue(ccxt::Precise::stringEquals(error, std::string("0")))))
            {
                return std::any{};
            }
            // a workaround for {"code":-2015,"msg":"Invalid API-key, IP, or permissions for action."}
            // despite that their message is very confusing, it is raised by Binance
            // on a temporary ban, the API key is valid, but disabled for a while
            if (isTrue(isTrue((isEqual(error, std::string("-2015")))) && isTrue((isEqual(::getValue(this->options, std::string("hasAlreadyAuthenticatedSuccessfully")), true)))))
            {
                throw DDoSProtection(toString(add(add(this->id, std::string(" ")), body)));
            }
            std::any feedback = add(add(this->id, std::string(" ")), body);
            if (isTrue(isEqual(message, std::string("No need to change margin type."))))
            {
                throw MarginModeAlreadySet(toString(feedback));
            }
            this->throwExactlyMatchedException(this->getExceptionsByUrl(url, std::string("exact")), error, feedback);
            this->throwExactlyMatchedException(::getValue(this->exceptions, std::string("exact")), error, feedback);
            throw ExchangeError(toString(feedback));
        }
        if (isTrue(!isEqual(success, true)))
        {
            throw ExchangeError(toString(add(add(this->id, std::string(" ")), body)));
        }
        if (isTrue(isArray(response)))
        {
            // cancelOrders returns an array like this: [{"code":-2011,"msg":"Unknown order sent."}]
            std::any arrayLength = getArrayLength(response);
            if (isTrue(isEqual(arrayLength, 1)))
            {
                std::any element = ::getValue(response, 0);
                std::any errorCode = this->safeString(element, std::string("code"));
                if (isTrue(!isEqual(errorCode, std::any{})))
                {
                    this->throwExactlyMatchedException(this->getExceptionsByUrl(url, std::string("exact")), errorCode, add(add(this->id, std::string(" ")), body));
                    this->throwExactlyMatchedException(::getValue(this->exceptions, std::string("exact")), errorCode, add(add(this->id, std::string(" ")), body));
                }
            }
        }
        return std::any{};
    }

    std::any calculateRateLimiterCost(std::any api, std::any method, std::any path, std::any params, std::any config = ccxt::dict {}) override
    {
        if (isTrue(isTrue((inOp(config, std::string("noCoin")))) && !isTrue((inOp(params, std::string("coin"))))))
        {
            return ::getValue(config, std::string("noCoin"));
        } else if (isTrue(isTrue((inOp(config, std::string("noSymbol")))) && !isTrue((inOp(params, std::string("symbol"))))))
        {
            return ::getValue(config, std::string("noSymbol"));
        } else if (isTrue(isTrue((inOp(config, std::string("noPoolId")))) && !isTrue((inOp(params, std::string("poolId"))))))
        {
            return ::getValue(config, std::string("noPoolId"));
        } else if (isTrue(isTrue((inOp(config, std::string("byLimit")))) && isTrue((inOp(params, std::string("limit"))))))
        {
            std::any limit = ::getValue(params, std::string("limit"));
            // safeValue keeps runtime identical to the prior bare index (no empty-array default)
            std::any byLimit = this->safeValue(config, std::string("byLimit"));
            for (std::any i = 0; isLessThan(i, getArrayLength(byLimit)); postFixIncrement(i))
            {
                std::any entry = ::getValue(byLimit, i);
                if (isTrue(isLessThanOrEqual(limit, ::getValue(entry, 0))))
                {
                    return ::getValue(entry, 1);
                }
            }
        }
        return this->safeValue(config, std::string("cost"), 1);
    }

    std::shared_future<std::any> request(std::any path, std::any api = std::string("public"), std::any method = std::string("GET"), std::any params = ccxt::dict {}, std::any headers = std::any{}, std::any body = std::any{}, std::any config = ccxt::dict {}) override
    {
        return std::async(std::launch::deferred, [=]() mutable -> std::any {
            std::any response = awaitValue(this->fetch2(path, api, method, params, headers, body, config));
            // a workaround for {"code":-2015,"msg":"Invalid API-key, IP, or permissions for action."}
            if (isTrue(isEqual(api, std::string("private"))))
            {
                ::setValue(this->options, std::string("hasAlreadyAuthenticatedSuccessfully"), true);
            }
            return response;
        }).share();
    }

    virtual std::shared_future<std::any> modifyMarginHelper(std::any symbol, std::any amount, std::any addOrReduce, std::any params = ccxt::dict {})
    {
        return std::async(std::launch::deferred, [=]() mutable -> std::any {
            // used to modify isolated positions
            std::any defaultType = this->safeString(this->options, std::string("defaultType"), std::string("future"));
            if (isTrue(isEqual(defaultType, std::string("spot"))))
            {
                defaultType = std::string("future");
            }
            std::any type = this->safeString(params, std::string("type"), defaultType);
            if (isTrue(isTrue((isEqual(type, std::string("margin")))) || isTrue((isEqual(type, std::string("spot"))))))
            {
                throw NotSupported(toString(add(this->id, std::string(" add / reduce margin only supported with type future or delivery"))));
            }
            if (isTrue(isEqual(this->markets, std::any{})))
            {
                awaitValue(this->loadMarkets());
            }
            std::any market = this->market(symbol);
            amount = this->amountToPrecision(symbol, amount);
            std::any request = ccxt::dict {
                { std::string("type"), addOrReduce },
                { std::string("symbol"), ::getValue(market, std::string("id")) },
                { std::string("amount"), amount },
            };
            std::any response = std::any{};
            std::any code = std::any{};
            if (isTrue(isEqual(::getValue(market, std::string("linear")), true)))
            {
                code = ::getValue(market, std::string("quote"));
                response = awaitValue(this->fapiPrivatePostPositionMargin(this->extend(request, params)));
            } else
            {
                code = ::getValue(market, std::string("base"));
                response = awaitValue(this->dapiPrivatePostPositionMargin(this->extend(request, params)));
            }
            //
            //     {
            //         "code": 200,
            //         "msg": "Successfully modify position margin.",
            //         "amount": 0.001,
            //         "type": 1
            //     }
            //
            if (isTrue(isEqual(response, std::any{})))
            {
                throw NullResponse(toString(add(this->id, std::string(" parseMarginModification() returned empty response"))));
            }
            return this->extend(this->parseMarginModification(response, market), ccxt::dict {
                { std::string("code"), code },
            });
        }).share();
    }

    std::any parseMarginModification(std::any data, std::any market = std::any{}) override
    {
        //
        // add/reduce margin
        //
        //     {
        //         "code": 200,
        //         "msg": "Successfully modify position margin.",
        //         "amount": 0.001,
        //         "type": 1
        //     }
        //
        // fetchMarginAdjustmentHistory
        //
        //    {
        //        symbol: "XRPUSDT",
        //        type: "1",
        //        deltaType: "TRADE",
        //        amount: "2.57148240",
        //        asset: "USDT",
        //        time: "1711046271555",
        //        positionSide: "BOTH",
        //        clientTranId: ""
        //    }
        //
        std::any rawType = this->safeInteger(data, std::string("type"));
        std::any errorCode = this->safeString(data, std::string("code"));
        std::any marketId = this->safeString(data, std::string("symbol"));
        std::any timestamp = this->safeInteger(data, std::string("time"));
        market = this->safeMarket(marketId, market, std::any{}, std::string("swap"));
        std::any noErrorCode = isEqual(errorCode, std::any{});
        std::any success = isEqual(errorCode, std::string("200"));
        return ccxt::dict {
            { std::string("info"), data },
            { std::string("symbol"), ::getValue(market, std::string("symbol")) },
            { std::string("type"), (isTrue((isEqual(rawType, 1))) ? std::any(std::string("add")) : std::any(std::string("reduce"))) },
            { std::string("marginMode"), std::string("isolated") },
            { std::string("amount"), this->safeNumber(data, std::string("amount")) },
            { std::string("code"), this->safeString(data, std::string("asset")) },
            { std::string("total"), std::any{} },
            { std::string("status"), (isTrue((isTrue(success) || isTrue(noErrorCode))) ? std::any(std::string("ok")) : std::any(std::string("failed"))) },
            { std::string("timestamp"), timestamp },
            { std::string("datetime"), this->iso8601(timestamp) },
        };
    }

    /**
     * @method
     * @name binance#reduceMargin
     * @description remove margin from a position
     * @see https://developers.binance.com/docs/derivatives/usds-margined-futures/trade/rest-api/Modify-Isolated-Position-Margin
     * @see https://developers.binance.com/docs/derivatives/coin-margined-futures/trade/rest-api/Modify-Isolated-Position-Margin
     * @param {string} symbol unified market symbol
     * @param {float} amount the amount of margin to remove
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} a [margin structure]{@link https://docs.ccxt.com/?id=margin-structure}
     */
    std::shared_future<std::any> reduceMargin(std::any symbol, std::any amount, std::any params = ccxt::dict {}) override
    {
        return std::async(std::launch::deferred, [=]() mutable -> std::any {
            return awaitValue(this->modifyMarginHelper(symbol, amount, 2, params));
        }).share();
    }

    /**
     * @method
     * @name binance#addMargin
     * @description add margin
     * @see https://developers.binance.com/docs/derivatives/usds-margined-futures/trade/rest-api/Modify-Isolated-Position-Margin
     * @see https://developers.binance.com/docs/derivatives/coin-margined-futures/trade/rest-api/Modify-Isolated-Position-Margin
     * @param {string} symbol unified market symbol
     * @param {float} amount amount of margin to add
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} a [margin structure]{@link https://docs.ccxt.com/?id=margin-structure}
     */
    std::shared_future<std::any> addMargin(std::any symbol, std::any amount, std::any params = ccxt::dict {}) override
    {
        return std::async(std::launch::deferred, [=]() mutable -> std::any {
            return awaitValue(this->modifyMarginHelper(symbol, amount, 1, params));
        }).share();
    }

    /**
     * @method
     * @name binance#fetchCrossBorrowRate
     * @description fetch the rate of interest to borrow a currency for margin trading
     * @see https://developers.binance.com/docs/margin_trading/borrow-and-repay/Query-Margin-Interest-Rate-History
     * @param {string} code unified currency code
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} a [borrow rate structure]{@link https://docs.ccxt.com/?id=borrow-rate-structure}
     */
    std::shared_future<std::any> fetchCrossBorrowRate(std::any code, std::any params = ccxt::dict {}) override
    {
        return std::async(std::launch::deferred, [=]() mutable -> std::any {
            if (isTrue(isEqual(this->markets, std::any{})))
            {
                awaitValue(this->loadMarkets());
            }
            std::any currency = this->currency(code);
            std::any request = ccxt::dict {
                { std::string("asset"), ::getValue(currency, std::string("id")) },
            };
            std::any response = awaitValue(this->sapiGetMarginInterestRateHistory(this->extend(request, params)));
            //
            //     [
            //         {
            //             "asset": "USDT",
            //             "timestamp": 1638230400000,
            //             "dailyInterestRate": "0.0006",
            //             "vipLevel": 0
            //         },
            //     ]
            //
            std::any rate = this->safeDict(response, 0);
            return this->parseBorrowRate(rate);
        }).share();
    }

    /**
     * @method
     * @name binance#fetchIsolatedBorrowRate
     * @description fetch the rate of interest to borrow a currency for margin trading
     * @see https://developers.binance.com/docs/margin_trading/account/Query-Isolated-Margin-Fee-Data
     * @param {string} symbol unified market symbol
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     *
     * EXCHANGE SPECIFIC PARAMETERS
     * @param {object} [params.vipLevel] user's current specific margin data will be returned if viplevel is omitted
     * @returns {object} an [isolated borrow rate structure]{@link https://docs.ccxt.com/?id=isolated-borrow-rate-structure}
     */
    std::shared_future<std::any> fetchIsolatedBorrowRate(std::any symbol, std::any params = ccxt::dict {}) override
    {
        return std::async(std::launch::deferred, [=]() mutable -> std::any {
            std::any request = ccxt::dict {
                { std::string("symbol"), symbol },
            };
            std::any borrowRates = awaitValue(this->fetchIsolatedBorrowRates(this->extend(request, params)));
            return this->safeDict(borrowRates, symbol);
        }).share();
    }

    /**
     * @method
     * @name binance#fetchIsolatedBorrowRates
     * @description fetch the borrow interest rates of all currencies
     * @see https://developers.binance.com/docs/margin_trading/account/Query-Isolated-Margin-Fee-Data
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {object} [params.symbol] unified market symbol
     *
     * EXCHANGE SPECIFIC PARAMETERS
     * @param {object} [params.vipLevel] user's current specific margin data will be returned if viplevel is omitted
     * @returns {object} a [borrow rate structure]{@link https://docs.ccxt.com/?id=borrow-rate-structure}
     */
    std::shared_future<std::any> fetchIsolatedBorrowRates(std::any params = ccxt::dict {}) override
    {
        return std::async(std::launch::deferred, [=]() mutable -> std::any {
            if (isTrue(isEqual(this->markets, std::any{})))
            {
                awaitValue(this->loadMarkets());
            }
            std::any request = ccxt::dict {};
            std::any symbol = this->safeString(params, std::string("symbol"));
            params = this->omit(params, std::string("symbol"));
            if (isTrue(!isEqual(symbol, std::any{})))
            {
                std::any market = this->market(symbol);
                ::setValue(request, std::string("symbol"), ::getValue(market, std::string("id")));
            }
            std::any response = awaitValue(this->sapiGetMarginIsolatedMarginData(this->extend(request, params)));
            //
            //    [
            //        {
            //            "vipLevel": 0,
            //            "symbol": "BTCUSDT",
            //            "leverage": "10",
            //            "data": [
            //                {
            //                    "coin": "BTC",
            //                    "dailyInterest": "0.00026125",
            //                    "borrowLimit": "270"
            //                },
            //                {
            //                    "coin": "USDT",
            //                    "dailyInterest": "0.000475",
            //                    "borrowLimit": "2100000"
            //                }
            //            ]
            //        }
            //    ]
            //
            return this->parseIsolatedBorrowRates(response);
        }).share();
    }

    /**
     * @method
     * @name binance#fetchBorrowRateHistory
     * @description retrieves a history of a currencies borrow interest rate at specific time slots
     * @see https://developers.binance.com/docs/margin_trading/borrow-and-repay/Query-Margin-Interest-Rate-History
     * @param {string} code unified currency code
     * @param {int} [since] timestamp for the earliest borrow rate
     * @param {int} [limit] the maximum number of [borrow rate structures]{@link https://docs.ccxt.com/?id=borrow-rate-structure} to retrieve
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object[]} an array of [borrow rate structures]{@link https://docs.ccxt.com/?id=borrow-rate-structure}
     */
    virtual std::shared_future<std::any> fetchBorrowRateHistory(std::any code, std::any since = std::any{}, std::any limit = std::any{}, std::any params = ccxt::dict {})
    {
        return std::async(std::launch::deferred, [=]() mutable -> std::any {
            if (isTrue(isEqual(this->markets, std::any{})))
            {
                awaitValue(this->loadMarkets());
            }
            if (isTrue(isEqual(limit, std::any{})))
            {
                limit = 93;
            } else if (isTrue(isGreaterThan(limit, 93)))
            {
                throw BadRequest(toString(add(this->id, std::string(" fetchBorrowRateHistory() limit parameter cannot exceed 92"))));
            }
            std::any currency = this->currency(code);
            std::any request = ccxt::dict {
                { std::string("asset"), ::getValue(currency, std::string("id")) },
                { std::string("limit"), limit },
            };
            if (isTrue(!isEqual(since, std::any{})))
            {
                ::setValue(request, std::string("startTime"), since);
                std::any endTime = subtract(this->sum(since, multiply(limit, 86400000)), 1); // required when startTime is further than 93 days in the past
                std::any now = this->milliseconds();
                ::setValue(request, std::string("endTime"), mathMin(endTime, now)); // cannot have an endTime later than current time
            }
            std::any response = awaitValue(this->sapiGetMarginInterestRateHistory(this->extend(request, params)));
            //
            //     [
            //         {
            //             "asset": "USDT",
            //             "timestamp": 1638230400000,
            //             "dailyInterestRate": "0.0006",
            //             "vipLevel": 0
            //         },
            //     ]
            //
            return this->parseBorrowRateHistory(response, code, since, limit);
        }).share();
    }

    std::any parseBorrowRate(std::any info, std::any currency = std::any{}) override
    {
        //
        //    {
        //        "asset": "USDT",
        //        "timestamp": 1638230400000,
        //        "dailyInterestRate": "0.0006",
        //        "vipLevel": 0
        //    }
        //
        std::any timestamp = this->safeInteger(info, std::string("timestamp"));
        std::any currencyId = this->safeString(info, std::string("asset"));
        return ccxt::dict {
            { std::string("currency"), this->safeCurrencyCode(currencyId, currency) },
            { std::string("rate"), this->safeNumber(info, std::string("dailyInterestRate")) },
            { std::string("period"), 86400000 },
            { std::string("timestamp"), timestamp },
            { std::string("datetime"), this->iso8601(timestamp) },
            { std::string("info"), info },
        };
    }

    std::any parseIsolatedBorrowRate(std::any info, std::any market = std::any{}) override
    {
        //
        //    {
        //        "vipLevel": 0,
        //        "symbol": "BTCUSDT",
        //        "leverage": "10",
        //        "data": [
        //            {
        //                "coin": "BTC",
        //                "dailyInterest": "0.00026125",
        //                "borrowLimit": "270"
        //            },
        //            {
        //                "coin": "USDT",
        //                "dailyInterest": "0.000475",
        //                "borrowLimit": "2100000"
        //            }
        //        ]
        //    }
        //
        std::any marketId = this->safeString(info, std::string("symbol"));
        market = this->safeMarket(marketId, market, std::any{}, std::string("spot"));
        std::any data = this->safeList(info, std::string("data"));
        std::any baseInfo = this->safeDict(data, 0);
        std::any quoteInfo = this->safeDict(data, 1);
        return ccxt::dict {
            { std::string("info"), info },
            { std::string("symbol"), this->safeString(market, std::string("symbol")) },
            { std::string("base"), this->safeString(baseInfo, std::string("coin")) },
            { std::string("baseRate"), this->safeNumber(baseInfo, std::string("dailyInterest")) },
            { std::string("quote"), this->safeString(quoteInfo, std::string("coin")) },
            { std::string("quoteRate"), this->safeNumber(quoteInfo, std::string("dailyInterest")) },
            { std::string("period"), 86400000 },
            { std::string("timestamp"), std::any{} },
            { std::string("datetime"), std::any{} },
        };
    }

    /**
     * @method
     * @name binance#createGiftCode
     * @description create gift code
     * @see https://developers.binance.com/docs/gift_card/market-data/Create-a-single-token-gift-card
     * @param {string} code gift code
     * @param {float} amount amount of currency for the gift
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} The gift code id, code, currency and amount
     */
    virtual std::shared_future<std::any> createGiftCode(std::any code, std::any amount, std::any params = ccxt::dict {})
    {
        return std::async(std::launch::deferred, [=]() mutable -> std::any {
            if (isTrue(isEqual(this->markets, std::any{})))
            {
                awaitValue(this->loadMarkets());
            }
            std::any currency = this->currency(code);
            // ensure you have enough token in your funding account before calling this code
            std::any request = ccxt::dict {
                { std::string("token"), ::getValue(currency, std::string("id")) },
                { std::string("amount"), amount },
            };
            std::any response = awaitValue(this->sapiPostGiftcardCreateCode(this->extend(request, params)));
            //
            //     {
            //         "code": "000000",
            //         "message": "success",
            //         "data": { referenceNo: "0033002404219823", code: "AP6EXTLKNHM6CEX7" },
            //         "success": true
            //     }
            //
            std::any data = this->safeDict(response, std::string("data"));
            std::any giftcardCode = this->safeString(data, std::string("code"));
            std::any id = this->safeString(data, std::string("referenceNo"));
            return ccxt::dict {
                { std::string("info"), response },
                { std::string("id"), id },
                { std::string("code"), giftcardCode },
                { std::string("currency"), code },
                { std::string("amount"), amount },
            };
        }).share();
    }

