    /**
     * @method
     * @name binance#fetchBorrowInterest
     * @description fetch the interest owed by the user for borrowing currency for margin trading
     * @see https://developers.binance.com/docs/margin_trading/borrow-and-repay/Get-Interest-History
     * @see https://developers.binance.com/docs/derivatives/portfolio-margin/account/Get-Margin-BorrowLoan-Interest-History
     * @param {string} [code] unified currency code
     * @param {string} [symbol] unified market symbol when fetch interest in isolated markets
     * @param {int} [since] the earliest time in ms to fetch borrrow interest for
     * @param {int} [limit] the maximum number of structures to retrieve
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {boolean} [params.portfolioMargin] set to true if you would like to fetch the borrow interest in a portfolio margin account
     * @returns {object[]} a list of [borrow interest structures]{@link https://docs.ccxt.com/?id=borrow-interest-structure}
     */
    std::shared_future<std::any> fetchBorrowInterest(std::any code = std::any{}, std::any symbol = std::any{}, std::any since = std::any{}, std::any limit = std::any{}, std::any params = ccxt::dict {}) override
    {
        return std::async(std::launch::deferred, [=]() mutable -> std::any {
            if (isTrue(isEqual(this->markets, std::any{})))
            {
                awaitValue(this->loadMarkets());
            }
            std::any isPortfolioMargin = std::any{};
            std::any isPortfolioMarginparamsVariable = this->handleOptionAndParams2(params, std::string("fetchBorrowInterest"), std::string("papi"), std::string("portfolioMargin"), false);
            isPortfolioMargin = ::getValue(isPortfolioMarginparamsVariable, 0);
            params = ::getValue(isPortfolioMarginparamsVariable, 1);
            std::any request = ccxt::dict {};
            std::any market = std::any{};
            if (isTrue(!isEqual(code, std::any{})))
            {
                std::any currency = this->currency(code);
                ::setValue(request, std::string("asset"), ::getValue(currency, std::string("id")));
            }
            if (isTrue(!isEqual(since, std::any{})))
            {
                ::setValue(request, std::string("startTime"), since);
            }
            if (isTrue(!isEqual(limit, std::any{})))
            {
                ::setValue(request, std::string("size"), limit);
            }
            std::any requestparamsVariable = this->handleUntilOption(std::string("endTime"), request, params);
            request = ::getValue(requestparamsVariable, 0);
            params = ::getValue(requestparamsVariable, 1);
            std::any response = std::any{};
            if (isTrue(isPortfolioMargin))
            {
                response = awaitValue(this->papiGetMarginMarginInterestHistory(this->extend(request, params)));
            } else
            {
                if (isTrue(!isEqual(symbol, std::any{})))
                {
                    market = this->market(symbol);
                    ::setValue(request, std::string("isolatedSymbol"), ::getValue(market, std::string("id")));
                }
                response = awaitValue(this->sapiGetMarginInterestHistory(this->extend(request, params)));
            }
            //
            // spot margin
            //
            //     {
            //         "rows":[
            //             {
            //                 "isolatedSymbol": "BNBUSDT", // isolated symbol, will not be returned for crossed margin
            //                 "asset": "BNB",
            //                 "interest": "0.02414667",
            //                 "interestAccuredTime": 1566813600000,
            //                 "interestRate": "0.01600000",
            //                 "principal": "36.22000000",
            //                 "type": "ON_BORROW"
            //             }
            //         ],
            //         "total": 1
            //     }
            //
            // spot margin portfolio margin
            //
            //     {
            //         "total": 49,
            //         "rows": [
            //             {
            //                 "txId": 1656187724899910076,
            //                 "interestAccuredTime": 1707541200000,
            //                 "asset": "USDT",
            //                 "rawAsset": "USDT",
            //                 "principal": "0.00011146",
            //                 "interest": "0.00000001",
            //                 "interestRate": "0.00089489",
            //                 "type": "PERIODIC"
            //             },
            //         ]
            //     }
            //
            std::any rows = this->safeList(response, std::string("rows"));
            std::any interest = this->parseBorrowInterests(rows, market);
            return this->filterByCurrencySinceLimit(interest, code, since, limit);
        }).share();
    }

    std::any parseBorrowInterest(std::any info, std::any market = std::any{}) override
    {
        std::any symbol = this->safeString(info, std::string("isolatedSymbol"));
        std::any timestamp = this->safeInteger(info, std::string("interestAccuredTime"));
        std::any marginMode = (isTrue((isEqual(symbol, std::any{}))) ? std::any(std::string("cross")) : std::any(std::string("isolated")));
        return ccxt::dict {
            { std::string("info"), info },
            { std::string("symbol"), symbol },
            { std::string("currency"), this->safeCurrencyCode(this->safeString(info, std::string("asset"))) },
            { std::string("interest"), this->safeNumber(info, std::string("interest")) },
            { std::string("interestRate"), this->safeNumber(info, std::string("interestRate")) },
            { std::string("amountBorrowed"), this->safeNumber(info, std::string("principal")) },
            { std::string("marginMode"), marginMode },
            { std::string("timestamp"), timestamp },
            { std::string("datetime"), this->iso8601(timestamp) },
        };
    }

    /**
     * @method
     * @name binance#repayCrossMargin
     * @description repay borrowed margin and interest
     * @see https://developers.binance.com/docs/derivatives/portfolio-margin/trade/Margin-Account-Repay
     * @see https://developers.binance.com/docs/margin_trading/borrow-and-repay/Margin-Account-Borrow-Repay
     * @see https://developers.binance.com/docs/derivatives/portfolio-margin/trade/Margin-Account-Repay-Debt
     * @param {string} code unified currency code of the currency to repay
     * @param {float} amount the amount to repay
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {boolean} [params.portfolioMargin] set to true if you would like to repay margin in a portfolio margin account
     * @param {string} [params.repayCrossMarginMethod] *portfolio margin only* 'papiPostRepayLoan' (default), 'papiPostMarginRepayDebt' (alternative)
     * @param {string} [params.specifyRepayAssets] *portfolio margin papiPostMarginRepayDebt only* specific asset list to repay debt
     * @returns {object} a [margin loan structure]{@link https://docs.ccxt.com/?id=margin-loan-structure}
     */
    std::shared_future<std::any> repayCrossMargin(std::any code, std::any amount, std::any params = ccxt::dict {}) override
    {
        return std::async(std::launch::deferred, [=]() mutable -> std::any {
            if (isTrue(isEqual(this->markets, std::any{})))
            {
                awaitValue(this->loadMarkets());
            }
            std::any currency = this->currency(code);
            std::any request = ccxt::dict {
                { std::string("asset"), ::getValue(currency, std::string("id")) },
                { std::string("amount"), this->currencyToPrecision(code, amount) },
            };
            std::any response = std::any{};
            std::any isPortfolioMargin = std::any{};
            std::any isPortfolioMarginparamsVariable = this->handleOptionAndParams2(params, std::string("repayCrossMargin"), std::string("papi"), std::string("portfolioMargin"), false);
            isPortfolioMargin = ::getValue(isPortfolioMarginparamsVariable, 0);
            params = ::getValue(isPortfolioMarginparamsVariable, 1);
            if (isTrue(isPortfolioMargin))
            {
                std::any method = std::any{};
                std::any methodparamsVariable = this->handleOptionAndParams2(params, std::string("repayCrossMargin"), std::string("repayCrossMarginMethod"), std::string("method"));
                method = ::getValue(methodparamsVariable, 0);
                params = ::getValue(methodparamsVariable, 1);
                if (isTrue(isEqual(method, std::string("papiPostMarginRepayDebt"))))
                {
                    response = awaitValue(this->papiPostMarginRepayDebt(this->extend(request, params)));
                } else
                {
                    response = awaitValue(this->papiPostRepayLoan(this->extend(request, params)));
                }
            } else
            {
                ::setValue(request, std::string("isIsolated"), std::string("FALSE"));
                ::setValue(request, std::string("type"), std::string("REPAY"));
                response = awaitValue(this->sapiPostMarginBorrowRepay(this->extend(request, params)));
            }
            return this->parseMarginLoan(response, currency);
        }).share();
    }

