    virtual std::any parseMarginLoan(std::any info, std::any currency = std::any{})
    {
        //
        //     {
        //         "tranId": 108988250265,
        //         "clientTag":""
        //     }
        //
        // repayCrossMargin alternative endpoint
        //
        //     {
        //         "asset": "USDC",
        //         "amount": 10,
        //         "specifyRepayAssets": null,
        //         "updateTime": 1727170761267,
        //         "success": true
        //     }
        //
        std::any currencyId = this->safeString(info, std::string("asset"));
        std::any timestamp = this->safeInteger(info, std::string("updateTime"));
        return ccxt::dict {
            { std::string("id"), this->safeString(info, std::string("tranId")) },
            { std::string("currency"), this->safeCurrencyCode(currencyId, currency) },
            { std::string("amount"), this->safeNumber(info, std::string("amount")) },
            { std::string("symbol"), std::any{} },
            { std::string("timestamp"), timestamp },
            { std::string("datetime"), this->iso8601(timestamp) },
            { std::string("info"), info },
        };
    }

    /**
     * @method
     * @name binance#fetchOpenInterestHistory
     * @description Retrieves the open interest history of a currency
     * @see https://developers.binance.com/docs/derivatives/usds-margined-futures/market-data/rest-api/Open-Interest-Statistics
     * @see https://developers.binance.com/docs/derivatives/coin-margined-futures/market-data/rest-api/Open-Interest-Statistics
     * @param {string} symbol Unified CCXT market symbol
     * @param {string} timeframe "5m","15m","30m","1h","2h","4h","6h","12h", or "1d"
     * @param {int} [since] the time(ms) of the earliest record to retrieve as a unix timestamp
     * @param {int} [limit] default 30, max 500
     * @param {object} [params] exchange specific parameters
     * @param {int} [params.until] the time(ms) of the latest record to retrieve as a unix timestamp
     * @param {boolean} [params.paginate] default false, when true will automatically paginate by calling this endpoint multiple times. See in the docs all the [availble parameters](https://github.com/ccxt/ccxt/wiki/Manual#pagination-params)
     * @returns {object} an array of [open interest structure]{@link https://docs.ccxt.com/?id=open-interest-structure}
     */
    std::shared_future<std::any> fetchOpenInterestHistory(std::any symbol, std::any timeframe = std::string("5m"), std::any since = std::any{}, std::any limit = std::any{}, std::any params = ccxt::dict {}) override
    {
        return std::async(std::launch::deferred, [=]() mutable -> std::any {
            if (isTrue(isEqual(timeframe, std::string("1m"))))
            {
                throw BadRequest(toString(add(this->id, std::string(" fetchOpenInterestHistory cannot use the 1m timeframe"))));
            }
            if (isTrue(isEqual(this->markets, std::any{})))
            {
                awaitValue(this->loadMarkets());
            }
            std::any paginate = false;
            std::any paginateparamsVariable = this->handleOptionAndParams(params, std::string("fetchOpenInterestHistory"), std::string("paginate"), false);
            paginate = ::getValue(paginateparamsVariable, 0);
            params = ::getValue(paginateparamsVariable, 1);
            if (isTrue(paginate))
            {
                return awaitValue(this->fetchPaginatedCallDeterministic(std::string("fetchOpenInterestHistory"), symbol, since, limit, timeframe, params, 500));
            }
            std::any market = this->market(symbol);
            std::any request = ccxt::dict {
                { std::string("period"), this->safeString(this->timeframes, timeframe, timeframe) },
            };
            if (isTrue(!isEqual(limit, std::any{})))
            {
                ::setValue(request, std::string("limit"), limit);
            }
            std::any symbolKey = (isTrue((isEqual(::getValue(market, std::string("linear")), true))) ? std::any(std::string("symbol")) : std::any(std::string("pair")));
            ::setValue(request, symbolKey, ::getValue(market, std::string("id")));
            if (isTrue(isEqual(::getValue(market, std::string("inverse")), true)))
            {
                ::setValue(request, std::string("contractType"), this->safeString(params, std::string("contractType"), std::string("CURRENT_QUARTER")));
            }
            if (isTrue(!isEqual(since, std::any{})))
            {
                ::setValue(request, std::string("startTime"), since);
            }
            std::any until = this->safeInteger(params, std::string("until")); // unified in milliseconds
            std::any endTime = this->safeInteger(params, std::string("endTime"), until); // exchange-specific in milliseconds
            params = this->omit(params, ccxt::list{std::string("endTime"), std::string("until")});
            if (isTrue(isTrue((!isEqual(endTime, std::any{}))) && isTrue((!isEqual(endTime, 0)))))
            {
                ::setValue(request, std::string("endTime"), endTime);
            } else if (isTrue(isTrue((!isEqual(since, std::any{}))) && isTrue((!isEqual(since, 0)))))
            {
                if (isTrue(isEqual(limit, std::any{})))
                {
                    limit = 30; // Exchange default
                }
                std::any duration = this->parseTimeframe(timeframe);
                ::setValue(request, std::string("endTime"), this->sum(since, multiply(multiply(duration, limit), 1000)));
            }
            std::any response = std::any{};
            if (isTrue(isEqual(::getValue(market, std::string("inverse")), true)))
            {
                response = awaitValue(this->dapiDataGetOpenInterestHist(this->extend(request, params)));
            } else
            {
                response = awaitValue(this->fapiDataGetOpenInterestHist(this->extend(request, params)));
            }
            //
            //  [
            //      {
            //          "symbol":"BTCUSDT",
            //          "sumOpenInterest":"75375.61700000",
            //          "sumOpenInterestValue":"3248828883.71251440",
            //          "timestamp":1642179900000
            //      },
            //      ...
            //  ]
            //
            return this->parseOpenInterestsHistory(response, market, since, limit);
        }).share();
    }

    /**
     * @method
     * @name binance#fetchOpenInterest
     * @description retrieves the open interest of a contract trading pair
     * @see https://developers.binance.com/docs/derivatives/usds-margined-futures/market-data/rest-api/Open-Interest
     * @see https://developers.binance.com/docs/derivatives/coin-margined-futures/market-data/rest-api/Open-Interest
     * @see https://developers.binance.com/docs/derivatives/option/market-data/Open-Interest
     * @param {string} symbol unified CCXT market symbol
     * @param {object} [params] exchange specific parameters
     * @returns {object} an open interest structure{@link https://docs.ccxt.com/?id=open-interest-structure}
     */
    std::shared_future<std::any> fetchOpenInterest(std::any symbol, std::any params = ccxt::dict {}) override
    {
        return std::async(std::launch::deferred, [=]() mutable -> std::any {
            if (isTrue(isEqual(this->markets, std::any{})))
            {
                awaitValue(this->loadMarkets());
            }
            std::any market = this->market(symbol);
            std::any request = ccxt::dict {};
            if (isTrue(isEqual(::getValue(market, std::string("option")), true)))
            {
                ::setValue(request, std::string("underlyingAsset"), ::getValue(market, std::string("baseId")));
                if (isTrue(isEqual(::getValue(market, std::string("expiry")), std::any{})))
                {
                    throw NotSupported(toString(add(add(this->id, std::string(" fetchOpenInterest does not support ")), symbol)));
                }
                ::setValue(request, std::string("expiration"), this->yymmdd(::getValue(market, std::string("expiry"))));
            } else
            {
                ::setValue(request, std::string("symbol"), ::getValue(market, std::string("id")));
            }
            std::any response = std::any{};
            if (isTrue(isEqual(::getValue(market, std::string("option")), true)))
            {
                response = awaitValue(this->eapiPublicGetOpenInterest(this->extend(request, params)));
            } else if (isTrue(isEqual(::getValue(market, std::string("inverse")), true)))
            {
                response = awaitValue(this->dapiPublicGetOpenInterest(this->extend(request, params)));
            } else
            {
                response = awaitValue(this->fapiPublicGetOpenInterest(this->extend(request, params)));
            }
            //
            // futures (fapi)
            //
            //     {
            //         "symbol": "ETHUSDT_230331",
            //         "openInterest": "23581.677",
            //         "time": 1677356872265
            //     }
            //
            // futures (dapi)
            //
            //     {
            //         "symbol": "ETHUSD_PERP",
            //         "pair": "ETHUSD",
            //         "openInterest": "26542436",
            //         "contractType": "PERPETUAL",
            //         "time": 1677360272224
            //     }
            //
            // options (eapi)
            //
            //     [
            //         {
            //             "symbol": "ETH-230225-1625-C",
            //             "sumOpenInterest": "460.50",
            //             "sumOpenInterestUsd": "734957.4358092150",
            //             "timestamp": "1677304860000"
            //         }
            //     ]
            //
            if (isTrue(isEqual(::getValue(market, std::string("option")), true)))
            {
                symbol = ::getValue(market, std::string("symbol"));
                std::any result = this->parseOpenInterestsHistory(response, market);
                for (std::any i = 0; isLessThan(i, getArrayLength(result)); postFixIncrement(i))
                {
                    std::any item = ::getValue(result, i);
                    if (isTrue(isEqual(::getValue(item, std::string("symbol")), symbol)))
                    {
                        return item;
                    }
                }
                throw NullResponse(toString(add(add(this->id, std::string(" fetchOpenInterest() could not find open interest for ")), symbol)));
            } else
            {
                return this->parseOpenInterest(response, market);
            }
            return std::any{};
        }).share();
    }

    std::any parseOpenInterest(std::any interest, std::any market = std::any{}) override
    {
        std::any timestamp = this->safeInteger2(interest, std::string("timestamp"), std::string("time"));
        std::any id = this->safeString(interest, std::string("symbol"));
        std::any amount = this->safeNumber2(interest, std::string("sumOpenInterest"), std::string("openInterest"));
        std::any value = this->safeNumber2(interest, std::string("sumOpenInterestValue"), std::string("sumOpenInterestUsd"));
        // Inverse returns the number of contracts different from the base or quote volume in this case
        // compared with https://www.binance.com/en/futures/funding-history/quarterly/4
        std::any isInverse = (isEqual(this->safeBool(market, std::string("inverse")), true));
        std::any baseVolume = (isTrue(isInverse) ? std::any(std::any{}) : std::any(amount));
        return this->safeOpenInterest(ccxt::dict {
            { std::string("symbol"), this->safeSymbol(id, market, std::any{}, std::string("contract")) },
            { std::string("baseVolume"), baseVolume },
            { std::string("quoteVolume"), value },
            { std::string("openInterestAmount"), amount },
            { std::string("openInterestValue"), value },
            { std::string("timestamp"), timestamp },
            { std::string("datetime"), this->iso8601(timestamp) },
            { std::string("info"), interest },
        }, market);
    }

    /**
     * @method
     * @name binance#fetchMyLiquidations
     * @description retrieves the users liquidated positions
     * @see https://developers.binance.com/docs/margin_trading/trade/Get-Force-Liquidation-Record
     * @see https://developers.binance.com/docs/derivatives/usds-margined-futures/trade/rest-api/Users-Force-Orders
     * @see https://developers.binance.com/docs/derivatives/coin-margined-futures/trade/rest-api/Users-Force-Orders
     * @see https://developers.binance.com/docs/derivatives/portfolio-margin/trade/Query-Users-UM-Force-Orders
     * @see https://developers.binance.com/docs/derivatives/portfolio-margin/trade/Query-Users-CM-Force-Orders
     * @param {string} [symbol] unified CCXT market symbol
     * @param {int} [since] the earliest time in ms to fetch liquidations for
     * @param {int} [limit] the maximum number of liquidation structures to retrieve
     * @param {object} [params] exchange specific parameters for the binance api endpoint
     * @param {int} [params.until] timestamp in ms of the latest liquidation
     * @param {boolean} [params.paginate] *spot only* default false, when true will automatically paginate by calling this endpoint multiple times. See in the docs all the [available parameters](https://github.com/ccxt/ccxt/wiki/Manual#pagination-params)
     * @param {boolean} [params.portfolioMargin] set to true if you would like to fetch liquidations in a portfolio margin account
     * @param {string} [params.type] "spot"
     * @param {string} [params.subType] "linear" or "inverse"
     * @returns {object} an array of [liquidation structures]{@link https://docs.ccxt.com/?id=liquidation-structure}
     */
    std::shared_future<std::any> fetchMyLiquidations(std::any symbol = std::any{}, std::any since = std::any{}, std::any limit = std::any{}, std::any params = ccxt::dict {}) override
    {
        return std::async(std::launch::deferred, [=]() mutable -> std::any {
            if (isTrue(isEqual(this->markets, std::any{})))
            {
                awaitValue(this->loadMarkets());
            }
            std::any paginate = false;
            std::any paginateparamsVariable = this->handleOptionAndParams(params, std::string("fetchMyLiquidations"), std::string("paginate"));
            paginate = ::getValue(paginateparamsVariable, 0);
            params = ::getValue(paginateparamsVariable, 1);
            if (isTrue(paginate))
            {
                return awaitValue(this->fetchPaginatedCallIncremental(std::string("fetchMyLiquidations"), symbol, since, limit, params, std::string("current"), 100));
            }
            std::any market = std::any{};
            if (isTrue(!isEqual(symbol, std::any{})))
            {
                market = this->market(symbol);
            }
            std::any type = std::any{};
            std::any typeparamsVariable = this->handleMarketTypeAndParams(std::string("fetchMyLiquidations"), market, params);
            type = ::getValue(typeparamsVariable, 0);
            params = ::getValue(typeparamsVariable, 1);
            std::any subType = std::any{};
            std::any subTypeparamsVariable = this->handleSubTypeAndParams(std::string("fetchMyLiquidations"), market, params, std::string("linear"));
            subType = ::getValue(subTypeparamsVariable, 0);
            params = ::getValue(subTypeparamsVariable, 1);
            std::any isPortfolioMargin = std::any{};
            std::any isPortfolioMarginparamsVariable = this->handleOptionAndParams2(params, std::string("fetchMyLiquidations"), std::string("papi"), std::string("portfolioMargin"), false);
            isPortfolioMargin = ::getValue(isPortfolioMarginparamsVariable, 0);
            params = ::getValue(isPortfolioMarginparamsVariable, 1);
            std::any request = ccxt::dict {};
            if (isTrue(!isEqual(type, std::string("spot"))))
            {
                ::setValue(request, std::string("autoCloseType"), std::string("LIQUIDATION"));
            }
            if (isTrue(!isEqual(market, std::any{})))
            {
                std::any symbolKey = (isTrue((isEqual(::getValue(market, std::string("spot")), true))) ? std::any(std::string("isolatedSymbol")) : std::any(std::string("symbol")));
                if (!isTrue(isPortfolioMargin))
                {
                    ::setValue(request, symbolKey, ::getValue(market, std::string("id")));
                }
            }
            if (isTrue(!isEqual(since, std::any{})))
            {
                ::setValue(request, std::string("startTime"), since);
            }
            if (isTrue(!isEqual(limit, std::any{})))
            {
                if (isTrue(isEqual(type, std::string("spot"))))
                {
                    ::setValue(request, std::string("size"), limit);
                } else
                {
                    ::setValue(request, std::string("limit"), limit);
                }
            }
            std::any requestparamsVariable = this->handleUntilOption(std::string("endTime"), request, params);
            request = ::getValue(requestparamsVariable, 0);
            params = ::getValue(requestparamsVariable, 1);
            std::any response = std::any{};
            if (isTrue(isEqual(type, std::string("spot"))))
            {
                if (isTrue(isPortfolioMargin))
                {
                    response = awaitValue(this->papiGetMarginForceOrders(this->extend(request, params)));
                } else
                {
                    response = awaitValue(this->sapiGetMarginForceLiquidationRec(this->extend(request, params)));
                }
            } else if (isTrue(isEqual(subType, std::string("linear"))))
            {
                if (isTrue(isPortfolioMargin))
                {
                    response = awaitValue(this->papiGetUmForceOrders(this->extend(request, params)));
                } else
                {
                    response = awaitValue(this->fapiPrivateGetForceOrders(this->extend(request, params)));
                }
            } else if (isTrue(isEqual(subType, std::string("inverse"))))
            {
                if (isTrue(isPortfolioMargin))
                {
                    response = awaitValue(this->papiGetCmForceOrders(this->extend(request, params)));
                } else
                {
                    response = awaitValue(this->dapiPrivateGetForceOrders(this->extend(request, params)));
                }
            } else
            {
                throw NotSupported(toString(add(add(add(this->id, std::string(" fetchMyLiquidations() does not support ")), this->safeString(market, std::string("type"))), std::string(" markets"))));
            }
            //
            // margin
            //
            //     {
            //         "rows": [
            //             {
            //                 "avgPrice": "0.00388359",
            //                 "executedQty": "31.39000000",
            //                 "orderId": 180015097,
            //                 "price": "0.00388110",
            //                 "qty": "31.39000000",
            //                 "side": "SELL",
            //                 "symbol": "BNBBTC",
            //                 "timeInForce": "GTC",
            //                 "isIsolated": true,
            //                 "updatedTime": 1558941374745
            //             }
            //         ],
            //         "total": 1
            //     }
            //
            // linear
            //
            //     [
            //         {
            //             "orderId": 6071832819,
            //             "symbol": "BTCUSDT",
            //             "status": "FILLED",
            //             "clientOrderId": "autoclose-1596107620040000020",
            //             "price": "10871.09",
            //             "avgPrice": "10913.21000",
            //             "origQty": "0.001",
            //             "executedQty": "0.001",
            //             "cumQuote": "10.91321",
            //             "timeInForce": "IOC",
            //             "type": "LIMIT",
            //             "reduceOnly": false,
            //             "closePosition": false,
            //             "side": "SELL",
            //             "positionSide": "BOTH",
            //             "stopPrice": "0",
            //             "workingType": "CONTRACT_PRICE",
            //             "origType": "LIMIT",
            //             "time": 1596107620044,
            //             "updateTime": 1596107620087
            //         },
            //     ]
            //
            // inverse
            //
            //     [
            //         {
            //             "orderId": 165123080,
            //             "symbol": "BTCUSD_200925",
            //             "pair": "BTCUSD",
            //             "status": "FILLED",
            //             "clientOrderId": "autoclose-1596542005017000006",
            //             "price": "11326.9",
            //             "avgPrice": "11326.9",
            //             "origQty": "1",
            //             "executedQty": "1",
            //             "cumBase": "0.00882854",
            //             "timeInForce": "IOC",
            //             "type": "LIMIT",
            //             "reduceOnly": false,
            //             "closePosition": false,
            //             "side": "SELL",
            //             "positionSide": "BOTH",
            //             "stopPrice": "0",
            //             "workingType": "CONTRACT_PRICE",
            //             "priceProtect": false,
            //             "origType": "LIMIT",
            //             "time": 1596542005019,
            //             "updateTime": 1596542005050
            //         },
            //     ]
            //
            std::any liquidationsList = ccxt::list{};
            std::any rows = this->safeList(response, std::string("rows"));
            if (isTrue(!isEqual(rows, std::any{})))
            {
                liquidationsList = rows;
            } else if (isTrue(isArray(response)))
            {
                // linear and inverse return the bare array, margin wraps it in 'rows'
                liquidationsList = response;
            }
            return this->parseLiquidations(liquidationsList, market, since, limit);
        }).share();
    }

    std::any parseLiquidation(std::any liquidation, std::any market = std::any{}) override
    {
        //
        // margin
        //
        //     {
        //         "avgPrice": "0.00388359",
        //         "executedQty": "31.39000000",
        //         "orderId": 180015097,
        //         "price": "0.00388110",
        //         "qty": "31.39000000",
        //         "side": "SELL",
        //         "symbol": "BNBBTC",
        //         "timeInForce": "GTC",
        //         "isIsolated": true,
        //         "updatedTime": 1558941374745
        //     }
        //
        // linear
        //
        //     {
        //         "orderId": 6071832819,
        //         "symbol": "BTCUSDT",
        //         "status": "FILLED",
        //         "clientOrderId": "autoclose-1596107620040000020",
        //         "price": "10871.09",
        //         "avgPrice": "10913.21000",
        //         "origQty": "0.001",
        //         "executedQty": "0.002",
        //         "cumQuote": "10.91321",
        //         "timeInForce": "IOC",
        //         "type": "LIMIT",
        //         "reduceOnly": false,
        //         "closePosition": false,
        //         "side": "SELL",
        //         "positionSide": "BOTH",
        //         "stopPrice": "0",
        //         "workingType": "CONTRACT_PRICE",
        //         "origType": "LIMIT",
        //         "time": 1596107620044,
        //         "updateTime": 1596107620087
        //     }
        //
        // inverse
        //
        //     {
        //         "orderId": 165123080,
        //         "symbol": "BTCUSD_200925",
        //         "pair": "BTCUSD",
        //         "status": "FILLED",
        //         "clientOrderId": "autoclose-1596542005017000006",
        //         "price": "11326.9",
        //         "avgPrice": "11326.9",
        //         "origQty": "1",
        //         "executedQty": "1",
        //         "cumBase": "0.00882854",
        //         "timeInForce": "IOC",
        //         "type": "LIMIT",
        //         "reduceOnly": false,
        //         "closePosition": false,
        //         "side": "SELL",
        //         "positionSide": "BOTH",
        //         "stopPrice": "0",
        //         "workingType": "CONTRACT_PRICE",
        //         "priceProtect": false,
        //         "origType": "LIMIT",
        //         "time": 1596542005019,
        //         "updateTime": 1596542005050
        //     }
        //
        std::any marketId = this->safeString(liquidation, std::string("symbol"));
        std::any timestamp = this->safeInteger2(liquidation, std::string("updatedTime"), std::string("updateTime"));
        return this->safeLiquidation(ccxt::dict {
            { std::string("info"), liquidation },
            { std::string("symbol"), this->safeSymbol(marketId, market) },
            { std::string("contracts"), this->safeNumber(liquidation, std::string("executedQty")) },
            { std::string("contractSize"), this->safeNumber(market, std::string("contractSize")) },
            { std::string("price"), this->safeNumber(liquidation, std::string("avgPrice")) },
            { std::string("side"), this->safeStringLower(liquidation, std::string("side")) },
            { std::string("baseValue"), this->safeNumber(liquidation, std::string("cumBase")) },
            { std::string("quoteValue"), this->safeNumber(liquidation, std::string("cumQuote")) },
            { std::string("timestamp"), timestamp },
            { std::string("datetime"), this->iso8601(timestamp) },
        });
    }

    /**
     * @method
     * @name binance#fetchGreeks
     * @description fetches an option contracts greeks, financial metrics used to measure the factors that affect the price of an options contract
     * @see https://developers.binance.com/docs/derivatives/option/market-data/Option-Mark-Price
     * @param {string} symbol unified symbol of the market to fetch greeks for
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} a [greeks structure]{@link https://docs.ccxt.com/?id=greeks-structure}
     */
    std::shared_future<std::any> fetchGreeks(std::any symbol, std::any params = ccxt::dict {}) override
    {
        return std::async(std::launch::deferred, [=]() mutable -> std::any {
            if (isTrue(isEqual(this->markets, std::any{})))
            {
                awaitValue(this->loadMarkets());
            }
            std::any market = this->market(symbol);
            std::any request = ccxt::dict {
                { std::string("symbol"), ::getValue(market, std::string("id")) },
            };
            std::any response = awaitValue(this->eapiPublicGetMark(this->extend(request, params)));
            //
            //     [
            //         {
            //             "symbol": "BTC-231229-40000-C",
            //             "markPrice": "2012",
            //             "bidIV": "0.60236275",
            //             "askIV": "0.62267244",
            //             "markIV": "0.6125176",
            //             "delta": "0.39111646",
            //             "theta": "-32.13948531",
            //             "gamma": "0.00004656",
            //             "vega": "51.70062218",
            //             "highPriceLimit": "6474",
            //             "lowPriceLimit": "5"
            //         }
            //     ]
            //
            return this->parseGreeks(this->safeDict(response, 0, ccxt::dict {}), market);
        }).share();
    }

    /**
     * @method
     * @name binance#fetchAllGreeks
     * @description fetches all option contracts greeks, financial metrics used to measure the factors that affect the price of an options contract
     * @see https://developers.binance.com/docs/derivatives/option/market-data/Option-Mark-Price
     * @param {string[]} [symbols] unified symbols of the markets to fetch greeks for, all markets are returned if not assigned
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} a [greeks structure]{@link https://docs.ccxt.com/?id=greeks-structure}
     */
    std::shared_future<std::any> fetchAllGreeks(std::any symbols = std::any{}, std::any params = ccxt::dict {}) override
    {
        return std::async(std::launch::deferred, [=]() mutable -> std::any {
            if (isTrue(isEqual(this->markets, std::any{})))
            {
                awaitValue(this->loadMarkets());
            }
            symbols = this->marketSymbols(symbols, std::any{}, true, true, true);
            std::any request = ccxt::dict {};
            std::any market = std::any{};
            if (isTrue(!isEqual(symbols, std::any{})))
            {
                std::any symbolsLength = getArrayLength(symbols);
                if (isTrue(isEqual(symbolsLength, 1)))
                {
                    market = this->market(::getValue(symbols, 0));
                    ::setValue(request, std::string("symbol"), ::getValue(market, std::string("id")));
                }
            }
            std::any response = awaitValue(this->eapiPublicGetMark(this->extend(request, params)));
            //
            //     [
            //         {
            //             "symbol": "BTC-231229-40000-C",
            //             "markPrice": "2012",
            //             "bidIV": "0.60236275",
            //             "askIV": "0.62267244",
            //             "markIV": "0.6125176",
            //             "delta": "0.39111646",
            //             "theta": "-32.13948531",
            //             "gamma": "0.00004656",
            //             "vega": "51.70062218",
            //             "highPriceLimit": "6474",
            //             "lowPriceLimit": "5"
            //         }
            //     ]
            //
            return this->parseAllGreeks(response, symbols);
        }).share();
    }

    std::any parseGreeks(std::any greeks, std::any market = std::any{}) override
    {
        //
        //     {
        //         "symbol": "BTC-231229-40000-C",
        //         "markPrice": "2012",
        //         "bidIV": "0.60236275",
        //         "askIV": "0.62267244",
        //         "markIV": "0.6125176",
        //         "delta": "0.39111646",
        //         "theta": "-32.13948531",
        //         "gamma": "0.00004656",
        //         "vega": "51.70062218",
        //         "highPriceLimit": "6474",
        //         "lowPriceLimit": "5"
        //     }
        //
        std::any marketId = this->safeString(greeks, std::string("symbol"));
        std::any symbol = this->safeSymbol(marketId, market);
        return ccxt::dict {
            { std::string("symbol"), symbol },
            { std::string("timestamp"), std::any{} },
            { std::string("datetime"), std::any{} },
            { std::string("delta"), this->safeNumber(greeks, std::string("delta")) },
            { std::string("gamma"), this->safeNumber(greeks, std::string("gamma")) },
            { std::string("theta"), this->safeNumber(greeks, std::string("theta")) },
            { std::string("vega"), this->safeNumber(greeks, std::string("vega")) },
            { std::string("rho"), std::any{} },
            { std::string("bidSize"), std::any{} },
            { std::string("askSize"), std::any{} },
            { std::string("bidImpliedVolatility"), this->safeNumber(greeks, std::string("bidIV")) },
            { std::string("askImpliedVolatility"), this->safeNumber(greeks, std::string("askIV")) },
            { std::string("markImpliedVolatility"), this->safeNumber(greeks, std::string("markIV")) },
            { std::string("bidPrice"), std::any{} },
            { std::string("askPrice"), std::any{} },
            { std::string("markPrice"), this->safeNumber(greeks, std::string("markPrice")) },
            { std::string("lastPrice"), std::any{} },
            { std::string("underlyingPrice"), std::any{} },
            { std::string("info"), greeks },
        };
    }

    std::shared_future<std::any> fetchTradingLimits(std::any symbols = std::any{}, std::any params = ccxt::dict {}) override
    {
        return std::async(std::launch::deferred, [=]() mutable -> std::any {
            // this method should not be called directly, use loadTradingLimits () instead
            std::any markets = awaitValue(this->fetchMarkets());
            std::any tradingLimits = ccxt::dict {};
            for (std::any i = 0; isLessThan(i, getArrayLength(markets)); postFixIncrement(i))
            {
                std::any market = ::getValue(markets, i);
                std::any symbol = this->safeString(market, std::string("symbol"));
                if (isTrue(isEqual(market, std::any{})))
                {
                    throw ExchangeError(toString(add(this->id, std::string(" fetchTradingLimits() could not resolve market"))));
                }
                if (isTrue(isTrue((isEqual(symbols, std::any{}))) || isTrue((this->inArray(symbol, symbols)))))
                {
                    if (isTrue(!isEqual(symbol, std::any{})))
                    {
                        ::setValue(tradingLimits, symbol, ::getValue(::getValue(market, std::string("limits")), std::string("amount")));
                    }
                }
            }
            return tradingLimits;
        }).share();
    }

    /**
     * @method
     * @name binance#fetchPositionMode
     * @description fetchs the position mode, hedged or one way, hedged for binance is set identically for all linear markets or all inverse markets
     * @see https://developers.binance.com/docs/derivatives/usds-margined-futures/account/rest-api/Get-Current-Position-Mode
     * @see https://developers.binance.com/docs/derivatives/coin-margined-futures/account/rest-api/Get-Current-Position-Mode
     * @param {string} symbol unified symbol of the market to fetch the order book for
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {string} [params.subType] "linear" or "inverse"
     * @returns {object} an object detailing whether the market is in hedged or one-way mode
     */
    std::shared_future<std::any> fetchPositionMode(std::any symbol = std::any{}, std::any params = ccxt::dict {}) override
    {
        return std::async(std::launch::deferred, [=]() mutable -> std::any {
            std::any market = std::any{};
            if (isTrue(!isEqual(symbol, std::any{})))
            {
                market = this->market(symbol);
            }
            std::any subType = std::any{};
            std::any subTypeparamsVariable = this->handleSubTypeAndParams(std::string("fetchPositionMode"), market, params);
            subType = ::getValue(subTypeparamsVariable, 0);
            params = ::getValue(subTypeparamsVariable, 1);
            std::any response = std::any{};
            // we still have two working endpoints but positionMode is common for linear and inverse markets
            // thus we do not throw an error if the subType is not specified and default to linear for now
            if (isTrue(isEqual(subType, std::string("inverse"))))
            {
                response = awaitValue(this->dapiPrivateGetPositionSideDual(params));
            } else
            {
                response = awaitValue(this->fapiPrivateGetPositionSideDual(params));
            }
            //
            //    {
            //        dualSidePosition: false
            //    }
            //
            std::any dualSidePosition = this->safeBool(response, std::string("dualSidePosition"));
            return ccxt::dict {
                { std::string("info"), response },
                { std::string("hedged"), dualSidePosition },
            };
        }).share();
    }

    /**
     * @method
     * @name binance#fetchMarginModes
     * @description fetches margin modes ("isolated" or "cross") that the market for the symbol in in, with symbol=undefined all markets for a subType (linear/inverse) are returned
     * @see https://developers.binance.com/docs/derivatives/coin-margined-futures/account/rest-api/Account-Information
     * @see https://developers.binance.com/docs/derivatives/usds-margined-futures/account/rest-api/Account-Information-V2
     * @see https://developers.binance.com/docs/derivatives/usds-margined-futures/account/rest-api/Symbol-Config
     * @param {string[]} symbols unified market symbols
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {string} [params.subType] "linear" or "inverse"
     * @returns {object} a list of [margin mode structures]{@link https://docs.ccxt.com/?id=margin-mode-structure}
     */
    std::shared_future<std::any> fetchMarginModes(std::any symbols = std::any{}, std::any params = ccxt::dict {}) override
    {
        return std::async(std::launch::deferred, [=]() mutable -> std::any {
            if (isTrue(isEqual(this->markets, std::any{})))
            {
                awaitValue(this->loadMarkets());
            }
            std::any market = std::any{};
            if (isTrue(!isEqual(symbols, std::any{})))
            {
                symbols = this->marketSymbols(symbols);
                market = this->market(::getValue(symbols, 0));
            }
            std::any subType = std::any{};
            std::any subTypeparamsVariable = this->handleSubTypeAndParams(std::string("fetchMarginMode"), market, params);
            subType = ::getValue(subTypeparamsVariable, 0);
            params = ::getValue(subTypeparamsVariable, 1);
            std::any response = std::any{};
            if (isTrue(isEqual(subType, std::string("linear"))))
            {
                response = awaitValue(this->fapiPrivateGetSymbolConfig(params));
            } else if (isTrue(isEqual(subType, std::string("inverse"))))
            {
                response = awaitValue(this->dapiPrivateGetAccount(params));
            } else
            {
                throw BadRequest(toString(add(this->id, std::string(" fetchMarginModes () supports linear and inverse subTypes only"))));
            }
            std::any assets = this->safeList(response, std::string("positions"), ccxt::list{});
            if (isTrue(isArray(response)))
            {
                assets = response;
            }
            return this->parseMarginModes(assets, symbols, std::string("symbol"), std::string("swap"));
        }).share();
    }

    /**
     * @method
     * @name binance#fetchMarginMode
     * @description fetches the margin mode of a specific symbol
     * @see https://developers.binance.com/docs/derivatives/usds-margined-futures/account/rest-api/Symbol-Config
     * @see https://developers.binance.com/docs/derivatives/coin-margined-futures/account/rest-api/Account-Information
     * @param {string} symbol unified symbol of the market the order was made in
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {string} [params.subType] "linear" or "inverse"
     * @returns {object} a [margin mode structure]{@link https://docs.ccxt.com/?id=margin-mode-structure}
     */
    std::shared_future<std::any> fetchMarginMode(std::any symbol, std::any params = ccxt::dict {}) override
    {
        return std::async(std::launch::deferred, [=]() mutable -> std::any {
            if (isTrue(isEqual(this->markets, std::any{})))
            {
                awaitValue(this->loadMarkets());
            }
            std::any market = this->market(symbol);
            std::any subType = std::any{};
            std::any subTypeparamsVariable = this->handleSubTypeAndParams(std::string("fetchMarginMode"), market, params);
            subType = ::getValue(subTypeparamsVariable, 0);
            params = ::getValue(subTypeparamsVariable, 1);
            std::any response = std::any{};
            if (isTrue(isEqual(subType, std::string("linear"))))
            {
                std::any request = ccxt::dict {
                    { std::string("symbol"), ::getValue(market, std::string("id")) },
                };
                response = awaitValue(this->fapiPrivateGetSymbolConfig(this->extend(request, params)));
            } else if (isTrue(isEqual(subType, std::string("inverse"))))
            {
                std::any fetchMarginModesResponse = awaitValue(this->fetchMarginModes(ccxt::list{symbol}, params));
                return ::getValue(fetchMarginModesResponse, symbol);
            } else
            {
                throw BadRequest(toString(add(this->id, std::string(" fetchMarginMode () supports linear and inverse subTypes only"))));
            }
            if (isTrue(isEqual(response, std::any{})))
            {
                throw NullResponse(toString(add(this->id, std::string(" fetchMarginMode() returned empty response"))));
            }
            return this->parseMarginMode(::getValue(response, 0), market);
        }).share();
    }

    std::any parseMarginMode(std::any marginMode, std::any market = std::any{}) override
    {
        std::any marketId = this->safeString(marginMode, std::string("symbol"));
        market = this->safeMarket(marketId, market);
        std::any marginModeRaw = this->safeBool(marginMode, std::string("isolated"));
        std::any reMarginMode = std::any{};
        if (isTrue(!isEqual(marginModeRaw, std::any{})))
        {
            reMarginMode = (isTrue(marginModeRaw) ? std::any(std::string("isolated")) : std::any(std::string("cross")));
        }
        std::any marginTypeRaw = this->safeStringLower(marginMode, std::string("marginType"));
        if (isTrue(!isEqual(marginTypeRaw, std::any{})))
        {
            reMarginMode = (isTrue((isEqual(marginTypeRaw, std::string("crossed")))) ? std::any(std::string("cross")) : std::any(std::string("isolated")));
        }
        return ccxt::dict {
            { std::string("info"), marginMode },
            { std::string("symbol"), this->safeString(market, std::string("symbol")) },
            { std::string("marginMode"), reMarginMode },
        };
    }

    /**
     * @method
     * @name binance#fetchOption
     * @description fetches option data that is commonly found in an option chain
     * @see https://developers.binance.com/docs/derivatives/option/market-data/24hr-Ticker-Price-Change-Statistics
     * @param {string} symbol unified market symbol
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} an [option chain structure]{@link https://docs.ccxt.com/?id=option-chain-structure}
     */
    std::shared_future<std::any> fetchOption(std::any symbol, std::any params = ccxt::dict {}) override
    {
        return std::async(std::launch::deferred, [=]() mutable -> std::any {
            if (isTrue(isEqual(this->markets, std::any{})))
            {
                awaitValue(this->loadMarkets());
            }
            std::any market = this->market(symbol);
            std::any request = ccxt::dict {
                { std::string("symbol"), ::getValue(market, std::string("id")) },
            };
            std::any response = awaitValue(this->eapiPublicGetTicker(this->extend(request, params)));
            //
            //     [
            //         {
            //             "symbol": "BTC-241227-80000-C",
            //             "priceChange": "0",
            //             "priceChangePercent": "0",
            //             "lastPrice": "2750",
            //             "lastQty": "0",
            //             "open": "2750",
            //             "high": "2750",
            //             "low": "2750",
            //             "volume": "0",
            //             "amount": "0",
            //             "bidPrice": "4880",
            //             "askPrice": "0",
            //             "openTime": 0,
            //             "closeTime": 0,
            //             "firstTradeId": 0,
            //             "tradeCount": 0,
            //             "strikePrice": "80000",
            //             "exercisePrice": "63944.09893617"
            //         }
            //     ]
            //
            std::any chain = this->safeDict(response, 0, ccxt::dict {});
            return this->parseOption(chain, std::any{}, market);
        }).share();
    }

    std::any parseOption(std::any chain, std::any currency = std::any{}, std::any market = std::any{}) override
    {
        //
        //     {
        //         "symbol": "BTC-241227-80000-C",
        //         "priceChange": "0",
        //         "priceChangePercent": "0",
        //         "lastPrice": "2750",
        //         "lastQty": "0",
        //         "open": "2750",
        //         "high": "2750",
        //         "low": "2750",
        //         "volume": "0",
        //         "amount": "0",
        //         "bidPrice": "4880",
        //         "askPrice": "0",
        //         "openTime": 0,
        //         "closeTime": 0,
        //         "firstTradeId": 0,
        //         "tradeCount": 0,
        //         "strikePrice": "80000",
        //         "exercisePrice": "63944.09893617"
        //     }
        //
        std::any marketId = this->safeString(chain, std::string("symbol"));
        market = this->safeMarket(marketId, market);
        return ccxt::dict {
            { std::string("info"), chain },
            { std::string("currency"), std::any{} },
            { std::string("symbol"), ::getValue(market, std::string("symbol")) },
            { std::string("timestamp"), std::any{} },
            { std::string("datetime"), std::any{} },
            { std::string("impliedVolatility"), std::any{} },
            { std::string("openInterest"), std::any{} },
            { std::string("bidPrice"), this->safeNumber(chain, std::string("bidPrice")) },
            { std::string("askPrice"), this->safeNumber(chain, std::string("askPrice")) },
            { std::string("midPrice"), std::any{} },
            { std::string("markPrice"), std::any{} },
            { std::string("lastPrice"), this->safeNumber(chain, std::string("lastPrice")) },
            { std::string("underlyingPrice"), this->safeNumber(chain, std::string("exercisePrice")) },
            { std::string("change"), this->safeNumber(chain, std::string("priceChange")) },
            { std::string("percentage"), this->safeNumber(chain, std::string("priceChangePercent")) },
            { std::string("baseVolume"), this->safeNumber(chain, std::string("volume")) },
            { std::string("quoteVolume"), std::any{} },
        };
    }

    /**
     * @method
     * @name binance#fetchMarginAdjustmentHistory
     * @description fetches the history of margin added or reduced from contract isolated positions
     * @see https://developers.binance.com/docs/derivatives/usds-margined-futures/trade/rest-api/Get-Position-Margin-Change-History
     * @see https://developers.binance.com/docs/derivatives/coin-margined-futures/trade/rest-api/Get-Position-Margin-Change-History
     * @param {string} symbol unified market symbol
     * @param {string} [type] "add" or "reduce"
     * @param {int} [since] timestamp in ms of the earliest change to fetch
     * @param {int} [limit] the maximum amount of changes to fetch
     * @param {object} params extra parameters specific to the exchange API endpoint
     * @param {int} [params.until] timestamp in ms of the latest change to fetch
     * @returns {object[]} a list of [margin structures]{@link https://docs.ccxt.com/?id=margin-loan-structure}
     */
    std::shared_future<std::any> fetchMarginAdjustmentHistory(std::any symbol = std::any{}, std::any type = std::any{}, std::any since = std::any{}, std::any limit = std::any{}, std::any params = ccxt::dict {}) override
    {
        return std::async(std::launch::deferred, [=]() mutable -> std::any {
            if (isTrue(isEqual(this->markets, std::any{})))
            {
                awaitValue(this->loadMarkets());
            }
            if (isTrue(isEqual(symbol, std::any{})))
            {
                throw ArgumentsRequired(toString(add(this->id, std::string(" fetchMarginAdjustmentHistory () requires a symbol argument"))));
            }
            std::any market = this->market(symbol);
            std::any until = this->safeInteger(params, std::string("until"));
            params = this->omit(params, std::string("until"));
            std::any request = ccxt::dict {
                { std::string("symbol"), ::getValue(market, std::string("id")) },
            };
            if (isTrue(!isEqual(type, std::any{})))
            {
                ::setValue(request, std::string("type"), (isTrue((isEqual(type, std::string("add")))) ? std::any(1) : std::any(2)));
            }
            if (isTrue(!isEqual(since, std::any{})))
            {
                ::setValue(request, std::string("startTime"), since);
            }
            if (isTrue(!isEqual(limit, std::any{})))
            {
                ::setValue(request, std::string("limit"), limit);
            }
            if (isTrue(!isEqual(until, std::any{})))
            {
                ::setValue(request, std::string("endTime"), until);
            }
            std::any response = std::any{};
            if (isTrue(isEqual(::getValue(market, std::string("linear")), true)))
            {
                response = awaitValue(this->fapiPrivateGetPositionMarginHistory(this->extend(request, params)));
            } else if (isTrue(isEqual(::getValue(market, std::string("inverse")), true)))
            {
                response = awaitValue(this->dapiPrivateGetPositionMarginHistory(this->extend(request, params)));
            } else
            {
                throw BadRequest(toString(add(add(this->id, std::string(" fetchMarginAdjustmentHistory () is not supported for markets of type ")), ::getValue(market, std::string("type")))));
            }
            //
            //    [
            //        {
            //            symbol: "XRPUSDT",
            //            type: "1",
            //            deltaType: "TRADE",
            //            amount: "2.57148240",
            //            asset: "USDT",
            //            time: "1711046271555",
            //            positionSide: "BOTH",
            //            clientTranId: ""
            //        }
            //        ...
            //    ]
            //
            if (isTrue(isEqual(response, std::any{})))
            {
                throw NullResponse(toString(add(this->id, std::string(" parseMarginModifications() returned empty response"))));
            }
            std::any modifications = this->parseMarginModifications(this->toArray(response));
            return this->filterBySymbolSinceLimit(modifications, symbol, since, limit);
        }).share();
    }

    /**
     * @method
     * @name binance#fetchConvertCurrencies
     * @description fetches all available currencies that can be converted
     * @see https://developers.binance.com/docs/convert/market-data/Query-order-quantity-precision-per-asset
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} an associative dictionary of currencies
     */
    std::shared_future<std::any> fetchConvertCurrencies(std::any params = ccxt::dict {}) override
    {
        return std::async(std::launch::deferred, [=]() mutable -> std::any {
            if (isTrue(isEqual(this->markets, std::any{})))
            {
                awaitValue(this->loadMarkets());
            }
            std::any response = awaitValue(this->sapiGetConvertAssetInfo(params));
            //
            //     [
            //         {
            //             "asset": "BTC",
            //             "fraction": 8
            //         },
            //     ]
            //
            std::any result = ccxt::dict {};
            std::any assets = this->toArray(response);
            for (std::any i = 0; isLessThan(i, getArrayLength(assets)); postFixIncrement(i))
            {
                std::any entry = ::getValue(assets, i);
                std::any id = this->safeString(entry, std::string("asset"));
                std::any code = this->safeCurrencyCode(id);
                if (isTrue(!isEqual(code, std::any{})))
                {
                    ::setValue(result, code, ccxt::dict {
    { std::string("info"), entry },
    { std::string("id"), id },
    { std::string("code"), code },
    { std::string("networks"), std::any{} },
    { std::string("type"), std::any{} },
    { std::string("name"), std::any{} },
    { std::string("active"), std::any{} },
    { std::string("deposit"), std::any{} },
    { std::string("withdraw"), std::any{} },
    { std::string("fee"), std::any{} },
    { std::string("precision"), this->parseNumber(this->parsePrecision(this->safeString(entry, std::string("fraction")))) },
    { std::string("limits"), ccxt::dict {
        { std::string("amount"), ccxt::dict {
            { std::string("min"), std::any{} },
            { std::string("max"), std::any{} },
        } },
        { std::string("withdraw"), ccxt::dict {
            { std::string("min"), std::any{} },
            { std::string("max"), std::any{} },
        } },
        { std::string("deposit"), ccxt::dict {
            { std::string("min"), std::any{} },
            { std::string("max"), std::any{} },
        } },
    } },
    { std::string("created"), std::any{} },
});
                }
            }
            return result;
        }).share();
    }

    /**
     * @method
     * @name binance#fetchConvertQuote
     * @description fetch a quote for converting from one currency to another
     * @see https://developers.binance.com/docs/convert/trade/Send-quote-request
     * @param {string} fromCode the currency that you want to sell and convert from
     * @param {string} toCode the currency that you want to buy and convert into
     * @param {float} amount how much you want to trade in units of the from currency
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {string} [params.walletType] either 'SPOT' or 'FUNDING', the default is 'SPOT'
     * @returns {object} a [conversion structure]{@link https://docs.ccxt.com/?id=conversion-structure}
     */
    std::shared_future<std::any> fetchConvertQuote(std::any fromCode, std::any toCode, std::any amount = std::any{}, std::any params = ccxt::dict {}) override
    {
        return std::async(std::launch::deferred, [=]() mutable -> std::any {
            if (isTrue(isEqual(amount, std::any{})))
            {
                throw ArgumentsRequired(toString(add(this->id, std::string(" fetchConvertQuote() requires an amount argument"))));
            }
            if (isTrue(isEqual(this->markets, std::any{})))
            {
                awaitValue(this->loadMarkets());
            }
            std::any request = ccxt::dict {
                { std::string("fromAsset"), fromCode },
                { std::string("toAsset"), toCode },
                { std::string("fromAmount"), amount },
            };
            std::any response = awaitValue(this->sapiPostConvertGetQuote(this->extend(request, params)));
            //
            //     {
            //         "quoteId":"12415572564",
            //         "ratio":"38163.7",
            //         "inverseRatio":"0.0000262",
            //         "validTimestamp":1623319461670,
            //         "toAmount":"3816.37",
            //         "fromAmount":"0.1"
            //     }
            //
            std::any fromCurrency = this->currency(fromCode);
            std::any toCurrency = this->currency(toCode);
            if (isTrue(isEqual(response, std::any{})))
            {
                throw NullResponse(toString(add(this->id, std::string(" parseConversion() returned empty response"))));
            }
            return this->parseConversion(response, fromCurrency, toCurrency);
        }).share();
    }

    /**
     * @method
     * @name binance#createConvertTrade
     * @description convert from one currency to another
     * @see https://developers.binance.com/docs/convert/trade/Accept-Quote
     * @param {string} id the id of the trade that you want to make
     * @param {string} fromCode the currency that you want to sell and convert from
     * @param {string} toCode the currency that you want to buy and convert into
     * @param {float} [amount] how much you want to trade in units of the from currency
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} a [conversion structure]{@link https://docs.ccxt.com/?id=conversion-structure}
     */
    std::shared_future<std::any> createConvertTrade(std::any id, std::any fromCode, std::any toCode, std::any amount = std::any{}, std::any params = ccxt::dict {}) override
    {
        return std::async(std::launch::deferred, [=]() mutable -> std::any {
            if (isTrue(isEqual(this->markets, std::any{})))
            {
                awaitValue(this->loadMarkets());
            }
            std::any request = ccxt::dict {};
            std::any response = std::any{};
            if (isTrue(isTrue((isEqual(fromCode, std::string("BUSD")))) || isTrue((isEqual(toCode, std::string("BUSD"))))))
            {
                if (isTrue(isEqual(amount, std::any{})))
                {
                    throw ArgumentsRequired(toString(add(this->id, std::string(" createConvertTrade() requires an amount argument"))));
                }
                ::setValue(request, std::string("clientTranId"), id);
                ::setValue(request, std::string("asset"), fromCode);
                ::setValue(request, std::string("targetAsset"), toCode);
                ::setValue(request, std::string("amount"), amount);
                response = awaitValue(this->sapiPostAssetConvertTransfer(this->extend(request, params)));
            } else
            {
                ::setValue(request, std::string("quoteId"), id);
                response = awaitValue(this->sapiPostConvertAcceptQuote(this->extend(request, params)));
            }
            std::any fromCurrency = this->currency(fromCode);
            std::any toCurrency = this->currency(toCode);
            if (isTrue(isEqual(response, std::any{})))
            {
                throw NullResponse(toString(add(this->id, std::string(" parseConversion() returned empty response"))));
            }
            return this->parseConversion(response, fromCurrency, toCurrency);
        }).share();
    }

    /**
     * @method
     * @name binance#fetchConvertTrade
     * @description fetch the data for a conversion trade
     * @see https://developers.binance.com/docs/convert/trade/Order-Status
     * @param {string} id the id of the trade that you want to fetch
     * @param {string} [code] the unified currency code of the conversion trade
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} a [conversion structure]{@link https://docs.ccxt.com/?id=conversion-structure}
     */
    std::shared_future<std::any> fetchConvertTrade(std::any id, std::any code = std::any{}, std::any params = ccxt::dict {}) override
    {
        return std::async(std::launch::deferred, [=]() mutable -> std::any {
            if (isTrue(isEqual(this->markets, std::any{})))
            {
                awaitValue(this->loadMarkets());
            }
            std::any request = ccxt::dict {};
            std::any response = std::any{};
            if (isTrue(isEqual(code, std::string("BUSD"))))
            {
                std::any msInDay = 86400000;
                std::any now = this->milliseconds();
                if (isTrue(!isEqual(code, std::any{})))
                {
                    std::any currency = this->currency(code);
                    ::setValue(request, std::string("asset"), ::getValue(currency, std::string("id")));
                }
                ::setValue(request, std::string("tranId"), id);
                ::setValue(request, std::string("startTime"), subtract(now, msInDay));
                ::setValue(request, std::string("endTime"), now);
                response = awaitValue(this->sapiGetAssetConvertTransferQueryByPage(this->extend(request, params)));
            } else
            {
                ::setValue(request, std::string("orderId"), id);
                response = awaitValue(this->sapiGetConvertOrderStatus(this->extend(request, params)));
            }
            std::any data = response;
            if (isTrue(isEqual(code, std::string("BUSD"))))
            {
                std::any rows = this->safeList(response, std::string("rows"), ccxt::list{});
                data = this->safeDict(rows, 0, ccxt::dict {});
            }
            std::any fromCurrencyId = this->safeString2(data, std::string("deductedAsset"), std::string("fromAsset"));
            std::any toCurrencyId = this->safeString2(data, std::string("targetAsset"), std::string("toAsset"));
            std::any fromCurrency = std::any{};
            std::any toCurrency = std::any{};
            if (isTrue(!isEqual(fromCurrencyId, std::any{})))
            {
                fromCurrency = this->currency(fromCurrencyId);
            }
            if (isTrue(!isEqual(toCurrencyId, std::any{})))
            {
                toCurrency = this->currency(toCurrencyId);
            }
            if (isTrue(isEqual(data, std::any{})))
            {
                throw NullResponse(toString(add(this->id, std::string(" parseConversion() returned empty response"))));
            }
            return this->parseConversion(data, fromCurrency, toCurrency);
        }).share();
    }

    /**
     * @method
     * @name binance#fetchConvertTradeHistory
     * @description fetch the users history of conversion trades
     * @see https://developers.binance.com/docs/convert/trade/Get-Convert-Trade-History
     * @param {string} [code] the unified currency code
     * @param {int} [since] the earliest time in ms to fetch conversions for
     * @param {int} [limit] the maximum number of conversion structures to retrieve
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {int} [params.until] timestamp in ms of the latest conversion to fetch
     * @returns {object[]} a list of [conversion structures]{@link https://docs.ccxt.com/?id=conversion-structure}
     */
    std::shared_future<std::any> fetchConvertTradeHistory(std::any code = std::any{}, std::any since = std::any{}, std::any limit = std::any{}, std::any params = ccxt::dict {}) override
    {
        return std::async(std::launch::deferred, [=]() mutable -> std::any {
            if (isTrue(isEqual(this->markets, std::any{})))
            {
                awaitValue(this->loadMarkets());
            }
            std::any request = ccxt::dict {};
            std::any msInThirtyDays = 2592000000;
            std::any now = this->milliseconds();
            if (isTrue(!isEqual(since, std::any{})))
            {
                ::setValue(request, std::string("startTime"), since);
            } else
            {
                ::setValue(request, std::string("startTime"), subtract(now, msInThirtyDays));
            }
            std::any endTime = this->safeInteger2(params, std::string("endTime"), std::string("until"));
            if (isTrue(!isEqual(endTime, std::any{})))
            {
                ::setValue(request, std::string("endTime"), endTime);
            } else
            {
                ::setValue(request, std::string("endTime"), now);
            }
            params = this->omit(params, std::string("until"));
            std::any response = std::any{};
            std::any responseQuery = std::any{};
            std::any fromCurrencyKey = std::any{};
            std::any toCurrencyKey = std::any{};
            if (isTrue(isEqual(code, std::string("BUSD"))))
            {
                std::any currency = this->currency(code);
                ::setValue(request, std::string("asset"), ::getValue(currency, std::string("id")));
                if (isTrue(!isEqual(limit, std::any{})))
                {
                    ::setValue(request, std::string("size"), limit);
                }
                fromCurrencyKey = std::string("deductedAsset");
                toCurrencyKey = std::string("targetAsset");
                responseQuery = std::string("rows");
                response = awaitValue(this->sapiGetAssetConvertTransferQueryByPage(this->extend(request, params)));
            } else
            {
                if (isTrue(isGreaterThan((subtract(::getValue(request, std::string("endTime")), ::getValue(request, std::string("startTime")))), msInThirtyDays)))
                {
                    throw BadRequest(toString(add(this->id, std::string(" fetchConvertTradeHistory () the max interval between startTime and endTime is 30 days."))));
                }
                if (isTrue(!isEqual(limit, std::any{})))
                {
                    ::setValue(request, std::string("limit"), limit);
                }
                fromCurrencyKey = std::string("fromAsset");
                toCurrencyKey = std::string("toAsset");
                responseQuery = std::string("list");
                response = awaitValue(this->sapiGetConvertTradeFlow(this->extend(request, params)));
            }
            std::any rows = this->safeList(response, responseQuery, ccxt::list{});
            return this->parseConversions(rows, code, fromCurrencyKey, toCurrencyKey, since, limit);
        }).share();
    }

    std::any parseConversion(std::any conversion, std::any fromCurrency = std::any{}, std::any toCurrency = std::any{}) override
    {
        //
        // fetchConvertQuote
        //
        //     {
        //         "quoteId":"12415572564",
        //         "ratio":"38163.7",
        //         "inverseRatio":"0.0000262",
        //         "validTimestamp":1623319461670,
        //         "toAmount":"3816.37",
        //         "fromAmount":"0.1"
        //     }
        //
        // createConvertTrade
        //
        //     {
        //         "orderId":"933256278426274426",
        //         "createTime":1623381330472,
        //         "orderStatus":"PROCESS"
        //     }
        //
        // createConvertTrade BUSD
        //
        //     {
        //         "tranId": 118263407119,
        //         "status": "S"
        //     }
        //
        // fetchConvertTrade, fetchConvertTradeHistory BUSD
        //
        //     {
        //         "tranId": 118263615991,
        //         "type": 244,
        //         "time": 1664442078000,
        //         "deductedAsset": "BUSD",
        //         "deductedAmount": "1",
        //         "targetAsset": "USDC",
        //         "targetAmount": "1",
        //         "status": "S",
        //         "accountType": "MAIN"
        //     }
        //
        // fetchConvertTrade
        //
        //     {
        //         "orderId":933256278426274426,
        //         "orderStatus":"SUCCESS",
        //         "fromAsset":"BTC",
        //         "fromAmount":"0.00054414",
        //         "toAsset":"USDT",
        //         "toAmount":"20",
        //         "ratio":"36755",
        //         "inverseRatio":"0.00002721",
        //         "createTime":1623381330472
        //     }
        //
        // fetchConvertTradeHistory
        //
        //     {
        //         "quoteId": "f3b91c525b2644c7bc1e1cd31b6e1aa6",
        //         "orderId": 940708407462087195,
        //         "orderStatus": "SUCCESS",
        //         "fromAsset": "USDT",
        //         "fromAmount": "20",
        //         "toAsset": "BNB",
        //         "toAmount": "0.06154036",
        //         "ratio": "0.00307702",
        //         "inverseRatio": "324.99",
        //         "createTime": 1624248872184
        //     }
        //
        std::any timestamp = this->safeIntegerN(conversion, ccxt::list{std::string("time"), std::string("validTimestamp"), std::string("createTime")});
        std::any fromCur = this->safeString2(conversion, std::string("deductedAsset"), std::string("fromAsset"));
        std::any fromCode = this->safeCurrencyCode(fromCur, fromCurrency);
        std::any to = this->safeString2(conversion, std::string("targetAsset"), std::string("toAsset"));
        std::any toCode = this->safeCurrencyCode(to, toCurrency);
        return ccxt::dict {
            { std::string("info"), conversion },
            { std::string("timestamp"), timestamp },
            { std::string("datetime"), this->iso8601(timestamp) },
            { std::string("id"), this->safeStringN(conversion, ccxt::list{std::string("tranId"), std::string("orderId"), std::string("quoteId")}) },
            { std::string("fromCurrency"), fromCode },
            { std::string("fromAmount"), this->safeNumber2(conversion, std::string("deductedAmount"), std::string("fromAmount")) },
            { std::string("toCurrency"), toCode },
            { std::string("toAmount"), this->safeNumber2(conversion, std::string("targetAmount"), std::string("toAmount")) },
            { std::string("price"), std::any{} },
            { std::string("fee"), std::any{} },
        };
    }

    /**
     * @method
     * @name binance#fetchFundingIntervals
     * @description fetch the funding rate interval for multiple markets
     * @see https://developers.binance.com/docs/derivatives/usds-margined-futures/market-data/rest-api/Get-Funding-Rate-Info
     * @see https://developers.binance.com/docs/derivatives/coin-margined-futures/market-data/rest-api/Get-Funding-Info
     * @param {string[]} [symbols] list of unified market symbols
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {string} [params.subType] "linear" or "inverse"
     * @returns {object[]} a list of [funding rate structures]{@link https://docs.ccxt.com/?id=funding-rate-structure}
     */
    std::shared_future<std::any> fetchFundingIntervals(std::any symbols = std::any{}, std::any params = ccxt::dict {}) override
    {
        return std::async(std::launch::deferred, [=]() mutable -> std::any {
            if (isTrue(isEqual(this->markets, std::any{})))
            {
                awaitValue(this->loadMarkets());
            }
            std::any market = std::any{};
            if (isTrue(!isEqual(symbols, std::any{})))
            {
                symbols = this->marketSymbols(symbols);
                market = this->market(::getValue(symbols, 0));
            }
            std::any type = std::string("swap");
            std::any subType = std::any{};
            std::any subTypeparamsVariable = this->handleSubTypeAndParams(std::string("fetchFundingIntervals"), market, params, std::string("linear"));
            subType = ::getValue(subTypeparamsVariable, 0);
            params = ::getValue(subTypeparamsVariable, 1);
            std::any response = std::any{};
            if (isTrue(this->isLinear(type, subType)))
            {
                response = awaitValue(this->fapiPublicGetFundingInfo(params));
            } else if (isTrue(this->isInverse(type, subType)))
            {
                response = awaitValue(this->dapiPublicGetFundingInfo(params));
            } else
            {
                throw NotSupported(toString(add(this->id, std::string(" fetchFundingIntervals() supports linear and inverse swap contracts only"))));
            }
            //
            //     [
            //         {
            //             "symbol": "BLZUSDT",
            //             "adjustedFundingRateCap": "0.03000000",
            //             "adjustedFundingRateFloor": "-0.03000000",
            //             "fundingIntervalHours": 4,
            //             "disclaimer": false
            //         },
            //     ]
            //
            return this->parseFundingRates(response, symbols);
        }).share();
    }

    /**
     * @method
     * @name binance#fetchLongShortRatioHistory
     * @description fetches the long short ratio history for a unified market symbol
     * @see https://developers.binance.com/docs/derivatives/usds-margined-futures/market-data/rest-api/Long-Short-Ratio
     * @see https://developers.binance.com/docs/derivatives/coin-margined-futures/market-data/rest-api/Long-Short-Ratio
     * @param {string} symbol unified symbol of the market to fetch the long short ratio for
     * @param {string} [timeframe] the period for the ratio, default is 24 hours
     * @param {int} [since] the earliest time in ms to fetch ratios for
     * @param {int} [limit] the maximum number of long short ratio structures to retrieve
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {int} [params.until] timestamp in ms of the latest ratio to fetch
     * @returns {object[]} an array of [long short ratio structures]{@link https://docs.ccxt.com/?id=long-short-ratio-structure}
     */
    std::shared_future<std::any> fetchLongShortRatioHistory(std::any symbol = std::any{}, std::any timeframe = std::any{}, std::any since = std::any{}, std::any limit = std::any{}, std::any params = ccxt::dict {}) override
    {
        return std::async(std::launch::deferred, [=]() mutable -> std::any {
            if (isTrue(isEqual(this->markets, std::any{})))
            {
                awaitValue(this->loadMarkets());
            }
            std::any market = this->market(symbol);
            if (isTrue(isEqual(timeframe, std::any{})))
            {
                timeframe = std::string("1d");
            }
            std::any request = ccxt::dict {
                { std::string("period"), timeframe },
            };
            std::any requestparamsVariable = this->handleUntilOption(std::string("endTime"), request, params);
            request = ::getValue(requestparamsVariable, 0);
            params = ::getValue(requestparamsVariable, 1);
            if (isTrue(!isEqual(since, std::any{})))
            {
                ::setValue(request, std::string("startTime"), since);
            }
            if (isTrue(!isEqual(limit, std::any{})))
            {
                ::setValue(request, std::string("limit"), limit);
            }
            std::any subType = std::any{};
            std::any subTypeparamsVariable = this->handleSubTypeAndParams(std::string("fetchLongShortRatioHistory"), market, params);
            subType = ::getValue(subTypeparamsVariable, 0);
            params = ::getValue(subTypeparamsVariable, 1);
            std::any response = std::any{};
            if (isTrue(isEqual(subType, std::string("linear"))))
            {
                ::setValue(request, std::string("symbol"), ::getValue(market, std::string("id")));
                response = awaitValue(this->fapiDataGetGlobalLongShortAccountRatio(this->extend(request, params)));
            } else if (isTrue(isEqual(subType, std::string("inverse"))))
            {
                ::setValue(request, std::string("pair"), ::getValue(::getValue(market, std::string("info")), std::string("pair")));
                response = awaitValue(this->dapiDataGetGlobalLongShortAccountRatio(this->extend(request, params)));
            } else
            {
                throw BadRequest(toString(add(this->id, std::string(" fetchLongShortRatioHistory() supports linear and inverse subTypes only"))));
            }
            return this->parseLongShortRatioHistory(response, market);
        }).share();
    }

    std::any parseLongShortRatio(std::any info, std::any market = std::any{}) override
    {
        //
        // linear
        //
        //     {
        //         "symbol": "BTCUSDT",
        //         "longAccount": "0.4558",
        //         "longShortRatio": "0.8376",
        //         "shortAccount": "0.5442",
        //         "timestamp": 1726790400000
        //     }
        //
        // inverse
        //
        //     {
        //         "longAccount": "0.7262",
        //         "longShortRatio": "2.6523",
        //         "shortAccount": "0.2738",
        //         "pair": "BTCUSD",
        //         "timestamp": 1726790400000
        //     }
        //
        std::any marketId = this->safeString(info, std::string("symbol"));
        std::any timestamp = this->safeIntegerOmitZero(info, std::string("timestamp"));
        return ccxt::dict {
            { std::string("info"), info },
            { std::string("symbol"), this->safeSymbol(marketId, market, std::any{}, std::string("contract")) },
            { std::string("timestamp"), timestamp },
            { std::string("datetime"), this->iso8601(timestamp) },
            { std::string("timeframe"), std::any{} },
            { std::string("longShortRatio"), this->safeNumber(info, std::string("longShortRatio")) },
        };
    }

    /**
     * @method
     * @name binance#fetchADLRank
     * @description fetches the auto deleveraging rank and risk percentage for a symbol
     * @see https://developers.binance.com/docs/derivatives/usds-margined-futures/market-data/rest-api/ADL-Risk
     * @param {string} symbol unified symbol of the market to fetch the auto deleveraging rank for
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} an [auto de leverage structure]{@link https://docs.ccxt.com/?id=auto-de-leverage-structure}
     */
    std::shared_future<std::any> fetchADLRank(std::any symbol, std::any params = ccxt::dict {}) override
    {
        return std::async(std::launch::deferred, [=]() mutable -> std::any {
            if (isTrue(isEqual(this->markets, std::any{})))
            {
                awaitValue(this->loadMarkets());
            }
            std::any market = this->market(symbol);
            std::any request = ccxt::dict {
                { std::string("symbol"), ::getValue(market, std::string("id")) },
            };
            std::any subType = std::any{};
            std::any subTypeparamsVariable = this->handleSubTypeAndParams(std::string("fetchADLRank"), market, params);
            subType = ::getValue(subTypeparamsVariable, 0);
            params = ::getValue(subTypeparamsVariable, 1);
            std::any response = std::any{};
            if (isTrue(isEqual(subType, std::string("linear"))))
            {
                response = awaitValue(this->fapiPublicGetSymbolAdlRisk(this->extend(request, params)));
            } else
            {
                throw BadRequest(toString(add(this->id, std::string(" fetchADLRank() supports linear subTypes only"))));
            }
            if (isTrue(isEqual(response, std::any{})))
            {
                throw NullResponse(toString(add(this->id, std::string(" parseADLRank() returned empty response"))));
            }
            return this->parseADLRank(response, market);
        }).share();
    }

    /**
     * @method
     * @name binance#fetchPositionsADLRank
     * @description fetches the auto deleveraging rank and risk percentage for a list of symbols that have open positions
     * @see https://developers.binance.com/docs/derivatives/usds-margined-futures/trade/rest-api/Position-ADL-Quantile-Estimation
     * @see https://developers.binance.com/docs/derivatives/coin-margined-futures/trade/rest-api/Position-ADL-Quantile-Estimation
     * @see https://developers.binance.com/docs/derivatives/portfolio-margin/trade/UM-Position-ADL-Quantile-Estimation
     * @see https://developers.binance.com/docs/derivatives/portfolio-margin/trade/CM-Position-ADL-Quantile-Estimation
     * @param {string[]} [symbols] list of unified market symbols
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {boolean} [params.portfolioMargin] set to true for the portfolio margin account
     * @returns {object[]} an array of [auto de leverage structure]{@link https://docs.ccxt.com/?id=auto-de-leverage-structure}
     */
    std::shared_future<std::any> fetchPositionsADLRank(std::any symbols = std::any{}, std::any params = ccxt::dict {}) override
    {
        return std::async(std::launch::deferred, [=]() mutable -> std::any {
            if (isTrue(isEqual(this->markets, std::any{})))
            {
                awaitValue(this->loadMarkets());
            }
            symbols = this->marketSymbols(symbols, std::any{}, true, true, true);
            std::any market = this->getMarketFromSymbols(symbols);
            std::any subType = std::any{};
            std::any subTypeparamsVariable = this->handleSubTypeAndParams(std::string("fetchPositionsADLRank"), market, params);
            subType = ::getValue(subTypeparamsVariable, 0);
            params = ::getValue(subTypeparamsVariable, 1);
            std::any isPortfolioMargin = std::any{};
            std::any isPortfolioMarginparamsVariable = this->handleOptionAndParams2(params, std::string("fetchPositionsADLRank"), std::string("papi"), std::string("portfolioMargin"), false);
            isPortfolioMargin = ::getValue(isPortfolioMarginparamsVariable, 0);
            params = ::getValue(isPortfolioMarginparamsVariable, 1);
            std::any response = std::any{};
            if (isTrue(isEqual(subType, std::string("linear"))))
            {
                if (isTrue(isPortfolioMargin))
                {
                    response = awaitValue(this->papiGetUmAdlQuantile(params));
                } else
                {
                    response = awaitValue(this->fapiPrivateGetAdlQuantile(params));
                }
            } else if (isTrue(isEqual(subType, std::string("inverse"))))
            {
                if (isTrue(isPortfolioMargin))
                {
                    response = awaitValue(this->papiGetCmAdlQuantile(params));
                } else
                {
                    response = awaitValue(this->dapiPrivateGetAdlQuantile(params));
                }
            } else
            {
                throw BadRequest(toString(add(this->id, std::string(" fetchPositionsADLRank() supports linear and inverse subTypes only"))));
            }
            //
            //     [
            //         {
            //             "symbol": "BTCUSDT",
            //             "adlQuantile": {
            //                 "LONG": 0,
            //                 "SHORT": 0,
            //                 "BOTH": 1
            //             }
            //         }
            //     ]
            //
            std::any responseList = ccxt::list{};
            if (isTrue(!isEqual(response, std::any{})))
            {
                responseList = this->toArray(response);
            }
            return this->parseADLRanks(responseList, symbols);
        }).share();
    }

    std::any parseADLRank(std::any info, std::any market = std::any{}) override
    {
        //
        // fetchADLRank
        //
        //     {
        //         "symbol": "BTCUSDT",
        //         "adlRisk": "LOW",
        //         "updateTime": 1766827800453
        //     }
        //
        // fetchPositionADLRank
        //
        //     {
        //         "symbol": "BTCUSDT",
        //         "adlQuantile": {
        //             "LONG": 0,
        //             "SHORT": 0,
        //             "BOTH": 1
        //         }
        //     }
        //
        std::any adlQuantile = this->safeDict(info, std::string("adlQuantile"), ccxt::dict {});
        std::any longNum = this->safeNumber(adlQuantile, std::string("LONG"));
        std::any shortNum = this->safeNumber(adlQuantile, std::string("SHORT"));
        std::any both = this->safeNumber(adlQuantile, std::string("BOTH"));
        std::any rank = std::any{};
        if (isTrue(!isEqual(both, std::any{})))
        {
            rank = both;
        } else
        {
            if (isTrue(isTrue(!isEqual(longNum, std::any{})) && isTrue(!isEqual(shortNum, std::any{}))))
            {
                if (isTrue(isGreaterThan(longNum, shortNum)))
                {
                    rank = longNum;
                } else
                {
                    rank = shortNum;
                }
            }
        }
        std::any marketId = this->safeString(info, std::string("symbol"));
        std::any timestamp = this->safeInteger2(info, std::string("timestamp"), std::string("updateTime"));
        return ccxt::dict {
            { std::string("info"), info },
            { std::string("symbol"), this->safeSymbol(marketId, market, std::any{}, std::string("contract")) },
            { std::string("rank"), rank },
            { std::string("rating"), this->safeStringLower(info, std::string("adlRisk")) },
            { std::string("percentage"), std::any{} },
            { std::string("timestamp"), timestamp },
            { std::string("datetime"), this->iso8601(timestamp) },
        };
    }
